/www.facebook.com/share/ZPzi2wtzTkML1CEw/?mibextid=oFDknk\r\nstart https://www.facebook.com/YousabTech?mibextid=ZbWKwL\r\nstart http://localhost/yousab-tech/public/en\r\nstart https://yousab-tech.com/webapp/public/en\r\nstart https://www.instagram.com/\r\nstart https://www.facebook.com/infinity.digital.master?mibextid\r\nstart https://www.facebook.com/solu.eg?mibextid=ZbWKwL\r\nstart https://www.facebook.com/fassla.software?mibextid=ZbWKwL\r\nstart https://www.facebook.com/markattybusiness?mibextid=ZbWKwL\r\nstart https://www.facebook.com/Diturn.net?mibextid=ZbWKwL','2024-07-17 00:57:20','2025-07-19 05:56:50',1,0),(15,'React Post','','import React, { useState } from \'react\';\r\nimport axios from \'axios\';\r\nimport { toast, ToastContainer } from \'react-toastify\';\r\nimport \'react-toastify/dist/ReactToastify.css\';\r\n\r\nconst ContactUs = () => {\r\n    const [formData, setFormData] = useState({\r\n        demo: \'\',\r\n    });\r\n    \r\n    const [errors, setErrors] = useState({\r\n        demo: \'\',\r\n    });\r\n\r\n    const handleChange = (e) => {\r\n        const { id, value } = e.target;\r\n        setFormData({ ...formData, [name]: value });\r\n    };\r\n\r\n    const handleSubmit = async (e) => {\r\n        e.preventDefault();\r\n\r\n        try {\r\n            await axios.post(\'https://yousab-tech.com/academy/public/api/message\', formData);\r\n            toast.success(\'Message sent successfully!\');\r\n            setFormData({\r\n                demo: \'\',\r\n            });\r\n            setErrors({\r\n                demo: \'\',\r\n            });\r\n        } catch (error) {\r\n            if (error.response && error.response.data && error.response.data.data) {\r\n                const apiErrors = error.response.data.data;\r\n                setErrors({\r\n                    demo: apiErrors.demo ? apiErrors.demo.join(\'\\n\') : \'\',\r\n                });\r\n                toast.error(\'Error sending message. Please check your inputs.\');\r\n            } else {\r\n                toast.error(\'Error sending message. Please try again later.\');\r\n            }\r\n        }\r\n    };\r\n\r\n    return (\r\n        <div className=\"container-fluid py-5\">\r\n            <div className=\"container py-5\">\r\n                <div className=\"text-center mb-5\">\r\n                    <h5 className=\"text-primary text-uppercase mb-3\" style={{ letterSpacing: \'5px\' }}>اتصال</h5>\r\n                    <h1>الاتصال للحصول على أي استفسار</h1>\r\n                </div>\r\n                <div className=\"row justify-content-center\">\r\n                    <div className=\"col-lg-8\">\r\n                        <div className=\"contact-form bg-secondary rounded p-5\">\r\n                            <form id=\"contactForm\" onSubmit={handleSubmit}>\r\n                                <div className=\"control-group mb-3\">\r\n                                    <input \r\n                                        type=\"text\" \r\n                                        className=\"form-control border-0 p-4\" \r\n                                        id=\"demo\" \r\n                                        name=\"demo\"\r\n                                        placeholder=\"demo\" \r\n                                        value={formData.demo}\r\n                                        onChange={handleChange}\r\n                                    />\r\n                                    <p className=\"help-block text-danger\" style={{ whiteSpace: \'pre-line\' }}>{errors.demo}</p>\r\n                                </div>\r\n                                <div className=\"text-center\">\r\n                                    <button className=\"btn btn-primary py-3 px-5\" type=\"submit\">أرسل رسالة</button>\r\n                                </div>\r\n                            </form>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <ToastContainer\r\n                position=\"top-right\"\r\n                autoClose={5000}\r\n                hideProgressBar={false}\r\n                newestOnTop={false}\r\n                closeOnClick\r\n                rtl={false}\r\n                pauseOnFocusLoss\r\n                draggable\r\n                pauseOnHover\r\n            />\r\n        </div>\r\n    );\r\n};\r\n\r\nexport default ContactUs;','2024-09-15 12:07:39','2025-07-13 05:58:06',1,0),(16,'React get','','import React, { useEffect, useState } from \'react\';\r\nimport { Link } from \'react-router-dom\';\r\n\r\nconst Courses = () => {\r\n    const [courses, setCourses] = useState([]);\r\n\r\n    // Fetching courses data from the API\r\n    useEffect(() => {\r\n        fetch(\'https://yousab-tech.com/academy/public/api/courses\')\r\n            .then((response) => response.json())\r\n            .then((data) => {\r\n                setCourses(data.data.courses);  // Assuming the courses are inside data.data.courses\r\n            })\r\n            .catch((error) => {\r\n                console.error(\'Error fetching courses:\', error);\r\n            });\r\n    }, []);\r\n\r\n    return (\r\n        <div className=\"container-fluid py-5\">\r\n            <div className=\"container py-5\">\r\n                <div className=\"text-center mb-5\">\r\n                    <h5 className=\"text-primary text-uppercase mb-3\" style={{ letterSpacing: \'5px\' }}>Courses</h5>\r\n                    <h1>Available Courses</h1>\r\n                </div>\r\n                <div className=\"row\">\r\n                    {courses.map((item) => (\r\n                        <div className=\"col-lg-4 col-md-6 mb-4\" key={item.id}>\r\n                            <div className=\"rounded overflow-hidden mb-2\">\r\n                                <img className=\"img-fluid\" src={item.image} alt={item.title} />\r\n                                <div className=\"bg-secondary p-4\">\r\n                                    <div className=\"d-flex justify-content-between mb-3\">\r\n                                        <small className=\"m-0\"><i className=\"fa fa-users text-primary mr-2\"></i>25 Students</small>\r\n                                        <small className=\"m-0\"><i className=\"far fa-clock text-primary mr-2\"></i>01h 30m</small>\r\n                                    </div>\r\n                                    <a className=\"h5\" href=\"#\">{item.title}</a>\r\n                                    <p dangerouslySetInnerHTML={{ __html: item.description }}></p>\r\n                                    <div className=\"border-top mt-4 pt-4\">\r\n                                        <div className=\"d-flex justify-content-between\">\r\n                                            <h6 className=\"m-0\"><i className=\"fa fa-star text-primary mr-2\"></i>4.5 <small>(250)</small></h6>\r\n                                        </div>\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    ))}\r\n                </div>\r\n            </div>\r\n        </div>\r\n    );\r\n};\r\n\r\nexport default Courses;','2024-09-15 12:22:53','2025-07-13 05:58:06',1,0),(17,'Ajax get','','$.ajax({\n    url: `products/${productId}`, // The route with the product ID\n    type: \'GET\',                   // HTTP method\n    success: function(response) {\n        // Handle success response\n        console.log(response);\n        // You can update your HTML here with the product data\n    },\n    error: function(xhr, status, error) {\n        // Handle error response\n        console.log(\"Error: \" + error);\n    }\n});','2024-09-20 01:15:22','2025-07-13 14:06:22',1,0),(18,'Ajax post','','$(document).ready(function() {\r\n    $(\'#contactForm\').submit(function(event) {\r\n      event.preventDefault();\r\n      var formData = $(this).serialize();\r\n      $.ajax({\r\n        type: \'POST\',\r\n        url: \'{{route(\"message.store\")}}\',\r\n        data: formData,\r\n        dataType: \'json\',\r\n        success: function(response) {\r\n          if (response.success) {\r\n            $(\'#successMsg\').text(response.message);\r\n            $(\'#contactForm\')[0].reset();\r\n          } else {\r\n            $(\'#successMsg\').text(\'\');\r\n            $.each(response.errors, function(key, value) {\r\n              $(\'#\' + key + \'Error\').text(value);\r\n            });\r\n          }\r\n        }\r\n      });\r\n    });\r\n  });','2024-09-20 01:15:31','2025-07-13 05:58:06',1,0),(19,'Server Terminal',NULL,'SELECT c.TABLE_NAME, c.COLUMN_NAME, c.DATA_TYPE, c.IS_NULLABLE, c.COLUMN_DEFAULT FROM INFORMATION_SCHEMA.COLUMNS c LEFT JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE k ON c.TABLE_NAME = k.TABLE_NAME AND c.COLUMN_NAME = k.COLUMN_NAME AND c.TABLE_SCHEMA = k.TABLE_SCHEMA WHERE c.TABLE_SCHEMA = \'aloo_test_db\' AND c.DATA_TYPE IN (\'int\', \'decimal\', \'float\', \'double\', \'bigint\', \'smallint\', \'tinyint\', \'mediumint\') AND k.COLUMN_NAME IS NULL AND c.IS_NULLABLE = \'YES\' AND c.COLUMN_NAME NOT LIKE \'%_id%\' AND c.COLUMN_NAME != \'id\';\r\n//export table\r\nmysqldump -u root -p --no-create-info aloo_test_db items > items_table_data_export.sql\r\n\r\n//export database table\r\nmysqldump -u root -p aloo_test_db > aloo_test_db_export.sql\r\n\r\n//import database table\r\nmysql -u root -p aloo < C:\\\\Users\\\\user\\\\Desktop\\\\aloo_test_db_export.sql\r\n\r\n//export database column\r\nmysqldump -u root -p aloo_test_db items > items.sql\r\n\r\n//import databasecolumn\r\nmysql -u root -p aloo items < C:\\\\Users\\\\user\\\\Desktop\\\\items_export.sql\r\n\r\n//Join methodology\r\nSELECT DISTINCT\r\n    admins.name AS admin_name,\r\n    tasks.title AS task_title,\r\n    projects.title AS project_title\r\nFROM \r\n    admins\r\nJOIN \r\n    tasks ON admins.id = tasks.employee_id\r\nJOIN \r\n    projects ON tasks.project_id = projects.id;\r\n\r\n//get structure of a table\r\nshow create table items;\r\n\r\n//show text inside file in server\r\ncat .env\r\n\r\n//show text inside file in local\r\ntype .env\r\n\r\ncd /d E:\r\ncd xampp/mysql/bin\r\nmysql -u root -p\r\nuse DBname;\r\nshow columns in tableName = desc tableName;\r\nSHOW CREATE TABLE table_name;\r\nselect * from INFORMATION_SCHEMA.TABLE_CONSTRAINTS;\r\nselect * from INFORMATION_SCHEMA.TABLE_CONSTRAINTS where table_schema=\'employment\' and table_name=\"jobs\";\r\nIMPORT DATABASE\r\nmysql -u root -p \"alogla_w\" < C:\\Users\\pc\\Desktop\\alogla\\alogla_w.sql\"\r\nALTER TABLE old_table_name RENAME new_table_name; //to rename table from cmd\r\nALTER TABLE comments change recipe_id news_id bigint();//to rename column from cmd\r\n\r\n//delete all tables in a database and should be applied in terminal when using the database want to be deleted\r\nSET FOREIGN_KEY_CHECKS = 0;\r\nSET GROUP_CONCAT_MAX_LEN=32768;\r\nSET @tables = NULL;\r\nSELECT GROUP_CONCAT(\'`\', table_name, \'`\') INTO @tables\r\nFROM information_schema.tables\r\nWHERE table_schema = \'aloo\';\r\nSET @tables = IFNULL(@tables, \'dummy\');\r\nSET @drop_statement = CONCAT(\'DROP TABLE IF EXISTS \', @tables);\r\nPREPARE stmt FROM @drop_statement;\r\nEXECUTE stmt;\r\nDEALLOCATE PREPARE stmt;\r\nSET FOREIGN_KEY_CHECKS = 1;','2024-10-29 12:17:35','2025-07-13 05:58:06',1,0),(20,'expo',NULL,'java -jar \"C:\\Users\\User\\Desktop\\generateAPK/bundletool.jar\" build-apks --bundle=C:\\Users\\User\\Desktop\\generateAPK/my_app.aab --output=C:\\Users\\User\\Desktop\\generateAPK/myapp.apks --mode=universal\r\n\r\nto upgrade exp to avoid downloading old version of expo\r\ninstall -g expo-cli\r\nexpo upgrade\r\nrm -rf node_modules package-lock.json\r\nnpm install --force','2024-10-29 14:21:32','2025-07-13 05:58:06',1,0),(21,'Recibe for a fast dashboard',NULL,'1-image compress package\n2- validate image and files less than 1 MB\n3- paginate 10 items\n','2024-11-10 02: