[\'password\']);\r\n            $input[\'type\'] = User::DOCTOR;\r\n            $input[\'language\'] = Setting::where(\'key\',\'language\')->get()->toArray()[0][\'value\'];\r\n            $doctor = User::create($input);\r\n            $doctor->assignRole(\'doctor\');\r\n            $doctor->address()->create($addressInputArray);\r\n            $createDoctor = Doctor::create([\r\n                \'availability\'=>json_encode(request()->availability),\r\n                \'services\'=>json_encode(request()->services),\r\n                \'sub_urgent_care\'=>json_encode(request()->sub_urgent_care),\r\n                \'sub_chronic_care\'=>json_encode(request()->sub_chronic_care),\r\n                \'sub_sexual_health\'=>json_encode(request()->sub_sexual_health),\r\n                \'sub_skin_and_hair\'=>json_encode(request()->sub_skin_and_hair),\r\n                \'sub_mental_health\'=>json_encode(request()->sub_mental_health),\r\n                \'sub_preventive_health\'=>json_encode(request()->sub_preventive_health),\r\n                    \'can_start\'=>request()->can_start,\r\n                    \'child_care\'=>request()->child_care,\r\n                    \'chronic_care\'=>request()->chronic_care,\r\n                    \'education\'=>request()->education,\r\n                    \'experience\'=>request()->experience,\r\n                    \'instagram_url\'=>request()->instagram_url,\r\n                    \'linkedin_url\'=>request()->linkedin_url,\r\n                    \'mental_health\'=>request()->mental_health,\r\n                    \'prefix\'=>request()->prefix,\r\n                    \'preventive_health\'=>request()->preventive_health,\r\n                    \'services_can_be_performed_online\'=>request()->services_can_be_performed_online,\r\n                    \'sexual_health\'=>request()->sexual_health,\r\n                    \'skin_and_hair\'=>request()->skin_and_hair,\r\n                    \'start_date\'=>request()->start_date,\r\n                    \'twitter_url\'=>request()->twitter_url,\r\n                    \'urgent_care\'=>request()->urgent_care,\r\n                    \'user_id\'=>$doctor->id,\r\n        ]);\r\n            $createDoctor->specializations()->sync($specialization);\r\n            if (isset($input[\'profile\']) && ! empty(\'profile\')) {\r\n                $doctor->addMedia($input[\'profile\'])->toMediaCollection(User::PROFILE, config(\'app.media_disc\'));\r\n            }\r\n\r\n            if (request()->hasFile(\'images\')) {\r\n                $files = request()->file(\'images\');\r\n                foreach ($files as $file) {\r\n                    $data[\'image\'] = $file->store(\'images\');\r\n                    $file->move(\'images\', $data[\'image\']);\r\n                    UserFile::create([\'path\' => $data[\'image\'],\'user_id\'=>$createDoctor->id]);\r\n                }\r\n            }   \r\n            if (request()->has(\'delimages\')) {\r\n                foreach (request()->delimages as $id) {\r\n                    $image = UserFile::find($id);\r\n                    if(file_exists($image->path))\r\n                      File::delete($image->path);\r\n                    if(isset($image->path))\r\n                      $image->delete();\r\n                }\r\n            } \r\n            // $doctor->sendEmailVerificationNotification();\r\n\r\n            \r\n\r\n            DB::commit();\r\n\r\n            return $doctor;\r\n        } catch (\\Exception $e) {\r\n            throw new UnprocessableEntityHttpException($e->getMessage());\r\n        }\r\n    }\r\n\r\n    public function update($input, $doctor)\r\n    {\r\n        $addressInputArray = Arr::only($input,\r\n            [\'address1\', \'address2\', \'city_id\', \'state_id\', \'country_id\', \'postal_code\']);\r\n        $doctorArray = Arr::only($input, [\'experience\', \'twitter_url\', \'linkedin_url\', \'instagram_url\']);\r\n        $qualificationArray = json_decode($input[\'qualifications\'], true);\r\n        $specialization = $input[\'specializations\'];\r\n        try {\r\n            DB::beginTransaction();\r\n            $input[\'email\'] = setEmailLowerCase($input[\'email\']);\r\n            $input[\'status\'] = (isset($input[\'status\'])) ? 1 : 0;\r\n            $input[\'type\'] = User::DOCTOR;\r\n            $doctor->user->update($input);\r\n\r\n            $doctor->user->address()->update($addressInputArray);\r\n            $doctor->update([\r\n                \'availability\'=>json_encode(request()->availability),\r\n                \'services\'=>json_encode(request()->services),\r\n                \'sub_urgent_care\'=>json_encode(request()->sub_urgent_care),\r\n                \'sub_chronic_care\'=>json_encode(request()->sub_chronic_care),\r\n                \'sub_sexual_health\'=>json_encode(request()->sub_sexual_health),\r\n                \'sub_skin_and_hair\'=>json_encode(request()->sub_skin_and_hair),\r\n                \'sub_mental_health\'=>json_encode(request()->sub_mental_health),\r\n                \'sub_preventive_health\'=>json_encode(request()->sub_preventive_health),\r\n                \'can_start\'=>request()->can_start,\r\n                \'child_care\'=>request()->child_care,\r\n                \'chronic_care\'=>request()->chronic_care,\r\n                \'education\'=>request()->education,\r\n                \'experience\'=>request()->experience,\r\n                \'instagram_url\'=>request()->instagram_url,\r\n                \'linkedin_url\'=>request()->linkedin_url,\r\n                \'mental_health\'=>request()->mental_health,\r\n                \'prefix\'=>request()->prefix,\r\n                \'preventive_health\'=>request()->preventive_health,\r\n                \'services_can_be_performed_online\'=>request()->services_can_be_performed_online,\r\n                \'sexual_health\'=>request()->sexual_health,\r\n                \'skin_and_hair\'=>request()->skin_and_hair,\r\n                \'start_date\'=>request()->start_date,\r\n                \'twitter_url\'=>request()->twitter_url,\r\n                \'urgent_care\'=>request()->urgent_care,\r\n\r\n        ]);\r\n\r\n            $doctor->specializations()->sync($specialization);\r\n\r\n            if (count($qualificationArray) >= 0) {\r\n                if (isset($input[\'deletedQualifications\'])) {\r\n                    Qualification::whereIn(\'id\', explode(\',\', $input[\'deletedQualifications\']))->delete();\r\n                }\r\n\r\n                foreach ($qualificationArray as $qualifications) {\r\n                    if ($qualifications == null) {\r\n                        continue;\r\n                    }\r\n                    if (isset($qualifications[\'id\'])) {\r\n                        $doctor->user->qualifications()->where(\'id\', $qualifications[\'id\'])->update($qualifications);\r\n                    } else {\r\n                        unset($qualifications[\'id\']);\r\n                        $doctor->user->qualifications()->create($qualifications);\r\n                    }\r\n                }\r\n            }\r\n\r\n            if (isset($input[\'profile\']) && ! empty(\'profile\')) {\r\n                $doctor->user->clearMediaCollection(User::PROFILE);\r\n                $doctor->user->media()->delete();\r\n                $doctor->user->addMedia($input[\'profile\'])->toMediaCollection(User::PROFILE, config(\'app.media_disc\'));\r\n            }\r\n\r\n            if (request()->hasFile(\'images\')) {\r\n                $files = request()->file(\'images\');\r\n                foreach ($files as $file) {\r\n                    $data[\'image\'] = $file->store(\'images\');\r\n                    $file->move(\'images\', $data[\'image\']);\r\n                    UserFile::create([\'path\' => $data[\'image\'],\'user_id\'=>$doctor->user->id]);\r\n                }\r\n            }   \r\n            if (request()->has(\'delimages\')) {\r\n                foreach (request()->delimages as $id) {\r\n                    $image = UserFile::find($id);\r\n                    if(file_exists($image->path))\r\n                      File::delete($image->path);\r\n                    if(isset($image->path))\r\n                      $image->delete();\r\n                }\r\n            } \r\n            DB::commit();\r\n\r\n            return $doctor;\r\n        } catch (\\Exception $e) {\r\n            throw new UnprocessableEntityHttpException($e->getMessage());\r\n        }\r\n    }\r\n\r\n    public function updateProfile(array $userInput): bool\r\n    {\r\n        try {\r\n          \r\n            DB::beginTransaction();\r\n\r\n            $user = Auth::user();\r\n            if(auth()->user()->role_name==\'Patient\'){\r\n                $patient =  Patient::where(\'user_id\',$user->id)->first();\r\n    \r\n                $addressInputArray = Arr::only($userInput,\r\n                    [\'address1\', \'address2\', \'city_id\', \'state_id\', \'country_id\', \'postal_code\']);\r\n                $userInput[\'type\'] = User::PATIENT;\r\n                $userInput[\'email\'] = setEmailLowerCase($userInput[\'email\']);\r\n                /** @var Patient $patient */\r\n                \r\n                $patient->user()->update(Arr::except($userInput, [\r\n                    \'address1\', \'address2\', \'city_id\', \'state_id\', \'country_id\', \'postal_code\', \'patient_unique_id\',\r\n                    \'avatar_remove\',\r\n                    \'profile\', \'is_edit\', \'edit_patient_country_id\', \'edit_patient_state_id\', \'edit_patient_city_id\',\r\n                    \'backgroundImg\',\r\n                ]));\r\n                \r\n    \r\n                if(isset($patient->address)){\r\n                    $patient->address()->update($addressInputArray);\r\n                }else{\r\n                    $patient->address()->create($addressInputArray);\r\n                }\r\n    \r\n                if ((getLogInUser()->hasRole(\'patient\'))) {\r\n                    if (! empty($userInput[\'image\'])) {\r\n                        $user->clearMediaCollection(Patient::PROFILE);\r\n                        $user->patient->media()->delete();\r\n                        $user->patient->addMedia($userInput[\'image\'])->toMediaCollection(Patient::PROFILE,\r\n                            config(\'app.media_disc\'));\r\n                    }\r\n                } else {\r\n                    if ((! empty($userInput[\'image\']))) {\r\n                        $user->clearMediaCollection(User::PROFILE);\r\n                        $user->media()->delete();\r\n                        $user->addMedia($userInput[\'image\'])->toMediaCollection(User::PROFILE, config(\'app.media_disc\'));\r\n                    }\r\n                }\r\n            }else if(auth()->user()->role_name==\'Doctor\'){\r\n       \r\n\r\n                $doctor =  Doctor::where(\'user_id\',$user->id)->first();\r\n    \r\n    \r\n                $addressInputArray = Arr::only($userInput,\r\n                    [\'address1\', \'address2\', \'city_id\', \'state_id\', \'country_id\', \'postal_code\']);\r\n                $userInput[\'type\'] = User::DOCTOR;\r\n                $userInput[\'email\'] = setEmailLowerCase($userInput[\'email\']);\r\n                /** @var Doctor $doctor */\r\n                \r\n                $doctor->user()->update([\r\n                    \'first_name\'=>request()->first_name,\r\n                    \'last_name\'=>request()->last_name,\r\n                    \'email\'=>request()->email,\r\n                    \'contact\'=>request()->contact,\r\n                    \'dob\'=>request()->dob,\r\n                    \'gender\'=>request()->gender,\r\n                    \'language\'=>request()->language,\r\n                    \'blood_group\'=>request()->blood_group,\r\n                    \'type\'=>request()->type,\r\n                    \'region_code\'=>request()->region_code,\r\n                    \'time_zone\'=>request()->time_zone,\r\n                    \'dark_mode\'=>request()->dark_mode,\r\n                    \r\n                ]);\r\n\r\n                $doctor->update([\r\n                    \'availability\'=>json_encode(request()->availability),\r\n                    \'services\'=>json_encode(request()->services),\r\n                    \'sub_urgent_care\'=>json_encode(request()->sub_urgent_care),\r\n                    \'sub_chronic_care\'=>json_encode(request()->sub_chronic_care),\r\n                    \'sub_sexual_health\'=>json_encode(request()->sub_sexual_health),\r\n                    \'sub_skin_and_hair\'=>json_encode(request()->sub_skin_and_hair),\r\n                    \'sub_mental_health\'=>json_encode(request()->sub_mental_health),\r\n                    \'sub_preventive_health\'=>json_encode(request()->sub_preventive_health),\r\n                    \'can_start\'=>request()->can_start,\r\n                    \'child_care\'=>request()->child_care,\r\n                    \'chronic_care\'=>request()->chronic_care,\r\n                    \'education\'=>request()->education,\r\n                    \'experience\'=>request()->experience,\r\n                    \'instagram_url\'=>request()->instagram_url,\r\n                    \'linkedin_url\'=>request()->linkedin_url,\r\n                    \'mental_health\'=>request()->mental_health,\r\n                    \'prefix\'=>request()->prefix,\r\n                    \'preventive_health\'=>request()->preventive_health,\r\n                    \'services_can_be_performed_online\'=>request()->services_can_be_performed_online,\r\n                    \'sexual_health\'=>request()->sexual_health,\r\n                    \'skin_and_hair\'=>request()->skin_and_hair,\r\n                    \'start_date\'=>request()->start_date,\r\n                    \'twitter_url\'=>request()->twitter_url,\r\n                    \'urgent_care\'=>request()->urgent_care,\r\n    \r\n            ]);\r\n                \r\n    \r\n\r\n    \r\n                if ((getLogInUser()->hasRole(\'doctor\'))) {\r\n                    if (! empty($userInput[\'image\'])) {\r\n                        $user->clearMediaCollection(Doctor::PROFILE);\r\n                        $user->doctor->media()->delete();\r\n                        $user->doctor->addMedia($userInput[\'image\'])->toMediaCollection(Doctor::PROFILE,\r\n                            config(\'app.media_disc\'));\r\n                    }\r\n                } else {\r\n                    if ((! empty($userInput[\'image\']))) {\r\n                        $user->clearMediaCollection(User::PROFILE);\r\n                        $user->media()->delete();\r\n                        $user->addMedia($userInput[\'image\'])->toMediaCollection(User::PROFILE, config(\'app.media_disc\'));\r\n                    }\r\n                }\r\n            }\r\n\r\n            DB::commit();\r\n\r\n            return true;\r\n        } catch (\\Exception $e) {\r\n            DB::rollBack();\r\n\r\n            throw new UnprocessableEntityHttpException($e->getMessage());\r\n        }\r\n    }\r\n\r\n    /**\r\n     * @return mixed\r\n     */\r\n    public function getSpecializationsData($doctor)\r\n    {\r\n        $data[\'specializations\'] = Specialization::pluck(\'name\', \'id\')->toArray();\r\n        $data[\'doctorSpecializations\'] = $doctor->specializations()->pluck(\'specialization_id\')->toArray();\r\n        $data[\'countryId\'] = $doctor->user->address()->pluck(\'country_id\');\r\n        $data[\'stateId\'] = $doctor->user->address()->pluck(\'state_id\');\r\n\r\n        return $data;\r\n    }\r\n\r\n    /**\r\n     * @return mixed\r\n     */\r\n    public function getCountries()\r\n    {\r\n        $countries = Country::pluck(\'name\', \'id\');\r\n\r\n        return $countries;\r\n    }\r\n\r\n    public function addQualification($input)\r\n    {\r\n        $input[\'user_id\'] = $input[\'id\'];\r\n        $qualification = Qualification::create($input);\r\n\r\n        return $qualification;\r\n    }\r\n\r\n    /**\r\n     * @throws \\Exception\r\n     */\r\n    public function doctorDetail($input): array\r\n    {\r\n        $todayDate = Carbon::now()->format(\'Y-m-d\');\r\n        $doctor[\'data\'] = Doctor::with([\'user.address\', \'specializations\', \'appointments.patient.user\'])->whereId($input->id)->first();\r\n        $doctor[\'doctorSession\'] = DoctorSession::whereDoctorId($input->id)->get();\r\n        //        $doctor[\'appointments\'] = DataTables::of((new UserDataTable())->getAppointment($input->id))->make(true);\r\n        $doctor[\'appointmentStatus\'] = Appointment::ALL_STATUS;\r\n        $doctor[\'totalAppointmentCount\'] = Appointment::whereDoctorId($input->id)->count();\r\n        $doctor[\'todayAppointmentCount\'] = Appointment::whereDoctorId($input->id)->where(\'date\', \'=\',\r\n            $todayDate)->count();\r\n        $doctor[\'upcomingAppointmentCount\'] = Appointment::whereDoctorId($input->id)->where(\'date\', \'>\',\r\n            $todayDate)->count();\r\n\r\n        return $doctor;\r\n    }\r\n}\r\n\r\nE:\\xampp\\htdocs\\instadoctorz\\app\\Http\\Controllers\\UserController.php\r\n<?php\r\n\r\nnamespace App\\Http\\Controllers;\r\n\r\nuse App\\DataTable\\UserDataTable;\r\nuse App\\Http\\Requests\\CreateQualificationRequest;\r\nuse App\\Http\\Requests\\CreateUserRequest;\r\nuse App\\Http\\Requests\\UpdateChangePasswordRequest;\r\nuse App\\Http\\Requests\\UpdateUserProfileRequest;\r\nuse App\\Http\\Requests\\UpdateUserRequest;\r\nuse App\\Models\\Appointment;\r\nuse App\\Models\\Doctor;\r\nuse App\\Models\\DoctorSession;\r\nuse App\\Models\\Specialization;\r\nuse App\\Models\\User;\r\nuse App\\Models\\Visit;\r\nuse App\\Repositories\\UserRepository;\r\nuse Carbon\\Carbon;\r\nuse DB;\r\nuse Exception;\r\nuse Illuminate\\Contracts\\Foundation\\Application;\r\nuse Illuminate\\Contracts\\View\\Factory;\r\nuse Illuminate\\Contracts\\View\\View;\r\nuse Illuminate\\Http\\JsonResponse;\r\nuse Illuminate\\Http\\RedirectResponse;\r\nuse Illuminate\\Http\\Request;\r\nuse Illuminate\\Routing\\Redirector;\r\nuse Illuminate\\Support\\Facades\\Auth;\r\nuse Illuminate\\Support\\Facades\\Hash;\r\nuse Laracasts\\Flash\\Flash;\r\nuse Symfony\\Component\\HttpKernel\\Exception\\UnprocessableEntityHttpException;\r\nuse Yajra\\DataTables\\DataTables;\r\nuse App\\Models\\Patient;\r\nuse App\\Models\\UserFile;\r\nuse Arr;\r\nuse Illuminate\\Support\\Facades\\File;\r\nclass UserController extends AppBaseController\r\n{\r\n    /**\r\n     * @var UserRepository\r\n     */\r\n    public $userRepo;\r\n\r\n    /**\r\n     * UserController constructor.\r\n     */\r\n    public function __construct(UserRepository $userRepository)\r\n    {\r\n        $this->userRepo = $userRepository;\r\n    }\r\n\r\n    /**\r\n     * Display a listing of the resource.\r\n     *\r\n     * @return Application|Factory|View\r\n     *\r\n     * @throws Exception\r\n     */\r\n    public function index(Request $request): \\Illuminate\\View\\View\r\n    {\r\n        $years = [];\r\n        $currentYear = Carbon::now()->format(\'Y\');\r\n        for ($year = 1960; $year <= $currentYear; $year++) {\r\n            $years[$year] = $year;\r\n        }\r\n\r\n        $status = User::STATUS;\r\n\r\n        return view(\'doctors.index\', compact(\'years\', \'status\'));\r\n    }\r\n\r\n    /**\r\n     * Show the form for creating a new resource.\r\n     *\r\n     * @return Application|Factory|View\r\n     */\r\n    public function create(): \\Illuminate\\View\\View\r\n    {\r\n        $specializations = Specialization::pluck(\'name\', \'id\')->toArray();\r\n        $country = $this->userRepo->getCountries();\r\n        $bloodGroup = Doctor::BLOOD_GROUP_ARRAY;\r\n        $prefixdata=[\r\n            \'Mr\' => \'Mr\',\'Mrs\' => \'Mrs\',\'Ms\' => \'Ms\',\'Mx\' => \'Mx\',\'Miss\' => \'Miss\',\'Dr\' => \'Dr\',\'Prof\' => \'Prof\'\r\n        ];\r\n        $educationdata=[\r\n                    \'Bachelor\' => \'Bachelor\',\r\n                    \'Diploma\' => \'Diploma\',\r\n                    \"Master\'s degree\" => \"Master\'s degree\",\r\n                    \'PHD\' => \'PHD\',\r\n                    \'Other\' => \'Other\',\r\n                    ];\r\n\r\n        return view(\'doctors.create\', compact(\'specializations\', \'country\', \'bloodGroup\',\'prefixdata\',\'educationdata\'));\r\n    }\r\n\r\n    /**\r\n     * Store a newly created resource in storage.\r\n     *\r\n     * @return Application|RedirectResponse|Redirector\r\n     */\r\n    public function store(CreateUserRequest $request): RedirectResponse\r\n    {\r\n        $input = $request->all();\r\n        $this->userRepo->store($input);\r\n\r\n \r\n\r\n        Flash::success(__(\'messages.flash.doctor_create\'));\r\n\r\n        return redirect(route(\'doctors.index\'));\r\n    }\r\n\r\n    /**\r\n     * @return Application|Factory|View|RedirectResponse\r\n     *\r\n     * @throws Exception\r\n     */\r\n    public function show(Doctor $doctor)\r\n    {\r\n        if (getLogInUser()->hasRole(\'patient\')) {\r\n            $doctorAppointment = Appointment::whereDoctorId($doctor->id)->wherePatientId(getLogInUser()->patient->id);\r\n            if (! $doctorAppointment->exists()) {\r\n                return redirect()->back();\r\n            }\r\n        }\r\n\r\n        $doctorDetailData = $this->userRepo->doctorDetail($doctor);\r\n\r\n        return view(\'doctors.show\', compact(\'doctor\', \'doctorDetailData\'));\r\n    }\r\n\r\n    /**\r\n     * Show the form for editing the specified resource.\r\n     *\r\n     * @return Application|Factory|View\r\n     */\r\n    public function edit(Doctor $doctor): \\Illuminate\\View\\View\r\n    {\r\n        $user = $doctor->user()->first();\r\n        $qualifications = $user->qualifications()->get();\r\n        $data = $this->userRepo->getSpecializationsData($doctor);\r\n        $bloodGroup = Doctor::BLOOD_GROUP_ARRAY;\r\n        $countries = $this->userRepo->getCountries();\r\n        $state = $cities = null;\r\n        $years = [];\r\n        $currentYear = Carbon::now()->format(\'Y\');\r\n        for ($year = 1960; $year <= $currentYear; $year++) {\r\n            $years[$year] = $year;\r\n        }\r\n        if (isset($countryId)) {\r\n            $state = getStates($data[\'countryId\']->toArray());\r\n        }\r\n        if (isset($stateId)) {\r\n            $cities = getCities($data[\'stateId\']->toArray());\r\n        }\r\n\r\n        $images=$doctor->user->images;\r\n\r\n        return view(\'doctors.edit\',\r\n            compact(\'user\', \'qualifications\', \'data\', \'doctor\', \'countries\', \'state\', \'cities\', \'years\', \'bloodGroup\',\'images\'));\r\n    }\r\n\r\n    /**\r\n     * Update the specified resource in storage.\r\n     */\r\n    public function update(UpdateUserRequest $request, Doctor $doctor): JsonResponse\r\n    {\r\n        $input = $request->all();\r\n        $this->userRepo->update($input, $doctor);\r\n\r\n\r\n        Flash::success(__(\'messages.flash.doctor_update\'));\r\n\r\n        return $this->sendSuccess(__(\'messages.flash.doctor_update\'));\r\n    }\r\n\r\n    /**\r\n     * Remove the specified resource from storage.\r\n     */\r\n    public function destroy(Doctor $doctor): JsonResponse\r\n    {\r\n        $existAppointment = Appointment::whereDoctorId($doctor->id)->exists();\r\n        $existVisit = Visit::whereDoctorId($doctor->id)->exists();\r\n\r\n        if ($existAppointment || $existVisit) {\r\n            return $this->sendError(__(\'messages.flash.doctor_use\'));\r\n        }\r\n\r\n        try {\r\n            DB::beginTransaction();\r\n            $doctor->user->delete();\r\n            $doctor->user->media()->delete();\r\n            $doctor->user->address()->delete();\r\n            $doctor->user->doctor()->delete();\r\n            DB::commit();\r\n\r\n            return $this->sendSuccess(__(\'messages.flash.doctor_delete\'));\r\n        } catch (Exception $e) {\r\n            throw new UnprocessableEntityHttpException($e->getMessage());\r\n        }\r\n    }\r\n\r\n    /**\r\n     * @return Application|Factory|View\r\n     */\r\n    public function editProfile(): \\Illuminate\\View\\View\r\n    {\r\n        $user = Auth::user();\r\n        if(auth()->user()->role_name==\'Doctor\')\r\n        $patient =  Doctor::where(\'user_id\',$user->id)->first();\r\n        else\r\n        $patient =  Patient::where(\'user_id\',$user->id)->first();\r\n        $data = $this->userRepo->getData();\r\n        $prefixdata=[\r\n            \'Mr\' => \'Mr\',\'Mrs\' => \'Mrs\',\'Ms\' => \'Ms\',\'Mx\' => \'Mx\',\'Miss\' => \'Miss\',\'Dr\' => \'Dr\',\'Prof\' => \'Prof\'\r\n        ];\r\n        $educationdata=[\r\n                    \'Bachelor\' => \'Bachelor\',\r\n                    \'Diploma\' => \'Diploma\',\r\n                    \"Master\'s degree\" => \"Master\'s degree\",\r\n                    \'PHD\' => \'PHD\',\r\n                    \'Other\' => \'Other\',\r\n                    ];\r\n        $bloodGroup = Doctor::BLOOD_GROUP_ARRAY;\r\n\r\n        return view(\'profile.index\', compact(\'user\',\'data\',\'patient\',\'prefixdata\',\'educationdata\',\'bloodGroup\'));\r\n    }\r\n\r\n    public function updateProfile(UpdateUserProfileRequest $request): RedirectResponse\r\n    {\r\n        $input = Arr::except($request->all(), [\'_token\',\'_method\']);\r\n        $this->userRepo->updateProfile($input);\r\n        Flash::success(__(\'messages.flash.user_profile_update\'));\r\n\r\n        return redirect(route(\'profile.setting\'));\r\n    }\r\n\r\n    public function changePassword(UpdateChangePasswordRequest $request): JsonResponse\r\n    {\r\n        $input = $request->all();\r\n\r\n        try {\r\n            /** @var User $user */\r\n            $user = Auth::user();\r\n            if (! Hash::check($input[\'current_password\'], $user->password)) {\r\n                return $this->sendError(__(\'messages.flash.current_invalid\'));\r\n            }\r\n            $input[\'password\'] = Hash::make($input[\'new_password\']);\r\n            $user->update($input);\r\n\r\n            return $this->sendSuccess(__(\'messages.flash.password_update\'));\r\n        } catch (Exception $e) {\r\n            throw new UnprocessableEntityHttpException($e->getMessage());\r\n        }\r\n    }\r\n\r\n    public function getStates(Request $request): JsonResponse\r\n    {\r\n        $countryId = $request->data;\r\n        $states = getStates($countryId);\r\n\r\n        return $this->sendResponse($states, __(\'messages.flash.retrieve\'));\r\n    }\r\n\r\n    public function getCity(Request $request): JsonResponse\r\n    {\r\n        $state = $request->state;\r\n        $cities = getCities($state);\r\n\r\n        return $this->sendResponse($cities, __(\'messages.flash.retrieve\'));\r\n    }\r\n\r\n    /**\r\n     * @return mixed\r\n     */\r\n    public function sessionData(Request $request)\r\n    {\r\n        $doctorSession = DoctorSession::whereDoctorId($request->doctorId)->first();\r\n\r\n        return $this->sendResponse($doctorSession, __(\'messages.flash.session_retrieve\'));\r\n    }\r\n\r\n    /**\r\n     * @return mixed\r\n     */\r\n    public function addQualification(CreateQualificationRequest $request, Doctor $doctor)\r\n    {\r\n        $this->userRepo->addQualification($request->all());\r\n\r\n        return $this->sendSuccess(__(\'messages.flash.qualification_create\'));\r\n    }\r\n\r\n    /**\r\n     * @return Application|RedirectResponse|Redirector\r\n     *\r\n     * @throws Exception\r\n     */\r\n    public function doctorAppointment(Doctor $doctor, Request $request)\r\n    {\r\n        if ($request->ajax()) {\r\n            return DataTables::of((new UserDataTable())->getAppointment($request->only([\r\n                \'status\', \'doctorId\', \'filter_date\',\r\n            ])))->make(true);\r\n        }\r\n\r\n        return redirect(route(\'doctors.index\'));\r\n    }\r\n\r\n    public function changeDoctorStatus(Request $request): JsonResponse\r\n    {\r\n        $doctor = User::findOrFail($request->id);\r\n        $doctor->update([\'status\' => ! $doctor->status]);\r\n\r\n        return $this->sendResponse($doctor, __(\'messages.flash.status_update\'));\r\n    }\r\n\r\n    public function updateLanguage(Request $request): JsonResponse\r\n    {\r\n        $language = $request->get(\'language\');\r\n\r\n        $user = getLogInUser();\r\n        $user->update([\'language\' => $language]);\r\n\r\n        return $this->sendSuccess(__(\'messages.flash.language_update\'));\r\n    }\r\n\r\n    public function impersonate(int $id): RedirectResponse\r\n    {\r\n        $user = User::findOrFail($id);\r\n        getLogInUser()->impersonate($user);\r\n        if ($user->hasRole(\'doctor\')) {\r\n            return redirect()->route(\'doctors.dashboard\');\r\n        } elseif ($user->hasRole(\'patient\')) {\r\n            return redirect()->route(\'patients.dashboard\');\r\n        }\r\n\r\n        return redirect()->route(\'admin.dashboard\');\r\n    }\r\n\r\n    public function impersonateLeave(): RedirectResponse\r\n    {\r\n        getLogInUser()->leaveImpersonation();\r\n\r\n        return redirect()->route(\'admin.dashboard\');\r\n    }\r\n\r\n    public function emailVerified(Request $request): JsonResponse\r\n    {\r\n        $user = User::findOrFail($request->id);\r\n        if ($request->value) {\r\n            $user->update([\r\n                \'email_verified_at\' => Carbon::now(),\r\n            ]);\r\n        } else {\r\n            $user->update([\r\n                \'email_verified_at\' => null,\r\n            ]);\r\n        }\r\n\r\n        return $this->sendResponse($user, __(\'messages.flash.verified_email\'));\r\n    }\r\n\r\n    public function emailNotification(Request $request): JsonResponse\r\n    {\r\n        $input = $request->all();\r\n        $user = getLogInUser();\r\n        $user->update([\r\n            \'email_notification\' => isset($input[\'email_notification\']) ? $input[\'email_notification\'] : 0,\r\n        ]);\r\n\r\n        return $this->sendResponse($user, __(\'messages.flash.email_notification\'));\r\n    }\r\n\r\n    public function resendEmailVerification($userId): JsonResponse\r\n    {\r\n        $user = User::findOrFail($userId);\r\n        if ($user->hasVerifiedEmail()) {\r\n            return $this->sendError(__(\'messages.flash.user_already_verified\'));\r\n        }\r\n\r\n        $user->sendEmailVerificationNotification();\r\n\r\n        return $this->sendSuccess(__(\'messages.flash.notification_send\'));\r\n    }\r\n\r\n    public function updateDarkMode(): JsonResponse\r\n    {\r\n        $user = Auth::user();\r\n        app()->setLocale($user->language);\r\n        $darkEnabled = $user->dark_mode == true;\r\n        $user->update([\r\n            \'dark_mode\' => ! $darkEnabled,\r\n        ]);\r\n\r\n        return $this->sendSuccess(__(\'messages.flash.theme_change\'));\r\n    }\r\n}\r\n\r\n\r\n\r\nTo active all routes that has product active in depth\r\n{{ request()->routeIs(\'*product*\') ? \'active\' : \'\' }}\r\n\r\n\r\nAdd return back button very easily to breadcrumb mid elements using javascript\r\n@if (isset($mid))\r\n<a class=\"btn btn-primary py-md-2 px-md-3 me-3\" onclick=\"history.back()\">\r\n<li class=\"breadcrumb-item active mb-2 -3\">{{ $mid }}</li>\r\n</a>\r\n@endif\r\n.htaccess in laravel\r\n<IfModule mod_rewrite.c>\r\n    <IfModule mod_negotiation.c>\r\n        Options -MultiViews -Indexes\r\n    </IfModule>\r\n\r\n    RewriteEngine On\r\n    #remove public from url\r\n    RewriteCond %{REQUEST_URI} !^/public/\r\n    RewriteRule ^(.*)$ /public/$1 [L,QSA]\r\n\r\n    # Handle Authorization Header\r\n    RewriteCond %{HTTP:Authorization} .\r\n    RewriteRule .* - [E=HTTP_AUTHORIZATION:%{HTTP:Authorization}]\r\n\r\n    # Redirect Trailing Slashes If Not A Folder...\r\n    RewriteCond %{REQUEST_FILENAME} !-d\r\n    RewriteCond %{REQUEST_URI} (.+)/$\r\n    RewriteRule ^ %1 [L,R=301]\r\n\r\n    # Send Requests To Front Controller...\r\n    RewriteCond %{REQUEST_FILENAME} !-d\r\n    RewriteCond %{REQUEST_FILENAME} !-f\r\n    RewriteRule ^ index.php [L]\r\n</IfModule>\r\n\r\n\r\nClass+$loop->index and attribute index={{$loop->index}} Methodology (Jquery)\r\nAdd attribute index to element which has the event and add class name with keyword+index \r\nNote index here is $loop->index\r\nSearch for $loop in this piece of code to understand\r\n<td class=\"quantity\">\r\n<h4 class=\"table-title text-content\">{{ __(\'general.quantity\') }}</h4>\r\n<div class=\"quantity-price\">\r\n<div class=\"cart_qty\">\r\n<div class=\"input-group\">\r\n<button type=\"button\" class=\"btn qty-left-minus\"\r\ndata-type=\"minus\" data-field=\"\">\r\n<i class=\"fa fa-minus\" aria-hidden=\"true\"></i>\r\n</button>\r\n<input class=\"form-control input-number qty-input itemCount\"\r\ntype=\"text\" name=\"itemCount\"\r\nvalue=\"{{ $item->get(\'quantity\') }}\" price=\"{{ $item->get(\'price\') }}\"\r\nhash=\"{{ $item->getHash() }}\" index=\"{{ $loop->index }}\">\r\n<button type=\"button\" class=\"btn qty-right-plus\"\r\ndata-type=\"plus\" data-field=\"\">\r\n<i class=\"fa fa-plus\" aria-hidden=\"true\"></i>\r\n</button>\r\n</div>\r\n</div>\r\n</div>\r\n</td>\r\n\r\n<td class=\"subtotal\">\r\n<h4 class=\"table-title text-content\">{{ __(\'general.total\') }}</h4>\r\n<h5 class=\"single-total{{ $loop->index }}\">${{$item->get(\'price\') * $item->get(\'quantity\')}}</h5>\r\n</td>\r\n\r\n\r\n\r\n\r\nHow to paginate in eloquent relation\r\n$products = $subcategory->products()->paginate(8);\r\n\r\ntrim in php\r\n echo trim($str,\"Hed!\");\r\n\r\nhow to get user ip\r\nrequest()->ip()\r\nFont awesome spinner\r\n<i class=\"fa fa-spinner fa-spin d-none\"></i>\r\nOld value to select option\r\n<select name=\"version\">\r\n    @foreach ($product->versions as $version)\r\n        <option value=\"{{ $version }}\" @selected(old(\'gender\',$admin->gende)==\'male\'?true:false)\r\n>\r\n            {{ $version }}\r\n        </option>\r\n    @endforeach\r\n</select>\r\n\r\nHow to use cart package\r\n<?php\r\n\r\nnamespace App\\Http\\Controllers;\r\n\r\nuse App\\Models\\Painting;\r\nuse Exception;\r\nuse Jackiedo\\Cart\\Cart;\r\nuse Illuminate\\Http\\Request;\r\n\r\nclass CartController extends Controller\r\n{\r\n    public $cart, $painting, $favorite;\r\n    public function __construct(Cart $cart, Painting $painting)\r\n    {\r\n        $this->cart = $cart->name(\'shopping\')->useForCommercial();\r\n        $this->favorite = $this->cart->newInstance(\'favorites\')->useForCommercial(false);\r\n        $this->painting = $painting;\r\n    }\r\n    /**\r\n     * Display a listing of the resource.\r\n     *\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n\r\n\r\n    public function getCartItems()\r\n    {\r\n        $items = $this->cart->getItems();\r\n        return view(\'front.cart\', compact(\'items\'));\r\n    }\r\n\r\n    public function getFavourites()\r\n    {\r\n        $items = $this->favorite->getItems();\r\n        return view(\'front.favourite\', compact(\'items\'));\r\n    }\r\n\r\n    public function addToCart($id)\r\n    {\r\n        try {\r\n            $painting = $this->painting->findorfail($id);\r\n            $this->cart->addItem([\'model\' => $painting, \'price\' => $painting->price]);\r\n            return redirect()->back();\r\n        } catch (Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(dd($e->getMessage()))]);\r\n        }\r\n    }\r\n\r\n    public function addToFavourite($id)\r\n    {\r\n        try {\r\n            $painting = $this->painting->findorfail($id);\r\n            $this->favorite->addItem([\'model\' => $painting, \'price\' => $painting->price]);\r\n            return redirect()->back();\r\n        } catch (Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(dd($e->getMessage()))]);\r\n        }\r\n    }\r\n\r\n    public function removeItemCart($hash)\r\n    {\r\n        try {\r\n            $this->cart->removeItem($hash);\r\n            return redirect()->back();\r\n        } catch (Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(dd($e->getMessage()))]);\r\n        }\r\n    }\r\n\r\n    public function removeItemFavourite($hash)\r\n    {\r\n        try {\r\n            $this->favorite->removeItem($hash);\r\n            return redirect()->back();\r\n        } catch (Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(dd($e->getMessage()))]);\r\n        }\r\n    }\r\n}\r\n\r\n\r\n\r\n\r\nPhone Validation\r\n\'phone\' => \'nullable|string|regex:/^[0-9+]+/|min:6|max:30\',\r\nMail attachment using ajax\r\n<!-- Start Contact -->\r\n<section class=\"contact-section\">\r\n    <div class=\"container\">\r\n        <div class=\"row\">\r\n            <div class=\"col-md-6 col-sm-6\">\r\n                <div class=\"success text-center alert alert-success alert-dismissible fade show d-none\" role=\"alert\">\r\n                </div>\r\n                <div class=\"error text-center alert alert-danger alert-dismissible fade show d-none\" role=\"alert\">\r\n                </div>\r\n                <div class=\"getin_form\">\r\n                    <h2>{{ page(\'contract-request-page\')->title }}</h2>\r\n                    <form method=\"POST\" id=\"Contract\" enctype=\"multipart/form-data\">\r\n                        @csrf\r\n                        <div class=\"row\">\r\n                            <div class=\"col-md-12 col-sm-12\" id=\"result\"></div>\r\n                            <div class=\"col-md-12 col-sm-12\">\r\n                                <div class=\"form-group\">\r\n                                    <label class=\"d-none\"></label>\r\n                                    <input class=\"form-control\" type=\"text\" placeholder=\"@lang(\'words.name\')\"\r\n                                        name=\"name\">\r\n                                    <div id=\"name\" class=\"err\"></div>\r\n\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"col-md-12 col-sm-12\">\r\n                                <div class=\"form-group\">\r\n                                    <label class=\"d-none\" for=\"\"></label>\r\n                                    <input class=\"form-control\" type=\"email\" placeholder=\"@lang(\'words.email\')\"\r\n                                        name=\"email\">\r\n                                    <div id=\"email\" class=\"err\"></div>\r\n\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"col-md-12 col-sm-12\">\r\n                                <div class=\"form-group\">\r\n                                    <label class=\"d-none\" for=\"\"></label>\r\n                                    <input class=\"form-control\" type=\"text\"\r\n                                        placeholder=\"@lang(\'words.phone\')\" name=\"phone\">\r\n                                    <div id=\"phone\" class=\"err\"></div>\r\n\r\n                                </div>\r\n                            </div>\r\n                            <div class=\"col-md-12 col-sm-12\">\r\n                                <div class=\"form-group\">\r\n                                    <label class=\"d-none\" for=\"\"></label>\r\n                                    <textarea class=\"form-control\" placeholder=\"@lang(\'words.inquiry\')\" rows=\"5\" id=\"inquiry\" name=\"inquiry\"></textarea>\r\n                                    <div id=\"inquiry_err\" class=\"err\"></div>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <div class=\"col-md-12 col-sm-12\">\r\n                                <div class=\"form-group\">\r\n                                    <label class=\"d-none\" for=\"\"></label>\r\n                                    <div class=\"mb-3\">\r\n                                        <div id=\"fileHelpId\" class=\"form-text\"><p>{{ __(\'words.upload_your_id\') }}</p></div>\r\n                                        <input type=\"file\" class=\"form-control\" name=\"file\">\r\n                                    </div>\r\n\r\n                                    <div id=\"file\" class=\"err\"></div>\r\n                                </div>\r\n                            </div>\r\n\r\n\r\n                            <div class=\"col-md-12 col-sm-12  mt-4\">\r\n                                <button type=\"submit\" class=\"btn button btn-rounded btn-light-blue btn-hvr-light-blue\"\r\n                                    id=\"btn-submit\">{{ __(\'words.send\') }}\r\n                                    <div class=\"btn-hvr-setting\">\r\n                                        <ul class=\"btn-hvr-setting-inner\">\r\n                                            <li class=\"btn-hvr-effect\"></li>\r\n                                            <li class=\"btn-hvr-effect\"></li>\r\n                                            <li class=\"btn-hvr-effect\"></li>\r\n                                            <li class=\"btn-hvr-effect\"></li>\r\n                                        </ul>\r\n                                    </div>\r\n                                </button>\r\n                            </div>\r\n                        </div>\r\n                    </form>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6 col-md-6 col-sm-12 pt-3\">\r\n               <img src=\"{{ page(\'contract-request-page\')->image }}\" class=\"img-fluid rounded-bottom contract-image\"   alt=\"\">\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n<!-- End Contact -->\r\n\r\n{{-- ajax call --}}\r\n@push(\'scripts\')\r\n    <script>\r\n        $(\'#Contract\').submit(function(e) {\r\n            console.log(\'Iam in\');\r\n            e.preventDefault();\r\n            $(\".err\").empty();\r\n            $(\".err\").addClass(\"d-none\");\r\n            let formData = new FormData($(\'#Contract\')[0]);\r\n            $(\"#btn-submit\").attr(\'disabled\', \'disabled\');\r\n            $.ajax({	\r\n                type: \'post\',\r\n                enctype: \'multipart/form-data\',\r\n                url: \"{{ route(\'contract.store\') }}\",\r\n                data: formData,\r\n                processData: false,\r\n                contentType: false,\r\n                cache: false,\r\n                success: (response) => {\r\n                    $(\"#btn-submit\").removeAttr(\'disabled\');\r\n                    if (response) {\r\n                        this.reset();\r\n                        console.log(response);\r\n                        if (response.success) {\r\n                            $(\'.success\').removeClass(\'d-none\').text(response.success);\r\n                            setTimeout(() => {\r\n                                $(\'.success\').addClass(\'d-none\').text(response.success);\r\n                            }, 5000);\r\n                        } else\r\n                            $(\'.error\').removeClass(\'d-none\').text(response.error);\r\n                    }\r\n                },\r\n                error: function(response) {\r\n                    console.log(\'In error\',response);\r\n                    $(\"#btn-submit\").removeAttr(\'disabled\');\r\n                    $(\".err\").addClass(\"d-block\");\r\n                    $(\".err\").removeClass(\"d-none\");\r\n                    if (response.responseJSON?.errors.name) {\r\n                        $(\"#name\").append(\r\n                            `<div class=\"alert alert-danger my-1\">${response.responseJSON?.errors.name}</div>`\r\n                        );\r\n                    }\r\n                    if (response.responseJSON?.errors.email) {\r\n                        $(\"#email\").append(\r\n                