orm-group\">\r\n                <strong>Date Created:</strong>\r\n                <p style=\"display: inline\">{{$product->created_at}}</p>\r\n \r\n            </div>\r\n        </div>\r\n    </div>\r\n@endsection\r\n\r\nProductController.php\r\n<?php\r\nnamespace App\\Http\\Controllers;\r\n \r\nuse App\\Models\\Product;\r\nuse Illuminate\\Http\\Request;\r\n \r\nclass ProductController extends Controller\r\n{\r\n    /**\r\n     * Display a listing of the resource.\r\n     *\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function index()\r\n    {\r\n        $products = Product::latest()->paginate(5);\r\n \r\n        return view(\'products.index\', compact(\'products\'))\r\n            ->with(\'i\', (request()->input(\'page\', 1) - 1) * 5);\r\n    }\r\n \r\n    /**\r\n     * Show the form for creating a new resource.\r\n     *\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function create()\r\n    {\r\n        return view(\'products.create\');\r\n    }\r\n \r\n    /**\r\n     * Store a newly created resource in storage.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function store(Request $request)\r\n    {\r\n        // dd($request->all());\r\n        $request->validate([\r\n            \'name\' => \'required\',\r\n            \'description\' => \'required\',\r\n            \'price\' => \'required\'\r\n        ],[\'name.required\'=>\'name is required\',\r\n        \'description.required\'=>\'name is required\',\r\n        \'price.required\'=>\'name is required\',]);\r\n\r\n \r\n        Product::create($request->all());\r\n        return redirect()->route(\'products.index\')\r\n            ->with(\'success\', \'Product created successfully.\');\r\n    }\r\n \r\n    /**\r\n     * Display the specified resource.\r\n     *\r\n     * @param  \\App\\Models\\Product  $product\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function show(Product $product)\r\n    {\r\n        return view(\'products.show\', compact(\'product\'));\r\n    }\r\n \r\n    /**\r\n     * Show the form for editing the specified resource.\r\n     *\r\n     * @param  \\App\\Models\\Product  $product\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function edit(Product $product)\r\n    {\r\n        return view(\'products.edit\', compact(\'product\'));\r\n    }\r\n    /**\r\n     * Update the specified resource in storage.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @param  \\App\\Models\\product  $product\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function update(Request $request, Product $product)\r\n    {\r\n        $request->validate([\r\n            \'name\' => \'required\',\r\n            \'description\' => \'required\',\r\n            \'price\' => \'required\'\r\n        ]);\r\n        $product->update($request->all());\r\n    	//or\r\n    	$product->update([\'name\'=>\'product2\',\'price\'=>55]);\r\n \r\n        return redirect()->route(\'products.index\')\r\n            ->with(\'success\', \'Product updated successfully\');\r\n    }\r\n    /**\r\n     * Remove the specified resource from storage.\r\n     *\r\n     * @param  \\App\\Models\\Product  $product\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function destroy(Product $product)\r\n    {\r\n        $product->delete();\r\n \r\n        return redirect()->route(\'products.index\')\r\n            ->with(\'success\', \'Product deleted successfully\');\r\n    }\r\n}\r\n\r\nProduct.php Model\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\n \r\nclass Product extends Model\r\n{\r\n    use HasFactory;\r\n \r\n    protected $table = \'products\';\r\n    public $timestamps = true;\r\n \r\n    protected $casts = [\r\n        \'price\' => \'float\'\r\n    ];\r\n \r\n    protected $fillable = [\r\n        \'name\',\r\n        \'description\',\r\n        \'price\',\r\n        \'created_at\'\r\n    ];\r\n}\r\n \r\nClassroom Model Controller that shows how to add relations\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\n \r\nclass Classroom extends Model\r\n{\r\n    use HasFactory;\r\n \r\n    protected $table = \'classroom\';\r\n   protected $primaryKey = \'classroom_id\';\r\n \r\n    protected $fillable = [\r\n        \'classroom_code\',\'title\',\r\n        \'course_id\',\'teacher_id\', \'content\',\'updated_at\'\r\n    ];\r\n \r\n    public function course()\r\n    {\r\n        return $this->belongsTo(Course::class, \'course_id\');\r\n    }\r\n   \r\n    public function teacher()\r\n    {\r\n        return $this->belongsTo(Teacher::class, \'teacher_id\');\r\n    }\r\n\r\n//hasMany relation and usage\r\n    public function students()\r\n    {\r\n        return $this->hasMany(Student::class);\r\n    }\r\n\r\n    $classroom->students //Gets all students enrolled in a one classroom\r\n\r\n}\r\n \r\nPorductMigration\r\n<?php\r\n \r\nuse Illuminate\\Database\\Migrations\\Migration;\r\nuse Illuminate\\Database\\Schema\\Blueprint;\r\nuse Illuminate\\Support\\Facades\\Schema;\r\n \r\nclass CreateProductsTable extends Migration\r\n{\r\n    /**\r\n     * Run the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function up()\r\n    {\r\n        Schema::create(\'products\', function (Blueprint $table) {\r\n            $table->id();\r\n            $table->string(\'name\', 255)->nullable();\r\n            $table->string(\'description\', 500)->nullable();\r\n            $table->decimal(\'price\', 22)->nullable()->default(0.00);\r\n            $table->binary(image);\r\n            $table->timestamp(\'created_at\')->useCurrent();\r\n            $table->timestamp(\'updated_at\')->useCurrent();\r\n            \r\n\r\n        });\r\n    }\r\n \r\n    /**\r\n     * Reverse the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function down()\r\n    {\r\n        Schema::dropIfExists(\'products\');\r\n    }\r\n}\r\n\r\nUserFactory.php\r\n<?php\r\n \r\nnamespace Database\\Factories;\r\n \r\nuse App\\Models\\User;\r\nuse Illuminate\\Database\\Eloquent\\Factories\\Factory;\r\nuse Illuminate\\Support\\Str;\r\n \r\nclass UserFactory extends Factory\r\n{\r\n    /**\r\n     * The name of the factory\'s corresponding model.\r\n     *\r\n     * @var string\r\n     */\r\n    protected $model = User::class;\r\n \r\n    /**\r\n     * Define the model\'s default state.\r\n     *\r\n     * @return array\r\n     */\r\n    public function definition()\r\n    {\r\n        return [\r\n            \'name\' => $this->faker->name,\r\n            \'email\' => $this->faker->unique()->safeEmail,\r\n            \'email_verified_at\' => now(),\r\n            \'password\' => \'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2.uheWG/igi\', // password\r\n            \'remember_token\' => Str::random(10),\r\n        ];\r\n    }\r\n}\r\n\r\nMailController.php\r\n<?php\r\n \r\nnamespace App\\Http\\Controllers;\r\n \r\nuse Illuminate\\Http\\Request;\r\nuse App\\Mail\\OrderShipped;\r\nuse Illuminate\\Support\\Facades\\Mail;\r\n \r\nclass MailController extends Controller\r\n{\r\n   public function sendMail()\r\n   {    \r\n        Mail::to(\'nessimboula@gmail.com\')->send(new OrderShipped());\r\n   }\r\n}\r\n\r\nUserSeeder.php\r\n<?php\r\n \r\nnamespace Database\\Seeders;\r\n \r\nuse Illuminate\\Database\\Seeder;\r\nuse App\\Models\\User;\r\nuse Illuminate\\Support\\Facades\\DB;\r\nUSE File;\r\n \r\nclass UserSeeder extends Seeder\r\n{\r\n    /**\r\n     * Run the database seeds.\r\n     *\r\n     * @return void\r\n     */\r\n    public function run()\r\n    {\r\n   \r\n \r\n        DB::statement(\'SET FOREIGN_KEY_CHECKS=0;\');\r\n        User::truncate();\r\n        