rt/form-data\">\r\n<input type=\"file\" class=\"form-control-file\" style=\"margin: 20px 0px -27px 5px;\" name=\"file\" id=\"exampleInputFile\" >\r\n\r\nController to receive and download files\r\n       //upload file\r\n        $name=$file->getClientOriginalName();\r\n \r\n        $file->move(\'materials\',$name);\r\n       \r\n        Comments::create([\r\n            \'comments\' => $request->input(\'comments\'),\r\n            \'post_id\' => $request->input(\'post_id\'),\r\n            \'student_id\' => $request->input(\'student_id\'),\r\n            \'teacher_id\' => $request->input(\'teacher_id\'),\r\n            \'content\' => $name\r\n            ]);  }\r\n       //download file\r\n       $studentassignments = StudentAssignment::latest()->paginate(100);\r\n       foreach(  $studentassignments as   $studentassignment)\r\n       if($studentassignment->id==$request->input(\'assignment_id\'))\r\n       {\r\n \r\n       $pathToFile =\'materials/\' . $studentassignment->content;\r\n       return response()->download($pathToFile);\r\n   \r\n}  \r\n\r\nHow to submit a form using ajax\r\n<script>\r\n    $(function () {\r\n        $(\"form\").validate();\r\n        });\r\n \r\n    $( \"form\" ).on( \"submit\", function(e) {\r\n        var dataString = $(this).serialize();\r\n        // alert(dataString); return false;\r\n        $.ajax({\r\n            type: \"POST\",\r\n            url: \"php.php\",\r\n            data: dataString,\r\n            success: function () {\r\n                $(\"#contact_form\").html(\"<div id=\'message\'></div>\");\r\n                $(\"#message\")\r\n                .html(\"<h2>Contact Form Submitted!</h2>\")\r\n                .append(\"<p>We will be in touch soon.</p>\")\r\n                .hide()\r\n                .fadeIn(1500, function () {\r\n                    $(\"#message\").append(\r\n                    \"<img id=\'checkmark\' src=\'images/check.png\' />\"\r\n                    );\r\n                });\r\n            }\r\n        });\r\n        e.preventDefault();\r\n    });\r\n</script>\r\n\r\nSlider.routes\r\nRoute::resource(\'sliders\', SliderController::class);\r\n//API route for home\r\nRoute::get(\'home\', \'App\\Http\\Controllers\\Api\\HomeController@home\');\r\n\r\nSlider.index.blade.php\r\n@extends(\'admin.components.index\')\r\n@section(\'module_name\') @lang(\'general.aside.slider\') @endsection\r\n@section(\'page_type\') @lang(\'general.index\') @endsection\r\n@section(\'title\') @lang(\'general.aside.slider\') @endsection\r\n@section(\'create_route\', route(\'sliders.create\'))\r\n \r\n@section(\'page_content\')\r\n    <table class=\"table table-separate table-head-custom table-checkable\" >\r\n        <thead>\r\n            <tr>\r\n                <th>#</th>\r\n                <th>@lang(\'general.title\')</th>\r\n                <th>@lang(\'general.created_at\')</th>\r\n                <th>@lang(\'general.control\')</th>\r\n            </tr>\r\n        </thead>\r\n        <tbody>\r\n            @foreach ($data as $key => $value)\r\n                <tr>\r\n                    <td class=\"dtr-control\">{{ $key + 1 }}</td>\r\n                    <td>{{ $value->title }}</td>\r\n                    <td class=\"sorting_1\" nowrap=\"nowrap\">\r\n                        <span class=\"label-inline\">{{ $value->created_at }}</span>\r\n                    </td>\r\n                    <td nowrap=\"nowrap\">\r\n                        @include(\'admin.components.table-control\', [\'name\'=>\'sliders\', \'value\'=>$value])\r\n                        {{-- <a href=\"{{ route(\'property.comments\', $value->id) }}\" class=\"btn btn-icon btn-light btn-hover-primary btn-sm\" title=\"التعليقات\">\r\n                            <span class=\"svg-icon svg-icon-primary svg-icon-2x\">\r\n                                <i class=\"fa fa-comment\"></i>\r\n                            </span>\r\n                        </a> --}}\r\n                    </td>\r\n                </tr>\r\n            