)</h3>\r\n            </div>\r\n            @if (Route::is(\'contact.index\'))\r\n                <div class=\"card-toolbar\"></div>\r\n            @else\r\n                <div class=\"card-toolbar\">\r\n                    <!--begin::Button-->\r\n                    <a href=\"@yield(\'create_route\')\" class=\"btn btn-primary font-weight-bolder\">\r\n                        <i class=\"la la-plus\"></i>@lang(\'general.add_new\')\r\n                    </a>\r\n                    <!--end::Button-->\r\n                </div>\r\n            @endif\r\n        </div>\r\n        <div class=\"card-body\">\r\n            <!--begin: Datatable-->\r\n            @yield(\'filters\')\r\n            <div class=\"table-responsive\">\r\n                @yield(\'page_content\')\r\n            </div>\r\n            <!--end: Datatable-->\r\n        </div>\r\n    </div>\r\n    <!--end::Card-->\r\n@endsection\r\n \r\n \r\nSlider.SliderController\r\n<?php\r\n \r\nnamespace App\\Http\\Controllers\\Admin;\r\n \r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\GeneralRequest;\r\nuse App\\Models\\General;\r\nuse Illuminate\\Support\\Facades\\File;\r\nclass SliderController extends Controller\r\n{\r\n    /**\r\n     * Display a listing of the resource.\r\n     *\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function index()\r\n    {\r\n       $data = General::where(\'type\',\'slider\')->take(6)->skip(5)->get();\r\n\r\n        return view(\'admin.sliders.index\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Show the form for creating a new resource.\r\n     *\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function create()\r\n    {\r\n        return view(\'admin.sliders.create\');\r\n    }\r\n \r\n    /**\r\n     * Store a newly created resource in storage.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function store(GeneralRequest $request)\r\n    {\r\n        $data = $request->all();\r\n        if ($request->hasFile(\'image\')) {\r\n            $file = $request->file(\'image\');\r\n            $data[\'image\']  = upload_image($file, \'image_\');\r\n        } else {\r\n            $data[\'image\'] = \'\';\r\n        }\r\n        $data[\'type\'] = \'slider\';\r\n        $general = General::create($data);\r\n        return $general ? redirect(route(\'sliders.index\'))->with([\'success\' => trans(\'general.added_success\')]) : redirect()->back();\r\n    }\r\n \r\n    /**\r\n     * Display the specified resource.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function show($id)\r\n    {\r\n        $data = General::findorfail($id);\r\n \r\n        return view(\'admin.sliders.show\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Show the form for editing the specified resource.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function edit($id)\r\n    {\r\n        $data = General::findOrfail($id);\r\n        return view(\'admin.sliders.edit\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Update the specified resource in storage.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function update(GeneralRequest $request, $id)\r\n    {\r\n        $data =  $request->all();\r\n        $general = General::findOrfail($id);\r\n        if ($request->hasFile(\'image\')) {\r\n            $file = $request->file(\'image\');\r\n            $data[\'image\']  = upload_image($file, \'image_\');\r\n            if(file_exists($general->image))\r\n            File::delete($general->image);\r\n        } else {\r\n            $data[\'image\'] =  $general->image;\r\n        }\r\n        $general->fill($data)->save();\r\n        return $general ? redirect(route(\'sliders.index\', $id))->with([\'success\' => trans(\'general.updated_success\')]) : redirect()->back();\r\n    }\r\n \r\n    /**\r\n     * Remove the specified resource from storage.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function destroy($id)\r\n    {\r\n        $general = General::findOrfail($id);\r\n        $general->translations()->delete();\r\n        $general->delete();\r\n        return redirect(route(\'sliders.index\'))->with([\'success\' => trans(\'general.deleted_success\')]);\r\n    }\r\n}\r\n \r\n \r\nSlider.Request\r\n<?php\r\n \r\nnamespace App\\Http\\Requests;\r\n \r\nuse Illuminate\\Foundation\\Http\\FormRequest;\r\n \r\nclass GeneralRequest extends FormRequest\r\n{\r\n    public function authorize()\r\n    {\r\n        return true;\r\n    }\r\n \r\n    public function rules()\r\n    {\r\n        //to add or remove input from request in validation class use $this->merge\r\n         $this->merge([\'user_id\' => auth(\'api\')->user()->id]);\r\n\r\n        $image = request()->isMethod(\'put\') ? \'nullable\' : \'required\';\r\n        $rules = [\r\n            \'image\' =>  $image ,\r\n        ];\r\n        foreach (config(\'translatable.locales\') as $locale) {\r\n            $rules += [$locale . \'.title\' => [\'required\', \'string\']];\r\n            $rules += [$locale . \'.description\' => [\'required\']];\r\n        }\r\n        return  $rules;\r\n    }\r\n    public function messages()\r\n    {\r\n        $messages = [\r\n            \'image.required\' => trans(\'requests.image_required\'),\r\n        ];\r\n        foreach (config(\'translatable.locales\') as $locale) {\r\n            $messages += [$locale . \'.title.required\' => trans(\'requests.title_required_\' . $locale)];\r\n            $messages += [$locale . \'.description.required\' => trans(\'requests.desc_required_\' . $locale)];\r\n        }\r\n        return $messages;\r\n    }\r\n \r\n}\r\n\r\nHome.Apicontroller\r\n<?php\r\n \r\nnamespace App\\Http\\Controllers\\Api;\r\n \r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Resources\\GeneralResource;\r\nuse App\\Http\\Resources\\PageResource;\r\nuse App\\Http\\Resources\\PropertiesResource;\r\nuse App\\Http\\Resources\\TeamResource;\r\nuse App\\Http\\Resources\\ToothResource;\r\nuse App\\Http\\Resources\\SettingsResource;\r\nuse App\\Models\\Category;\r\nuse App\\Models\\General;\r\nuse App\\Models\\OurTeam;\r\nuse App\\Models\\Page;\r\nuse App\\Models\\Property;\r\nuse App\\Models\\PropertyTranslation;\r\nuse App\\Models\\Setting;\r\nuse GrahamCampbell\\ResultType\\Success;\r\nuse Illuminate\\Http\\Request;\r\n \r\nclass HomeController extends Controller\r\n{\r\n    public function home(Request $request)\r\n    {\r\n        $data[\'sliders\'] = GeneralResource::collection(General::where(\'type\',\'slider\')->get());\r\n        $data[\'services\'] = GeneralResource::collection(General::where(\'type\',\'service\')->get());\r\n        $data[\'appointment_page\'] = new PageResource(Page::where(\'identifier\',\'appointment\')->first());\r\n        $data[\'about_page\'] = new PageResource(Page::where(\'identifier\',\'about\')->first());\r\n        $data[\'testimonials\'] = GeneralResource::collection(General::where(\'type\',\'testimonial\')->get());\r\n        $data[\'our_team\'] = TeamResource::collection(OurTeam::get());\r\n        $data[\'tooth_page\'] = new ToothResource(Page::where(\'identifier\',\'tooth_cleaning\')->first());\r\n \r\n        return response()->json([\r\n            \'status\' => \'Success\',\r\n            \'data\'   => $data\r\n        ]);\r\n    }\r\n \r\n}\r\n \r\nGeneral.Resource\r\n<?php\r\n \r\nnamespace App\\Http\\Resources;\r\n \r\nuse Illuminate\\Http\\Resources\\Json\\JsonResource;\r\n \r\nclass GeneralResource extends JsonResource\r\n{\r\n    /**\r\n     * Transform the resource into an array.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @return array|\\Illuminate\\Contracts\\Support\\Arrayable|\\JsonSerializable\r\n     */\r\n    public function toArray($request)\r\n    {\r\n        return [\r\n            \'id\' => $this->id,\r\n            \'title\' => $this->translate($request->lang)->title,\r\n            \'description\' => $this->translate($request->lang)->description,\r\n            \'image\' =>$this->image ? asset($this->image) : asset(settings()->logo),\r\n        ];\r\n    }\r\n}\r\n\r\nGeneral.Model.php\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Astrotomic\\Translatable\\Contracts\\Translatable as TranslatableContract;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\nuse Astrotomic\\Translatable\\Translatable;\r\n \r\nclass General extends Model implements TranslatableContract\r\n{\r\n    use Translatable;\r\n \r\n    public $translatedAttributes = [\r\n        \'title\',\r\n        \'description\'\r\n    ];\r\n \r\n    protected $fillable = [\'image\',\'type\'];\r\n}\r\n\r\nGeneralTranslation.Model.php\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\n \r\nclass GeneralTranslation extends Model\r\n{\r\n    protected $fillable = [\r\n        \'title\',\r\n        \'description\',\r\n    ];\r\n}\r\n\r\nGeneral.migration\r\n<?php\r\n \r\nuse Illuminate\\Database\\Migrations\\Migration;\r\nuse Illuminate\\Database\\Schema\\Blueprint;\r\nuse Illuminate\\Support\\Facades\\Schema;\r\n \r\nclass CreateGeneralsTable extends Migration\r\n{\r\n    /**\r\n     * Run the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function up()\r\n    {\r\n        Schema::create(\'generals\', function (Blueprint $table) {\r\n            $table->bigIncrements(\'id\');\r\n            $table->string(\'image\')->nullable();\r\n            $table->string(\'type\');\r\n            $table->timestamps();\r\n        });\r\n    }\r\n \r\n    /**\r\n     * Reverse the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function down()\r\n    {\r\n        Schema::dropIfExists(\'generals\');\r\n    }\r\n}\r\n \r\nGeneralTranslation.migration\r\n<?php\r\n \r\nuse Illuminate\\Database\\Migrations\\Migration;\r\nuse Illuminate\\Database\\Schema\\Blueprint;\r\nuse Illuminate\\Support\\Facades\\Schema;\r\n \r\nclass CreateGeneralTranslationsTable extends Migration\r\n{\r\n    /**\r\n     * Run the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function up()\r\n    {\r\n        Schema::create(\'general_translations\', function (Blueprint $table) {\r\n            $table->bigIncrements(\'id\');\r\n            $table->string(\'title\')->nullable();\r\n            $table->string(\'description\')->nullable();\r\n            $table->unsignedBigInteger(\'general_id\');\r\n            $table->string(\'locale\')->index();\r\n            $table->unique([\'general_id\', \'locale\']);\r\n            $table->foreign(\'general_id\')->references(\'id\')->on(\'generals\')->delete(\'cascade\');\r\n            $table->timestamps();\r\n        });\r\n    }\r\n \r\n    /**\r\n     * Reverse the migrations.\r\n     *\r\n     * @return void\r\n     */\r\n    public function down()\r\n    {\r\n        Schema::dropIfExists(\'general_translations\');\r\n    }\r\n}\r\n\r\nAppointment and Contact Api routes\r\nRoute::post(\'contact\', \'App\\Http\\Controllers\\Api\\AboutController@contact\');\r\nRoute::post(\'appointment\', \'App\\Http\\Controllers\\Api\\AboutController@appointment\');\r\nRoute::post(\'question\', \'App\\Http\\Controllers\\Api\\AboutController@post_question\');\r\n\r\nAppointment and Contact Api controller\r\n<?php\r\nnamespace App\\Http\\Controllers\\Api;\r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\Site\\ContactFormRequest;\r\nuse App\\Http\\Requests\\ContactRequest;\r\nuse App\\Models\\Contact;\r\nuse App\\Models\\Page;\r\nuse App\\Models\\Setting;\r\nuse Illuminate\\Http\\Request;\r\nuse Validator;\r\nuse App\\Http\\Controllers\\Api\\BaseController as BaseController;\r\nuse App\\Models\\Appointment;\r\nuse App\\Models\\Question;\r\n \r\nclass AboutController extends BaseController\r\n{\r\n \r\n    public function contact(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'name\' => \'required\',\r\n            \'phone\' => \'required\',\r\n            \'message\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Contact::create($data);\r\n        return $this->sendResponse($success, \'تم ارسال الرسالة بنح\');\r\n    }\r\n    public function appointment(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'first_name\' => \'required\',\r\n            \'last_name\' => \'required\',\r\n            \'age\' => \'required\',\r\n            \'phone\' => \'required\',\r\n            \'service\' => \'required\',\r\n            \'date_time\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Appointment::create($data);\r\n        return $this->sendResponse($success, \'تم حجز الموعد بنجاح\');\r\n    }\r\n \r\n    public function post_question(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'name\' => \'required\',\r\n            \'phone\' => \'required|numeric\',\r\n            \'message\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Question::create($data);\r\n        return $this->sendResponse($success, \'تم ارسال السؤال بنجاح\');\r\n    }\r\n \r\n    public function setting(Request $request){\r\n        $data = Setting::first();\r\n        $data[\'logo\'] = asset($data->logo);\r\n        $data[\'breadcrumb\'] = asset($data->breadcrumb);\r\n        $data[\'website_title\'] = $data->translate($request->lang)->website_title;\r\n        $data[\'meta_title\'] = $data->translate($request->lang)->meta_title;\r\n        $data[\'meta_description\'] = $data->translate($request->lang)->meta_description;\r\n        $data[\'meta_keywords\'] = $data->translate($request->lang)->meta_keywords;\r\n        $data[\'address\'] = $data->translate($request->lang)->address;\r\n        $data[\'footer_description\'] = $data->translate($request->lang)->footer_description;\r\n        return response()->json([\r\n            \'status\' => \'true\',\r\n            \'data\'   => $data\r\n        ]);\r\n    }\r\n}\r\n\r\nNBE payment gate way\r\npublic function store(Request $request){\r\n$data=$request->all();\r\n$last_invoice = Invoice::create($data);\r\n// $last_invoice=Invoice::where(\'name\',$data[\'name\'])->first();\r\n$username=\'merchant.TESTEGPTEST\';\r\n$password=\'c622b7e9e550292df400be7d3e846476\';\r\n \r\n$url = \'https://test-\r\nnbe.gateway.mastercard.com/api/rest/version/65/merchant/TESTEGPTEST/session\';\r\n \r\n$data = array(\"apiOperation\" => \"INITIATE_CHECKOUT\",\r\n        \"interaction\" => array (\"operation\" => \"AUTHORIZE\" ,\"returnUrl\"\r\n        =>\"http://127.0.0.1:8000/success_invoice/\".$last_invoice->id,\"cancelUrl\" =>\r\n        \"http://127.0.0.1:8000/cancel_invoice/\".$last_invoice->id),\r\n        \"order\" => array (\"currency\" => \"EGP\" ,\"id\" =>\r\n \r\n        $last_invoice->id,\"amount\" => $last_invoice->price,\"description\"=>\'description\')\r\n \r\n);\r\n \r\n$postdata = json_encode($data);\r\n$ch = curl_init($url);\r\ncurl_setopt($ch, CURLOPT_POST, 1);\r\ncurl_setopt($ch, CURLOPT_POSTFIELDS, $postdata);\r\ncurl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);\r\ncurl_setopt($ch, CURLOPT_HTTPHEADER, array(\'Content-Type:\r\napplication/json\'));\r\ncurl_setopt($ch, CURLOPT_USERPWD, \"$username:$password\");\r\n$result = curl_exec($ch);\r\ncurl_close($ch);\r\n$seeion_id = json_decode($result)->session->id ;\r\n \r\n$newUrl = \'https://test-\r\nnbe.gateway.mastercard.com/api/rest/version/65/merchant/TESTEGPTEST/session/\'.$seeion_id;\r\n$data_two = array(\"apiOperation\" => \"UPDATE_SESSION\",\r\n\"order\" => array (\"currency\" => \"EGP\" ,\"id\" =>\r\n$last_invoice->id,\"amount\" => $last_invoice->price)\r\n);\r\n \r\n$postdata_two = json_encode($data_two);\r\n$ch = curl_init($newUrl);\r\ncurl_setopt($ch, CURLOPT_POST, 1);\r\ncurl_setopt($ch, CURLOPT_POSTFIELDS, $postdata_two);\r\ncurl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);\r\ncurl_setopt($ch, CURLOPT_HTTPHEADER, array(\'Content-Type:\r\napplication/json\'));\r\ncurl_setopt($ch, CURLOPT_USERPWD, \"$username:$password\");\r\n$result = curl_exec($ch);\r\ncurl_close($ch);\r\n// $seeion_id = json_decode($result)->session->id ;\r\nreturn view(\'user.marwan_payment\',compact(\'seeion_id\'));\r\n \r\n}\r\n \r\npublic function cancel_invoice($id){\r\n    $invoice=Invoice::findOrFail($id);\r\n    $invoice->update([\"status\"=>\"canceled\"]);\r\n    return view(\'user.cancel_payment\');\r\n    }\r\n \r\n    public function success_invoice($id){\r\n    $invoice=Invoice::findOrFail($id);\r\n    $invoice->update([\"status\"=>\"success\"]);\r\n    return view(\'user.sucdcess_payment\');\r\n    }\r\n\r\nInvoice form\r\n<form action=\"{{getRoute(\'invoices.store\')}}\"\r\n \r\n    method=\"POST\" id=\"invoice_form\">\r\n    @csrf\r\n    <div class=\"row\">\r\n        <div class=\"col-lg-6\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الاسم <label>\r\n                <input class=\"form-control\" type=\"text\" name=\"name\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-6\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الهاتف/>* label>\r\n                <input class=\"form-control\" type=\"number\" name=\"phone\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">االلكتروني البريد/>label>\r\n                <input class=\"form-control\" type=\"text\" name=\"email\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الخدمة/>label>\r\n                <select name=\"product_id\" id=\"product_select\" class=\"form-control\">\r\n                    @foreach ($products as $product)\r\n                        <option product-price=\"{{ $product->price }}\" value=\"{{ $product->id }}\">{{ $product->name }}</option>\r\n                    @endforeach\r\n                </select>\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">السعر) L.E)</label>\r\n                <input class=\"form-control\" type=\"text\" name=\"price\" id=\"price\" readonly>\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12 text-center\">\r\n            <button class=\"btn btn-primary \" type=\"submit\">ادفع</button>\r\n        </div>\r\n    </div>\r\n</form>\r\n \r\n<script>\r\n$(document).ready(function(){\r\n    $(\"#product_select\").on(\"change\",function(){\r\n        let value = $(this).find(\":selected\").attr(\"product-price\");\r\n        $(\"#price\").val(value);\r\n    });\r\n});ript>\r\n\r\nHow to show limited words of returned string\r\n {!! mb_substr ( $service->description , 0, 210) !!}...\r\n\r\nHow to control pagination\r\n{!! $data->links(\'admin.components.pagination.default\') !!}\r\n\r\n\'admin.components.pagination.default\'\r\n@if ($paginator->hasPages())\r\n<nav class=\"navigation\" aria-label=\"Page navigation\">\r\n    <ul class=\"pagination mt-5\">\r\n        {{-- Previous Page Link --}}\r\n        @if ($paginator->onFirstPage())\r\n            <li class=\"page-item disabled\"><span class=\"page-link arrow\" aria-label=\"Previous\"><span aria-hidden=\"true\">&laquo;</span></span></li>\r\n        @else\r\n            <li class=\"page-item\"><a class=\"page-link arrow\" href=\"{{ $paginator->previousPageUrl() }}\" aria-label=\"Previous\"><span aria-hidden=\"true\">&laquo;</span></a></li>\r\n        @endif\r\n \r\n        {{-- Pagination Elements --}}\r\n        @foreach ($elements as $element)\r\n            {{-- \"Three Dots\" Separator --}}\r\n            @if (is_string($element))\r\n                <li class=\"page-item disabled\"><span>{{ $element }}</span></li>\r\n            @endif\r\n \r\n            {{-- Array Of Links --}}\r\n            @if (is_array($element))\r\n                @foreach ($element as $page => $url)\r\n                    @if ($page == $paginator->currentPage())\r\n                        <li class=\"page-item active\"><span  class=\"page-link\">{{ $page }}</span></li>\r\n                    @else\r\n                        <li class=\"page-item\"><a class=\"page-link\" href=\"{{ $url }}\">{{ $page }}</a></li>\r\n                    @endif\r\n                @endforeach\r\n            @endif\r\n        @endforeach\r\n \r\n        {{-- Next Page Link --}}\r\n        @if ($paginator->hasMorePages())\r\n            <li class=\"page-item\"><a class=\"page-link arrow\" href=\"{{ $paginator->nextPageUrl() }}\" aria-label=\"Next\"><span aria-hidden=\"true\">&raquo;</span></a></li>\r\n        @else\r\n            <li class=\"page-item disabled\"><span class=\"page-link arrow\" aria-label=\"Next\"><span aria-hidden=\"true\">&raquo;</span></span></li>\r\n        @endif\r\n    </ul>\r\n</nav>\r\n@endif\r\n\r\nHow to get a part of url and add processing on it\r\n@extends(\'front.layouts.master\')\r\n@section(\'title\')\r\n    {{ settings()->website_title }} | {{ trans(\'site.services\') }}\r\n@endsect