console.log(\"async storage error\", err);\r\n  }\r\n};\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\orders.js\r\nimport { api } from \"./base\";\r\n\r\nexport const orderPost = async ({ token, values }) => {\r\n  api.defaults.headers = { Authorization: `Bearer ${token}` };\r\n  const res = await api.post(`/auth/order`, values);\r\n  return res.data;\r\n};\r\n\r\nexport const getPendingOrders = async ({ token, type }) => {\r\n  api.defaults.headers = { Authorization: `Bearer ${token}` };\r\n  console.log({ type });\r\n  const res = await api.get(`/auth/orders/${type}`);\r\n  return res.data;\r\n};\r\nexport const getSingleOrder = async ({ token, orderId }) => {\r\n  api.defaults.headers = { Authorization: `Bearer ${token}` };\r\n  const res = await api.get(`/auth/order/${orderId}`);\r\n  return res.data;\r\n};\r\n\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\api\\products.js\r\nimport { api } from \"./base\";\r\n\r\nexport const createProduct = async ({ values }) => {\r\n  const res = await api.post(`/products/store`, values);\r\n  return res.data;\r\n};\r\n\r\nexport const getProducts = async ({ locale }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(\"/products\");\r\n  return res.data;\r\n};\r\n\r\nexport const getProduct = async ({ locale, itemId }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(`/product/${itemId}`);\r\n  return res.data;\r\n};\r\nexport const getProductEdit = async ({ locale, itemId }) => {\r\n  api.defaults.headers = { locale };\r\n  const res = await api.get(`/products/${itemId}/edit`);\r\n  return res.data;\r\n};\r\n\r\nexport const removeProduct = async ({ itemId }) => {\r\n  const res = await api.delete(`/products/${itemId}`);\r\n  return res.data;\r\n};\r\n\r\nexport const productUpdate = async ({ itemId, values }) => {\r\n  const res = await api.post(`/products/${itemId}`, values);\r\n  return res.data;\r\n};\r\n\r\nexport const productsFilter = async ({ title }) => {\r\n  const 