alse }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"PaymentMethodNoCard\"\r\n          component={PaymentMethodNoCard}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"TrackingOrders\"\r\n          component={TrackingOrderV2}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"MyOrderDetails\"\r\n          component={MyOrderDetails}\r\n          options={{\r\n            headerShown: true,\r\n            headerTitle: \"Order Details\",\r\n          }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Call\"\r\n          component={Call}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Message\"\r\n          component={Message}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Favourite\"\r\n          component={Favourite}\r\n          options={{ headerShown: false }}\r\n        />\r\n      </Stack.Navigator>\r\n    </NavigationContainer>\r\n  );\r\n};\r\n\r\nexport default AppNavigation;\r\n\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\navigations\\BottomTabNavigation.js\r\nimport { View, Text, Platform } from \"react-native\";\r\nimport React from \"react\";\r\nimport { createBottomTabNavigator } from \"@react-navigation/bottom-tabs\";\r\nimport { COLORS } from \"../constants\";\r\nimport { Search, Notifications, Menu, MyOrders } from \"../screens\";\r\nimport { Ionicons, SimpleLineIcons } from \"@expo/vector-icons\";\r\nimport DrawerNavigation from \"./DrawerNavigation\";\r\nimport { AntDesign } from \"@expo/vector-icons\";\r\n\r\nconst Tab = createBottomTabNavigator();\r\n\r\nconst screenOptions = {\r\n  tabBarShowLabel: false,\r\n  headerShown: false,\r\n  tabBarStyle: {\r\n    position: \"absolute\",\r\n    bottom: 0,\r\n    right: 0,\r\n    left: 0,\r\n    elevation: 0,\r\n    height: 60,\r\n    background: COLORS.white,\r\n  },\r\n};\r\n\r\nconst BottomTabNavigation = () => {\r\n  return (\r\n    <Tab.Navigator screenOptions={screenOptions}>\r\n      <Tab.Screen\r\n        name=\"Home\"\r\n        component={DrawerNavigation}\r\n        options={{\r\n          tabBarIcon: ({ focused }) => {\r\n            return (\r\n              <SimpleLineIcons\r\n                name=\"home\"\r\n                size={24}\r\n                color={focused ? COLORS.primary : COLORS.black}\r\n              />\r\n            );\r\n          },\r\n        }}\r\n      />\r\n\r\n      <Tab.Screen\r\n        name=\"MyOrders\"\r\n        component={MyOrders}\r\n        options={{\r\n          tabBarIcon: ({ focused }) => {\r\n            return (\r\n              <Ionicons\r\n                name=\"list-sharp\"\r\n                size={24}\r\n                color={focused ? COLORS.primary : COLORS.black}\r\n              />\r\n            );\r\n          },\r\n        }}\r\n      />\r\n\r\n      <Tab.Screen\r\n        name=\"Search\"\r\n        component={Search}\r\n        options={{\r\n          tabBarIcon: () => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  alignItems: \"center\",\r\n                  justifyContent: \"center\",\r\n                  backgroundColor: COLORS.primary,\r\n                  height: Platform.OS == \"ios\" ? 50 : 60,\r\n                  width: Platform.OS == \"ios\" ? 50 : 60,\r\n                  top: Platform.OS == \"ios\" ? -10 : -20,\r\n                  borderRadius: Platform.OS == \"ios\" ? 25 : 30,\r\n                  borderWidth: 2,\r\n                  borderColor: COLORS.white,\r\n                }}\r\n              >\r\n                <AntDesign name=\"search1\" size={24} color={COLORS.white} />\r\n              </View>\r\n            );\r\n          },\r\n        }}\r\n      />\r\n\r\n      <Tab.Screen\r\n        name=\"Notifications\"\r\n        component={Notifications}\r\n        options={{\r\n          tabBarIcon: ({ focused }) => {\r\n            return (\r\n              <Ionicons\r\n                name=\"notifications-outline\"\r\n                size={24}\r\n                color={focused ? COLORS.primary : COLORS.black}\r\n              />\r\n            );\r\n          },\r\n        }}\r\n      />\r\n\r\n      <Tab.Screen\r\n        name=\"Menu\"\r\n        component={Menu}\r\n        options={{\r\n          tabBarIcon: ({ focused }) => {\r\n            return (\r\n              <Ionicons\r\n                name=\"person-outline\"\r\n                size={24}\r\n                color={focused ? COLORS.primary : COLORS.black}\r\n              />\r\n            );\r\n          },\r\n        }}\r\n      />\r\n    </Tab.Navigator>\r\n  );\r\n};\r\n\r\nexport default BottomTabNavigation;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\navigations\\DrawerNavigation.js\r\nimport \"react-native-gesture-handler\";\r\nimport { View, Text, Image } from \"react-native\";\r\nimport { Feather, Ionicons, AntDesign } from \"@expo/vector-icons\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport {\r\n  DrawerItemList,\r\n  createDrawerNavigator,\r\n} from \"@react-navigation/drawer\";\r\nimport { COLORS, images } from \"../constants\";\r\nimport {\r\n  Address,\r\n  Menu,\r\n  Notifications,\r\n  PaymentMethod,\r\n  Cart,\r\n  MyOrders,\r\n  HomeV1,\r\n  HomeV2,\r\n  Search,\r\n  HomeV3,\r\n} from \"../screens\";\r\nimport Advertisments from \"../screens/Advertisments\";\r\n\r\nconst Drawer = createDrawerNavigator();\r\nconst DrawerNavigation = () => {\r\n  return (\r\n    <Drawer.Navigator\r\n      drawerContent={(props) => {\r\n        return (\r\n          <SafeAreaView>\r\n            <View\r\n              style={{\r\n                height: 200,\r\n                width: \"100%\",\r\n                justifyContent: \"center\",\r\n                alignItems: \"center\",\r\n              }}\r\n            >\r\n              <Image\r\n                source={images.avatar3}\r\n                style={{\r\n                  height: 100,\r\n                  width: 100,\r\n                  borderRadius: 50,\r\n                }}\r\n              />\r\n              <Text\r\n                style={{\r\n                  fontSize: 18,\r\n                  marginVertical: 6,\r\n                  fontFamily: \"bold\",\r\n                  color: COLORS.black,\r\n                }}\r\n              >\r\n                Billi William\r\n              </Text>\r\n              <Text\r\n                style={{\r\n                  fontSize: 16,\r\n                  color: COLORS.black,\r\n                  fontFamily: \"regular\",\r\n                }}\r\n              >\r\n                Product Designer\r\n              </Text>\r\n            </View>\r\n            <DrawerItemList {...props} />\r\n          </SafeAreaView>\r\n        );\r\n      }}\r\n      screenOptions={{\r\n        drawerStyle: {\r\n          backgroundColor: COLORS.white,\r\n          width: 250,\r\n        },\r\n        headerStyle: {\r\n          backgroundColor: COLORS.white,\r\n        },\r\n        headerShown: false,\r\n        headerTintColor: COLORS.black,\r\n        headerTitleStyle: {\r\n          fontWeight: \"bold\",\r\n        },\r\n        drawerLabelStyle: {\r\n          color: COLORS.black,\r\n          fontFamily: \"regular\",\r\n          fontSize: 14,\r\n          marginLeft: -10,\r\n        },\r\n      }}\r\n    >\r\n      <Drawer.Screen\r\n        name=\"Home\"\r\n        options={{\r\n          drawerLabel: \"Home\",\r\n          title: \"Home\",\r\n          headerShadowVisible: false,\r\n          drawerIcon: () => (\r\n            <AntDesign name=\"home\" size={24} color={COLORS.black} />\r\n          ),\r\n        }}\r\n        component={HomeV1}\r\n      />\r\n\r\n      <Drawer.Screen\r\n        name=\"Orders\"\r\n        options={{\r\n          drawerLabel: \"Orders\",\r\n          title: \"Orders\",\r\n          drawerIcon: () => (\r\n            <Ionicons name=\"gift-outline\" size={24} color={COLORS.black} />\r\n          ),\r\n        }}\r\n        component={MyOrders}\r\n      />\r\n      <Drawer.Screen\r\n        name=\"Search\"\r\n        options={{\r\n          drawerLabel: \"Search\",\r\n          title: \"Search\",\r\n          drawerIcon: () => (\r\n            <Ionicons name=\"search-outline\" size={24} color={COLORS.black} />\r\n          ),\r\n        }}\r\n        component={Search}\r\n      />\r\n      <Drawer.Screen\r\n        name=\"Whishlist\"\r\n        options={{\r\n          drawerLabel: \"Wishlist\",\r\n          title: \"Wishlist\",\r\n          drawerIcon: () => (\r\n            <Ionicons name=\"heart-outline\" size={24} color={COLORS.black} />\r\n          ),\r\n        }}\r\n        component={Cart}\r\n      />\r\n\r\n      <Drawer.Screen\r\n        name=\"Delivery Address\"\r\n        options={{\r\n          drawerLabel: \"Delivery Address\",\r\n          title: \"Delivery Address\",\r\n          drawerIcon: () => (\r\n            <Ionicons name=\"location-outline\" size={24} color={COLORS.black} />\r\n          ),\r\n        }}\r\n        component={Address}\r\n      />\r\n\r\n      <Drawer.Screen\r\n        name=\"Payment Methods\"\r\n        options={{\r\n          drawerLabel: \"Payment Methods\",\r\n          title: \"Payment Methods\",\r\n          drawerIcon: () => (\r\n            <AntDesign name=\"creditcard\" size={24} color={COLORS.black} />\r\n          ),\r\n        }}\r\n        component={PaymentMethod}\r\n      />\r\n\r\n      <Drawer.Screen\r\n        name=\"Notifications\"\r\n        options={{\r\n          drawerLabel: \"Notifications\",\r\n          title: \"Notifications\",\r\n          drawerIcon: () => (\r\n            <Ionicons\r\n              name=\"notifications-outline\"\r\n              size={24}\r\n              color={COLORS.black}\r\n            />\r\n          ),\r\n        }}\r\n        component={Notifications}\r\n      />\r\n\r\n      <Drawer.Screen\r\n        name=\"Help\"\r\n        options={{\r\n          drawerLabel: \"Help\",\r\n          title: \"Help\",\r\n          drawerIcon: () => (\r\n            <Feather name=\"help-circle\" size={24} color={COLORS.black} />\r\n          ),\r\n        }}\r\n        component={Menu}\r\n      />\r\n    </Drawer.Navigator>\r\n  );\r\n};\r\n\r\nexport default DrawerNavigation;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Cart.js\r\nimport { View, Text, TouchableOpacity, Image, FlatList } from \"react-native\";\r\nimport React, { useState } from \"react\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport { COLORS, SIZES, icons, images } from \"../constants\";\r\nimport * as Animatable from \"react-native-animatable\";\r\nimport { cartStyles } from \"../styles/CartStyles\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport Input from \"../components/Input\";\r\nimport Button from \"../components/Button\";\r\nimport { cartData } from \"../data/cart\";\r\nimport { StatusBar } from \"expo-status-bar\";\r\nimport { ImageBackground } from \"react-native\";\r\nimport { useDispatch, useSelector } from \"react-redux\";\r\nimport { addQty, decreaseQty, emptyCart, removeItem } from \"../store/cartSlice\";\r\nimport { orderPost } from \"../api/orders\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\n\r\nconst Cart = ({ navigation }) => {\r\n  const dispatch = useDispatch();\r\n  const cart = useSelector((state) => state.cart);\r\n  const toast = useToast();\r\n  // const [name, setName] = useState(\"Ahmed Elselly\");\r\n  const [address, setAddress] = useState(\"cairo, egypt, 1111\");\r\n  // const [email, setEmail] = useState(\"ahmed@gmail.com\");\r\n  // const [phone, setPhone] = useState(\"12345678912\");\r\n  const user = useSelector((state) => state.user);\r\n  if (!user.isLoggedIn) {\r\n    navigation.navigate(\"Login\");\r\n  }\r\n  const token = user?.data?.access_token;\r\n\r\n  const decreaseQuantity = (id) => {\r\n    dispatch(decreaseQty(id));\r\n  };\r\n\r\n  const increaseQuantity = (id) => {\r\n    dispatch(addQty(id));\r\n  };\r\n\r\n  const handleRemoveItem = (id) => {\r\n    dispatch(removeItem(id));\r\n  };\r\n\r\n  const handleSubmitOrder = () => {\r\n    const values = {\r\n      name: user?.data.user.name,\r\n      email: user?.data.user.email,\r\n      phone: user?.data.user.phone,\r\n      address,\r\n      // status: \"pending\",\r\n      // ...cart,\r\n      // items: [...cart.items],\r\n      // totalPrice: cart.totalPrice,\r\n    };\r\n    const data = { ...values, ...cart };\r\n    orderPost({ values: data, token })\r\n      .then((res) => {\r\n        console.log({ res: res.data });\r\n        toast.show(\"Added the order successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        dispatch(emptyCart());\r\n      })\r\n      .catch((err) => {\r\n        console.log({ error: err.response.data });\r\n      });\r\n  };\r\n\r\n  return (\r\n    <ImageBackground\r\n      source={images.background3}\r\n      style={{ flex: 1, backgroundColor: COLORS.blue }}\r\n    >\r\n      <StatusBar hidden={true} />\r\n      <View style={cartStyles.header}>\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            alignItems: \"center\",\r\n            justifyContent: \"space-between\",\r\n            marginTop: 20,\r\n          }}\r\n        >\r\n          <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n            <TouchableOpacity\r\n              onPress={() => navigation.goBack()}\r\n              style={commonStyles.header1Icon}\r\n            >\r\n              <Image\r\n                resizeMode=\"contain\"\r\n                source={icons.arrowLeft}\r\n                style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n              />\r\n            </TouchableOpacity>\r\n            <Text\r\n              style={{\r\n                marginLeft: 12,\r\n                fontSize: 17,\r\n                fontFamily: \"regular\",\r\n                color: COLORS.white,\r\n              }}\r\n            >\r\n              Cart\r\n            </Text>\r\n          </View>\r\n          <TouchableOpacity onPress={() => console.log(\"Edit Items\")}>\r\n            <Text\r\n              style={{\r\n                fontSize: 14,\r\n                fontFamily: \"bold\",\r\n                textTransform: \"uppercase\",\r\n                color: COLORS.green,\r\n              }}\r\n            >\r\n              Done\r\n            </Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <FlatList\r\n          data={cart.items}\r\n          keyExtractor={(item) => item.id}\r\n          renderItem={({ item, index }) => {\r\n            return (\r\n              <View key={index} style={cartStyles.cartItemContainer}>\r\n                <View style={{ marginRight: 2, width: 120 }}>\r\n                  <Image\r\n                    source={{ uri: item.image }}\r\n                    resizeMode=\"contain\"\r\n                    style={{\r\n                      height: 120,\r\n                      width: 120,\r\n                      borderRadius: 30,\r\n                    }}\r\n                  />\r\n                </View>\r\n                <View\r\n                  style={{\r\n                    flexDirection: \"column\",\r\n                    justifyContent: \"space-between\",\r\n                    height: \"100%\",\r\n                    width: SIZES.width - 152,\r\n                    paddingLeft: 10,\r\n                    paddingRight: 6,\r\n                  }}\r\n                >\r\n                  <View\r\n                    style={{\r\n                      flexDirection: \"row\",\r\n                      justifyContent: \"space-between\",\r\n                    }}\r\n                  >\r\n                    <Text\r\n                      style={{\r\n                        fontSize: 13,\r\n                        color: COLORS.white,\r\n                        fontFamily: \"regular\",\r\n                        textTransform: \"capitalize\",\r\n                        marginRight: 20,\r\n                      }}\r\n                    >\r\n                      {item.title}\r\n                    </Text>\r\n                    <TouchableOpacity\r\n                      onPress={() => handleRemoveItem(item.id)}\r\n                      style={{\r\n                        height: 26,\r\n                        width: 26,\r\n                        borderRadius: 13,\r\n                        alignItems: \"center\",\r\n                        justifyContent: \"center\",\r\n                        backgroundColor: COLORS.red,\r\n                        marginTop: 2,\r\n                      }}\r\n                    >\r\n                      <Image\r\n                        source={icons.close}\r\n                        resizeMode=\"contain\"\r\n                        style={{\r\n                          width: 12,\r\n                          tintColor: COLORS.white,\r\n                        }}\r\n                      />\r\n                    </TouchableOpacity>\r\n                  </View>\r\n\r\n                  <Text\r\n                    style={{\r\n                      fontSize: 20,\r\n                      fontFamily: \"bold\",\r\n                      color: COLORS.white,\r\n                      marginVertical: 6,\r\n                    }}\r\n                  >\r\n                    EGP {item.price}\r\n                  </Text>\r\n                  <View\r\n                    style={{\r\n                      flexDirection: \"row\",\r\n                      justifyContent: \"space-between\",\r\n                    }}\r\n                  >\r\n                    <Text\r\n                      style={{\r\n                        fontSize: 16,\r\n                        color: COLORS.white,\r\n                        fontFamily: \"regular\",\r\n                      }}\r\n                    >\r\n                      {item.size}\r\n                    </Text>\r\n                    <View\r\n                      style={{ flexDirection: \"row\", alignItems: \"center\" }}\r\n                    >\r\n                      <TouchableOpacity\r\n                        onPress={() => decreaseQuantity(item.id)}\r\n                        style={cartStyles.roundedBtn}\r\n                      >\r\n                        <Text style={cartStyles.body2}>-</Text>\r\n                      </TouchableOpacity>\r\n                      <Text\r\n                        style={{\r\n                          fontSize: 16,\r\n                          fontFamily: \"regular\",\r\n                          color: COLORS.white,\r\n                          marginHorizontal: 12,\r\n                        }}\r\n                      >\r\n                        {item.qty}\r\n                      </Text>\r\n                      <TouchableOpacity\r\n                        onPress={() => increaseQuantity(item.id)}\r\n                        style={cartStyles.roundedBtn}\r\n                      >\r\n                        <Text style={cartStyles.body2}>+</Text>\r\n                      </TouchableOpacity>\r\n                    </View>\r\n                  </View>\r\n                </View>\r\n              </View>\r\n            );\r\n          }}\r\n        />\r\n      </View>\r\n      <Animatable.View animation=\"fadeInUpBig\" style={cartStyles.footer}>\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            justifyContent: \"space-between\",\r\n            marginBottom: 10,\r\n          }}\r\n        >\r\n          <Text style={cartStyles.body3}>Delivery Address</Text>\r\n          <TouchableOpacity onPress={() => navigation.navigate(\"EditCart\")}>\r\n            <Text style={cartStyles.body3Color}>Edit</Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n        <Input\r\n          id=\"Address\"\r\n          placeholder=\"2118 Thornridge Cir. Syracuse\"\r\n          placeholderTextColor={COLORS.gray4}\r\n          editable={true}\r\n          value={address}\r\n          onChangeText={setAddress}\r\n        />\r\n\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            justifyContent: \"space-between\",\r\n            marginVertical: 16,\r\n          }}\r\n        >\r\n          <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n            <Text style={cartStyles.body3}>Total:</Text>\r\n            <Text\r\n              style={{\r\n                fontSize: 24,\r\n                fontFamily: \"bold\",\r\n                color: COLORS.black,\r\n                marginLeft: 12,\r\n              }}\r\n            >\r\n              EGP {cart.totalPrice}\r\n            </Text>\r\n          </View>\r\n          <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n            <Text style={cartStyles.body3Color}>Breakdown</Text>\r\n            <View style={{ marginLeft: 2 }}>\r\n              <Image\r\n                source={icons.arrowRight}\r\n                style={{\r\n                  height: 18,\r\n                  width: 18,\r\n                  tintColor: COLORS.black,\r\n                }}\r\n              />\r\n            </View>\r\n          </View>\r\n        </View>\r\n\r\n        <Button\r\n          filled\r\n          title=\"PLACE ORDER\"\r\n          onPress={handleSubmitOrder}\r\n          style={{ marginVertical: 2 }}\r\n        />\r\n      </Animatable.View>\r\n    </ImageBackground>\r\n  );\r\n};\r\n\r\nexport default Cart;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\HomeV1.js\r\nimport {\r\n  View,\r\n  Text,\r\n  SafeAreaView,\r\n  StyleSheet,\r\n  Image,\r\n  TextInput,\r\n  TouchableOpacity,\r\n  FlatList,\r\n} from \"react-native\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { COLORS, FONTS, SIZES, icons } from \"../constants\";\r\nimport {\r\n  Feather,\r\n  Ionicons,\r\n  MaterialIcons,\r\n  Octicons,\r\n  MaterialCommunityIcons,\r\n  Fontisto,\r\n} from \"@expo/vector-icons\";\r\nimport { ScrollView } from \"react-native-virtualized-view\";\r\nimport { StatusBar } from \"expo-status-bar\";\r\nimport CustomModal from \"../components/CustomModal\";\r\nimport { shopCollections } from \"../data/shops\";\r\nimport { shoppingCategories } from \"../data/utils\";\r\nimport { getCategories } from \"../api/categories\";\r\nimport { getHome } from \"../api/home\";\r\nimport { useNavigation } from \"@react-navigation/native\";\r\nimport { getNews } from \"../api/news\";\r\nimport { useDispatch, useSelector } from \"react-redux\";\r\nimport Advertisements from \"../components/Advertisements\";\r\nimport { AntDesign } from \"@expo/vector-icons\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\nimport { addToCart } from \"../store/cartSlice\";\r\n\r\nconst HomeV1 = ({ navigation }) => {\r\n  const locale = \"en\";\r\n  const dispatch = useDispatch();\r\n  const toast = useToast();\r\n  const user = useSelector((state) => state.user);\r\n  const cart = useSelector((state) => state.cart);\r\n  const [products, setProducts] = useState([]);\r\n  const [categories, setCategories] = useState([]);\r\n\r\n  const [searchQuery, setSearchQuery] = useState(\"\");\r\n  const [modalVisible, setModalVisible] = useState(true);\r\n  const [news, setNews] = useState([]);\r\n\r\n  useEffect(() => {\r\n    getHome({ locale }).then((res) => {\r\n      setProducts(res.data.products);\r\n    });\r\n    getCategories({ locale }).then((res) => {\r\n      setCategories(res.data.categories);\r\n    });\r\n    getNews({ locale }).then((res) => {\r\n      setNews(res.data.newss);\r\n    });\r\n  }, []);\r\n\r\n  const handlePressGotIt = () => {\r\n    // Handle the logic when the \"GOT IT\" button is pressed\r\n    // For example, you can close the modal or perform any other action\r\n    setModalVisible(false);\r\n  };\r\n\r\n  const handleSearch = (text) => {\r\n    setSearchQuery(text);\r\n  };\r\n\r\n  const handleDisplayDetails = (id) => {\r\n    console.log({ pressed: id });\r\n    navigation.navigate(\"ProductDetails\", {\r\n      itemId: id,\r\n    });\r\n  };\r\n\r\n  const handleAddToCart = (product) => {\r\n    dispatch(addToCart({ product, qty: 1 }));\r\n    toast.show(\"Added an item to cart!\", {\r\n      type: \"success\",\r\n      placement: \"top\",\r\n      duration: 4000,\r\n      offset: 30,\r\n      style: { top: 50 },\r\n      animationType: \"slide-in\",\r\n    });\r\n  };\r\n\r\n  const renderNews = () => {\r\n    return (\r\n      <View>\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            justifyContent: \"space-between\",\r\n            marginVertical: 8,\r\n            alignItems: \"center\",\r\n          }}\r\n        >\r\n          <Text style={{ ...FONTS.body2 }}>All News</Text>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"NewsList\")}\r\n            style={{ flexDirection: \"row\", alignItems: \"center\" }}\r\n          >\r\n            <Text style={{ fontSize: 16, fontFamily: \"regular\" }}>See All</Text>\r\n            <View>\r\n              <MaterialIcons\r\n                name=\"keyboard-arrow-right\"\r\n                size={24}\r\n                color={COLORS.gray4}\r\n              />\r\n            </View>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <FlatList\r\n          horizontal={true}\r\n          data={news}\r\n          keyExtractor={(item) => item.id}\r\n          renderItem={({ item, index }) => (\r\n            <TouchableOpacity\r\n              key={index}\r\n              style={{\r\n                width: 300,\r\n                paddingHorizontal: 8,\r\n                marginHorizontal: 10,\r\n                alignItems: \"center\",\r\n                flexDirection: \"row\",\r\n                shadowColor: \"rgba(150, 150, 154,.4)\",\r\n                shadowOffset: {\r\n                  width: 12,\r\n                  height: 12,\r\n                },\r\n                shadowOpacity: 0.15,\r\n                shadowRadius: 30,\r\n                elevation: 0.1,\r\n                // borderRadius: 50,\r\n                // borderColor: COLORS.tertiaryGray,\r\n                // borderWidth: 1,\r\n              }}\r\n              onPress={() =>\r\n                navigation.navigate(\"NewsSingle\", {\r\n                  itemId: item.id,\r\n                })\r\n              }\r\n            >\r\n              <Image\r\n                source={{ uri: item.image }}\r\n                resizeMode=\"contain\"\r\n                style={{\r\n                  width: \"100%\",\r\n                  height: 200,\r\n                  // borderRadius: 22,\r\n                  marginRight: 10,\r\n                }}\r\n              />\r\n              {/* <Text style={{ fontSize: 16, fontFamily: \"medium\" }}>\r\n                {item.title}\r\n              </Text> */}\r\n            </TouchableOpacity>\r\n          )}\r\n        />\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderProductCategories = () => {\r\n    return (\r\n      <View>\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            justifyContent: \"space-between\",\r\n            marginVertical: 8,\r\n            alignItems: \"center\",\r\n          }}\r\n        >\r\n          <Text style={{ ...FONTS.body2 }}>All Categories</Text>\r\n          <TouchableOpacity\r\n            onPress={() => console.log(\"See all category\")}\r\n            style={{ flexDirection: \"row\", alignItems: \"center\" }}\r\n          >\r\n            <Text style={{ fontSize: 16, fontFamily: \"regular\" }}>See All</Text>\r\n            <View>\r\n              <MaterialIcons\r\n                name=\"keyboard-arrow-right\"\r\n                size={24}\r\n                color={COLORS.gray4}\r\n              />\r\n            </View>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <FlatList\r\n          horizontal={true}\r\n          // data={shoppingCategories}\r\n          data={categories.length && categories}\r\n          keyExtractor={(item) => item.id}\r\n          renderItem={({ item, index }) => (\r\n            <TouchableOpacity\r\n              key={index}\r\n              style={{\r\n                height: 60,\r\n                paddingHorizontal: 8,\r\n                marginHorizontal: 10,\r\n                alignItems: \"center\",\r\n                flexDirection: \"row\",\r\n                shadowColor: \"rgba(150, 150, 154,.4)\",\r\n                shadowOffset: {\r\n                  width: 12,\r\n                  height: 12,\r\n                },\r\n                shadowOpacity: 0.15,\r\n                shadowRadius: 30,\r\n                elevation: 0.1,\r\n                borderRadius: 50,\r\n                borderColor: COLORS.tertiaryGray,\r\n                borderWidth: 1,\r\n              }}\r\n            >\r\n              <Image\r\n                source={{ uri: item.image }}\r\n                resizeMode=\"contain\"\r\n                style={{\r\n                  height: 44,\r\n                  width: 44,\r\n                  borderRadius: 22,\r\n                  marginRight: 10,\r\n                }}\r\n              />\r\n              <Text style={{ fontSize: 16, fontFamily: \"medium\" }}>\r\n                {item.title}\r\n              </Text>\r\n            </TouchableOpacity>\r\n          )}\r\n        />\r\n      </View>\r\n    );\r\n  };\r\n  const renderSearchBar = () => {\r\n    return (\r\n      <View\r\n        style={{\r\n          width: SIZES.width - 32,\r\n          height: 62,\r\n          borderRadius: 10,\r\n          backgroundColor: COLORS.tertiaryGray,\r\n          alignItems: \"center\",\r\n          flexDirection: \"row\",\r\n        }}\r\n      >\r\n        <View\r\n          style={{\r\n            marginHorizontal: SIZES.padding,\r\n          }}\r\n        >\r\n          <Ionicons name=\"search\" size={24} color={COLORS.gray4} />\r\n        </View>\r\n        <TextInput\r\n          placeholder=\"Search products...\"\r\n          onChangeText={handleSearch}\r\n          placeholderTextColor={COLORS.gray5}\r\n          style={{\r\n            width: \"100%\",\r\n          }}\r\n        />\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderProducts = () => {\r\n    return (\r\n      <View style={{ height: \"auto\" }}>\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            justifyContent: \"space-between\",\r\n            marginVertical: 8,\r\n            alignItems: \"center\",\r\n          }}\r\n        >\r\n          <Text style={{ ...FONTS.body2 }}>Our Products</Text>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"ProductByKeywords\")}\r\n            style={{ flexDirection: \"row\", alignItems: \"center\" }}\r\n          >\r\n            <Text style={{ fontSize: 16, fontFamily: \"regular\" }}>See All</Text>\r\n            <View>\r\n              <MaterialIcons\r\n                name=\"keyboard-arrow-right\"\r\n                size={24}\r\n                color={COLORS.gray4}\r\n              />\r\n            </View>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <FlatList\r\n          nestedScrollEnabled\r\n          data={products?.length && products}\r\n          keyExtractor={(item) => item.id}\r\n          renderItem={({ item, index }) => (\r\n            <TouchableOpacity\r\n              onPress={() => handleDisplayDetails(item.id)}\r\n              key={index}\r\n              style={{\r\n                width: SIZES.width - 32,\r\n                borderColor: COLORS.tertiaryGray,\r\n                borderWidth: 1,\r\n                paddingBottom: 2,\r\n                marginBottom: 12,\r\n                borderRadius: 15,\r\n              }}\r\n            >\r\n              <Image\r\n                source={{ uri: item.image }}\r\n                style={{\r\n                  width: SIZES.width - 32,\r\n                  height: 136,\r\n                  borderRadius: 15,\r\n                }}\r\n              />\r\n              <Text\r\n                style={{\r\n                  fontSize: 18,\r\n                  fontFamily: \"regular\",\r\n                  marginVertical: 6,\r\n                  marginHorizontal: 10,\r\n                }}\r\n              >\r\n                {item.title}\r\n              </Text>\r\n              <Text\r\n                style={{\r\n                  fontSize: 18,\r\n                  fontFamily: \"regular\",\r\n                  marginVertical: 6,\r\n                  marginHorizontal: 10,\r\n                  color: \"orange\",\r\n                }}\r\n              >\r\n                EGP {item.price}\r\n              </Text>\r\n              <Text\r\n                style={{\r\n                  fontSize: 18,\r\n                  fontFamily: \"regular\",\r\n                  marginVertical: 6,\r\n                  marginHorizontal: 10,\r\n                  color: COLORS.primary,\r\n                }}\r\n              >\r\n                Discount: {item.discount}%\r\n              </Text>\r\n              {/* <View style={{ marginBottom: 4, flexDirection: \'row\' }}>\r\n                {item.keywords.map((keyword, index) => (\r\n                  <Text key={index} style={{ fontSize: 14, color: COLORS.gray5, textTransform: \"capitalize\" }}>\r\n                    {keyword}{index !== item.keywords.length - 1 ? \"-\" : \"\"}\r\n                  </Text>\r\n                ))}\r\n              </View> */}\r\n              <View\r\n                style={{\r\n                  flexDirection: \"row\",\r\n                  justifyContent: \"space-between\",\r\n                }}\r\n              >\r\n                <View style={{ flexDirection: \"row\", padding: 10 }}>\r\n                  <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n                    <Octicons name=\"star\" size={24} color={COLORS.primary} />\r\n                    <Text style={{ marginLeft: 8 }}>{item.rating}</Text>\r\n                  </View>\r\n                  <View\r\n                    style={{\r\n                      flexDirection: \"row\",\r\n                      alignItems: \"center\",\r\n                      marginHorizontal: SIZES.padding3,\r\n                    }}\r\n                  >\r\n                    <MaterialCommunityIcons\r\n                      name=\"truck-delivery-outline\"\r\n                      size={24}\r\n                      color={COLORS.primary}\r\n                    />\r\n                    <Text style={{ marginLeft: 8 }}>{item.shipping}</Text>\r\n                  </View>\r\n                  <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n                    <Fontisto\r\n                      name=\"stopwatch\"\r\n                      size={22}\r\n                      color={COLORS.primary}\r\n                    />\r\n                    <Text style={{ marginLeft: 8 }}>\r\n                      {item.deliveryTime} days\r\n                    </Text>\r\n                  </View>\r\n                </View>\r\n\r\n                <TouchableOpacity\r\n                  onPress={() => handleAddToCart(item)}\r\n                  style={{\r\n                    height: 30,\r\n                    width: 100,\r\n                    borderRadius: 15,\r\n                    alignItems: \"center\",\r\n                    justifyContent: \"center\",\r\n                    backgroundColor: COLORS.primary,\r\n                  }}\r\n                >\r\n                  <Text style={{ color: COLORS.white }}>Add to cart</Text>\r\n                </TouchableOpacity>\r\n              </View>\r\n            </TouchableOpacity>\r\n          )}\r\n        />\r\n      </View>\r\n    );\r\n  };\r\n  return (\r\n    <SafeAreaView style={styles.area}>\r\n      <View style={{ flex: 1, marginHorizontal: 16 }}>\r\n        <StatusBar hidden={true} />\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            justifyContent: \"space-between\",\r\n            alignItems: \"center\",\r\n            marginTop: 20,\r\n          }}\r\n        >\r\n          <View\r\n            style={{\r\n              flexDirection: \"row\",\r\n              alignItems: \"center\",\r\n            }}\r\n          >\r\n            <TouchableOpacity\r\n              onPress={() => navigation.toggleDrawer()}\r\n              style={{\r\n                height: 45,\r\n                width: 45,\r\n                borderRadius: 22.5,\r\n                alignItems: \"center\",\r\n                justifyContent: \"center\",\r\n                backgroundColor: COLORS.secondaryGray,\r\n              }}\r\n            >\r\n              <Image\r\n                source={icons.menu}\r\n                style={{\r\n                  height: 24,\r\n                  width: 24,\r\n                }}\r\n              />\r\n            </TouchableOpacity>\r\n            <View\r\n              style={{\r\n                flexDirection: \"column\",\r\n                marginLeft: 12,\r\n              }}\r\n            >\r\n              <Text\r\n                style={{\r\n                  fontSize: 12,\r\n                  fontWeight: \"bold\",\r\n                  color: COLORS.primary,\r\n                }}\r\n              >\r\n                DELIVER TO\r\n              </Text>\r\n              <View\r\n                style={{\r\n                  flexDirection: \"row\",\r\n                  alignItems: \"center\",\r\n                }}\r\n              >\r\n                <Text\r\n                  style={{\r\n                    fontSize: 14,\r\n                    fontWeight: \"regular\",\r\n                  }}\r\n                >\r\n                  Halab lab office\r\n                </Text>\r\n                <Image\r\n                  source={icons.arrowDown2}\r\n                  style={{\r\n                    height: 12,\r\n                    width: 12,\r\n                    marginLeft: 4,\r\n                  }}\r\n                />\r\n              </View>\r\n            </View>\r\n          </View>\r\n\r\n          <TouchableOpacity\r\n            style={{\r\n              height: 45,\r\n              width: 45,\r\n              borderRadius: 22.5,\r\n              alignItems: \"center\",\r\n              justifyContent: \"center\",\r\n              backgroundColor: COLORS.tertiaryBlack,\r\n            }}\r\n            onPress={() => navigation.navigate(\"Cart\")}\r\n          >\r\n            <View>\r\n              <View\r\n                style={{\r\n                  position: \"absolute\",\r\n                  top: -16,\r\n                  left: 12,\r\n                  backgroundColor: COLORS.primary,\r\n                  height: 25,\r\n                  width: 25,\r\n                  alignItems: \"center\",\r\n                  justifyContent: \"center\",\r\n                  borderRadius: 12.5,\r\n                  zIndex: 999,\r\n                }}\r\n              >\r\n                <Text\r\n                  style={{\r\n                    fontSize: 16,\r\n                    color: COLORS.white,\r\n                  }}\r\n                >\r\n                  {cart.totalQty}\r\n                </Text>\r\n              </View>\r\n              <Feather name=\"shopping-bag\" size={24} color={COLORS.white} />\r\n            </View>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <View\r\n          style={{\r\n            flexDirection: \"row\",\r\n            alignItems: \"center\",\r\n            marginVertical: 16,\r\n          }}\r\n        >\r\n          <Text style={{ fontSize: 16, fontFamily: \"regular\" }}>\r\n            {user.isLoggedIn && `Hey ${user.data.user.name}`}\r\n          </Text>\r\n        </View>\r\n        <ScrollView>\r\n          {/* {renderSearchBar()} */}\r\n          <Advertisements />\r\n          {renderProductCategories()}\r\n          {renderNews()}\r\n          {renderProducts()}\r\n        </ScrollView>\r\n      </View>\r\n      <CustomModal\r\n        modalVisible={modalVisible}\r\n        setModalVisible={setModalVisible}\r\n        onPressGotIt={handlePressGotIt}\r\n        code=\"#1243CD2\"\r\n      />\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  area: {\r\n    flex: 1,\r\n    backgroundColor: COLORS.white,\r\n  },\r\n});\r\n\r\nexport default HomeV1;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Login.js\r\nimport {\r\n  View,\r\n  Text,\r\n  TouchableOpacity,\r\n  Image,\r\n  ImageBackground,\r\n  StyleSheet,\r\n  TextInput,\r\n} from \"react-native\";\r\nimport React, { useState, useEffect } from \"react\";\r\nimport Checkbox from \"expo-checkbox\";\r\nimport * as Animatable from \"react-native-animatable\";\r\nimport Button from \"../components/Button\";\r\nimport { StatusBar } from \"expo-status-bar\";\r\nimport { useDispatch, useSelector } from \"react-redux\";\r\nimport { login } from \"../api/login\";\r\nimport { COLORS, FONTS, images, icons } from \"../constants\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport Input from \"../components/Input\";\r\nimport { useNavigation, useRoute } from \"@react-navigation/native\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\nimport { Alert } from \"react-native\";\r\nimport { setLogin } from \"../store/userSlice\";\r\n\r\nconst Login = () => {\r\n  const route = useRoute();\r\n  const navigation = useNavigation();\r\n  const toast = useToast();\r\n  const message = route?.params?.message && route?.params?.message;\r\n  const [isChecked, setChecked] = useState(false);\r\n  const [error, setError] = useState(null);\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const dispatch = useDispatch();\r\n  const [email, setEmail] = useState(\"ibrahimsamy308@gmail.com\");\r\n  const [password, setPassword] = useState(\"123456789\");\r\n\r\n  const handleSubmit = () => {\r\n    setIsLoading(true);\r\n    const values = { email, password };\r\n    login({ values })\r\n      .then((res) => {\r\n        // console.log({ res: res.data });\r\n        dispatch(setLogin(res.data));\r\n        navigation.navigate(\"LocationAccess\");\r\n        setIsLoading(false);\r\n      })\r\n      .catch((err) => {\r\n        const errors = err?.response.data;\r\n        const objKeys = Object.keys(errors);\r\n        const errorMessage = errors[objKeys[0]];\r\n        setError(errorMessage);\r\n        setIsLoading(false);\r\n      });\r\n  };\r\n\r\n  useEffect(() => {\r\n    if (message?.length) {\r\n      toast.show(message, {\r\n        type: \"success\",\r\n        placement: \"top\",\r\n        duration: 4000,\r\n        offset: 30,\r\n        style: { top: 50 },\r\n        animationType: \"slide-in\",\r\n      });\r\n    }\r\n    if (error) {\r\n      Alert.alert(\"An error occured\", error);\r\n    }\r\n    let timeout = setTimeout(() => {\r\n      setIsLoading(false);\r\n    }, 3000);\r\n    return () => clearTimeout(timeout);\r\n  }, [error]);\r\n\r\n  // implementing facebook authentication\r\n  const facebookAuthHandler = () => {\r\n    return null;\r\n  };\r\n\r\n  // implementing twitter authentication\r\n  const twitterAuthHandler = () => {\r\n    return null;\r\n  };\r\n\r\n  // implementing apple authentication\r\n  const appleAuthHandler = () => {\r\n    return null;\r\n  };\r\n\r\n  return (\r\n    <ImageBackground\r\n      source={images.background1}\r\n      style={{ flex: 1, backgroundColor: COLORS.blue }}\r\n    >\r\n      <StatusBar style=\"light\" />\r\n      <View style={commonStyles.header}>\r\n        <Text style={commonStyles.headerTitle}>Log In</Text>\r\n        <Text style={commonStyles.subHeaderTitle}>\r\n          Please sign in to your existing account\r\n        </Text>\r\n      </View>\r\n      <Animatable.View animation=\"fadeInUpBig\" style={commonStyles.footer}>\r\n        <Text style={commonStyles.inputHeader}>Email</Text>\r\n        <Input\r\n          id=\"email\"\r\n          value={email}\r\n          onChangeText={setEmail}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"example@gmail.com\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"email-address\"\r\n        />\r\n        <Text style={commonStyles.inputHeader}>Password</Text>\r\n        <Input\r\n          id=\"password\"\r\n          value={password}\r\n          onChangeText={setPassword}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"*************\"\r\n          placeholderTextColor={COLORS.black}\r\n          secureTextEntry={true}\r\n        />\r\n\r\n        <View style={commonStyles.checkBoxContainer}>\r\n          <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n            <Checkbox\r\n              style={commonStyles.checkbox}\r\n              value={isChecked}\r\n              color={isChecked ? COLORS.primary : COLORS.black}\r\n              onValueChange={setChecked}\r\n            />\r\n            <Text style={{ ...FONTS.body4 }}>Remenber me</Text>\r\n          </View>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"ForgotPassword\")}\r\n          >\r\n            <Text style={{ ...FONTS.body4, color: COLORS.primary }}>\r\n              Forgot Password ?\r\n            </Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <Button\r\n          title=\"LOG IN\"\r\n          isLoading={isLoading}\r\n          filled\r\n