ain\"\r\n            source={icons.more}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderUserProfile = () => {\r\n    return (\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginVertical: 16,\r\n        }}\r\n      >\r\n        <Image\r\n          source={images.avatar3}\r\n          resizeMode=\"contain\"\r\n          style={{\r\n            height: 100,\r\n            width: 100,\r\n            borderRadius: 50,\r\n          }}\r\n        />\r\n        <View style={{ marginLeft: 12 }}>\r\n          <Text style={{ ...FONTS.h4 }}>{user?.data?.user?.name}</Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 12,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n              marginVertical: 6,\r\n            }}\r\n          >\r\n            {user?.data?.user?.email}\r\n          </Text>\r\n        </View>\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderSettings = () => {\r\n    const navigation = useNavigation();\r\n    return (\r\n      <View style={{ flexDirection: \"column\" }}>\r\n        <View style={styles.container}>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"PersonalProfile\")}\r\n            style={styles.subContainer}\r\n          >\r\n            <View style={styles.subLeftContainer}>\r\n              <View style={styles.rounded}>\r\n                <Feather name=\"user\" size={24} color={COLORS.primary} />\r\n              </View>\r\n              <Text style={styles.textBody}>Personal Info</Text>\r\n            </View>\r\n            <View>\r\n              <Image source={icons.arrowRight} style={styles.iconRight} />\r\n            </View>\r\n          </TouchableOpacity>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigat