ainer}>\r\n              <View style={styles.rounded}>\r\n                <Feather name=\"shopping-bag\" size={24} color=\"#369BFF\" />\r\n              </View>\r\n              <Text style={styles.textBody}>Products List</Text>\r\n            </View>\r\n            <View>\r\n              <Image source={icons.arrowRight} style={styles.iconRight} />\r\n            </View>\r\n          </TouchableOpacity>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"NewsListAdmin\")}\r\n            style={styles.subContainer}\r\n          >\r\n            <View style={styles.subLeftContainer}>\r\n              <View style={styles.rounded}>\r\n                <Feather name=\"shopping-bag\" size={24} color=\"#369BFF\" />\r\n              </View>\r\n              <Text style={styles.textBody}>News List</Text>\r\n            </View>\r\n            <View>\r\n              <Image source={icons.arrowRight} style={styles.iconRight} />\r\n            </View>\r\n          </TouchableOpacity>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"AdminAdvertismentList\")}\r\n            style={styles.subContainer}\r\n          >\r\n            <View style={styles.subLeftContainer}>\r\n              <View style={styles.rounded}>\r\n                <Feather name=\"shopping-bag\" size={24} color=\"#369BFF\" />\r\n              </View>\r\n              <Text style={styles.textBody}>Advertisments List</Text>\r\n            </View>\r\n            <View>\r\n              <Image source={icons.arrowRight} style={styles.iconRight} />\r\n            </View>\r\n          </TouchableOpacity>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"AddAdvertisment\")}\r\n            style={styles.subContainer}\r\n          >\r\n            <View style={styles.subLeftContainer}>\r\n              <View style={styles.rounded}>\r\n                <Feather name=\"shopping-bag\" size={24} color=\"#369BFF\" />\r\n           