ew>\r\n          </TouchableOpacity>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"Settings\")}\r\n            style={styles.subContainer}\r\n          >\r\n            <View style={styles.subLeftContainer}>\r\n              <View style={styles.rounded}>\r\n                <Feather name=\"settings\" size={24} color=\"#413DFB\" />\r\n              </View>\r\n              <Text style={styles.textBody}>Settings</Text>\r\n            </View>\r\n            <View>\r\n              <Image source={icons.arrowRight} style={styles.iconRight} />\r\n            </View>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <View style={[styles.container, { marginBottom: 100 }]}>\r\n          <TouchableOpacity onPress={handleLogout} style={styles.subContainer}>\r\n            <View style={styles.subLeftContainer}>\r\n              <View style={styles.rounded}>\r\n                <MaterialIcons name=\"logout\" size={24} color=\"#FB4A59\" />\r\n              </View>\r\n              <Text style={styles.textBody}>Logout</Text>\r\n            </View>\r\n            <View>\r\n              <Image source={icons.arrowRight} style={styles.iconRight} />\r\n            </View>\r\n          </TouchableOpacity>\r\n        </View>\r\n      </View>\r\n    );\r\n  };\r\n  return (\r\n    <SafeAreaView style={{ flex: 1, backgroundColor: COLORS.white }}>\r\n      <StatusBar hidden={true} />\r\n      <View\r\n        style={{\r\n          flex: 1,\r\n          marginHorizontal: 16,\r\n        }}\r\n      >\r\n        {renderHeader()}\r\n        <ScrollView>\r\n          {renderUserProfile()}\r\n          {renderSettings()}\r\n        </ScrollView>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    backgroundColor: COLORS.gray7,\r\n    borderRadius: 16,\r\n    width: SIZES.width - 32,\r\n    paddingVertical: 8,\r\n    marginBottom: 12,\r\n  },\r\n  subContainer: {\r\n    flexDirection: \"row\",\r\n    justifyContent: \"space-between\",\r\n    alignItems: \"center\",\r\n    backgroundColor: COLORS.gray7,\r\n    marginVertical: 8,\r\n  },\r\n  subLeftContainer: {\r\n    flexDirection: \"row\",\r\n    alignItems: \"center\",\r\n  },\r\n  rounded: {\r\n    height: 40,\r\n    width: 40,\r\n    borderRadius: 20,\r\n    backgroundColor: COLORS.white,\r\n    alignItems: \"center\",\r\n    justifyContent: \"center\",\r\n    marginHorizontal: 12,\r\n  },\r\n  textBody: {\r\n    fontSize: 16,\r\n    fontFamily: \"regular\",\r\n    color: \"#32343E\",\r\n  },\r\n  iconRight: {\r\n    height: 16,\r\n    width: 16,\r\n    marginRight: 8,\r\n    tintColor: \"#747783\",\r\n  },\r\n});\r\nexport default Menu;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\MyOrders.js\r\nimport {\r\n  View,\r\n  Text,\r\n  TouchableOpacity,\r\n  Image,\r\n  useWindowDimensions,\r\n} from \"react-native\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport { COLORS, icons } from \"../constants\";\r\nimport { useNavigation } from \"@react-navigation/native\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { TabView, SceneMap, TabBar } from \"react-native-tab-view\";\r\nimport { FlatList } from \"react-native\";\r\nimport { history, orders } from \"../data/utils\";\r\nimport { StatusBar } from \"expo-status-bar\";\r\nimport { getPendingOrders } from \"../api/orders\";\r\nimport { useSelector } from \"react-redux\";\r\n\r\nconst OngoingRoute = () => {\r\n  const navigation = useNavigation();\r\n  const [orders, setOrders] = useState(null);\r\n  const user = useSelector((state) => state.user);\r\n  if (!user) return navigation.navigate(\"Menu\");\r\n  const token = user?.data?.access_token;\r\n\r\n  useEffect(() => {\r\n    getPendingOrders({ token, type: \"pending\" })\r\n      .then((res) => {\r\n        console.log({ res: res.data[0] });\r\n        setOrders(res.data);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err.response.data });\r\n      });\r\n  }, []);\r\n\r\n  return (\r\n    <View style={{ flex: 1 }}>\r\n      <FlatList\r\n        data={orders && orders}\r\n        keyExtractor={(item) => item.id}\r\n        renderItem={({ item, index }) => (\r\n          <View style={{ flexDirection: \"column\" }}>\r\n            <View\r\n              style={{\r\n                borderBottomColor: COLORS.gray,\r\n                borderBottomWidth: 1,\r\n                marginVertical: 12,\r\n                paddingBottom: 4,\r\n              }}\r\n            >\r\n              <Text\r\n                style={{\r\n                  fontSize: 14,\r\n                  fontFamily: \"bold\",\r\n                  textTransform: \"capitalize\",\r\n                }}\r\n              >\r\n                {item.status}\r\n              </Text>\r\n            </View>\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                justifyContent: \"space-between\",\r\n              }}\r\n            >\r\n              <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n                <Image\r\n                  source={{ uri: item?.order_Products[0]?.product?.image }}\r\n                  style={{\r\n                    height: 60,\r\n                    width: 60,\r\n                    borderRadius: 8,\r\n                  }}\r\n                />\r\n                <View style={{ marginLeft: 12 }}>\r\n                  <Text\r\n                    style={{\r\n                      fontSize: 14,\r\n                      fontWeight: \"bold\",\r\n                    }}\r\n                  >\r\n                    {item?.order_Products[0]?.product?.name}\r\n                  </Text>\r\n                  <View\r\n                    style={{\r\n                      flexDirection: \"row\",\r\n                      alignItems: \"center\",\r\n                      marginTop: 4,\r\n                    }}\r\n                  >\r\n                    <Text style={{ fontSize: 14, fontFamily: \"bold\" }}>\r\n                      EGP {item.total}\r\n                    </Text>\r\n                    <Text style={{ fontSize: 12, fontFamily: \"regular\" }}>\r\n                      {\" \"}\r\n                      | {item.order_Products.length} Items\r\n                    </Text>\r\n                  </View>\r\n                </View>\r\n              </View>\r\n              <Text\r\n                style={{\r\n                  fontSize: 14,\r\n                  textDecorationLine: \"underline\",\r\n                  textDecorationColor: COLORS.gray5,\r\n                  fontFamily: \"regular\",\r\n                }}\r\n              >\r\n                {item.address}\r\n              </Text>\r\n            </View>\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                justifyContent: \"space-between\",\r\n                marginVertical: 18,\r\n              }}\r\n            >\r\n              <TouchableOpacity\r\n                style={{\r\n                  height: 38,\r\n                  width: 140,\r\n                  alignItems: \"center\",\r\n                  justifyContent: \"center\",\r\n                  backgroundColor: COLORS.primary,\r\n                  borderRadius: 8,\r\n                }}\r\n                onPress={() =>\r\n                  navigation.navigate(\"MyOrderDetails\", {\r\n                    itemId: item.id,\r\n                  })\r\n                }\r\n              >\r\n                <Text\r\n                  style={{\r\n                    color: COLORS.white,\r\n                    fontSize: 14,\r\n                    fontFamily: \"regular\",\r\n                  }}\r\n                >\r\n                  Show Order\r\n                </Text>\r\n              </TouchableOpacity>\r\n            </View>\r\n          </View>\r\n        )}\r\n      />\r\n    </View>\r\n  );\r\n};\r\n\r\nconst HistoryRoute = () => {\r\n  const navigation = useNavigation();\r\n  const [history, setHistory] = useState(null);\r\n  const user = useSelector((state) => state.user);\r\n  if (!user) return navigation.navigate(\"Menu\");\r\n  const token = user?.data?.access_token;\r\n\r\n  useEffect(() => {\r\n    getPendingOrders({ token, type: \"delivered\" }).then((res) => {\r\n      setHistory(res.data);\r\n    });\r\n  }, []);\r\n\r\n  return (\r\n    <View style={{ flex: 1 }}>\r\n      <FlatList\r\n        data={history && history}\r\n        keyExtractor={(item) => item.id}\r\n        renderItem={({ item, index }) => (\r\n          <View style={{ flexDirection: \"column\" }}>\r\n            <View\r\n              style={{\r\n                borderBottomColor: COLORS.gray,\r\n                borderBottomWidth: 1,\r\n                marginVertical: 12,\r\n                flexDirection: \"row\",\r\n                paddingBottom: 4,\r\n              }}\r\n            >\r\n              <Text\r\n                style={{\r\n                  fontSize: 14,\r\n                  fontFamily: \"bold\",\r\n                  textTransform: \"capitalize\",\r\n                  color: item.status == \"Completed\" ? COLORS.green : COLORS.red,\r\n                }}\r\n              >\r\n                {item.status}\r\n              </Text>\r\n            </View>\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                justifyContent: \"space-between\",\r\n              }}\r\n            >\r\n              <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n                <Image\r\n                  source={{ uri: item.order_Products[0].product.image }}\r\n                  style={{\r\n                    height: 60,\r\n                    width: 60,\r\n                    borderRadius: 8,\r\n                  }}\r\n                />\r\n                <View style={{ marginLeft: 12 }}>\r\n                  <Text\r\n                    style={{\r\n                      fontSize: 14,\r\n                      fontWeight: \"bold\",\r\n                    }}\r\n                  >\r\n                    {item.name}\r\n                  </Text>\r\n                  <View\r\n                    style={{\r\n                      flexDirection: \"row\",\r\n                      alignItems: \"center\",\r\n                      marginTop: 4,\r\n                    }}\r\n                  >\r\n                    <Text style={{ fontSize: 14, fontFamily: \"bold\" }}>\r\n                      EGP {item.total}\r\n                    </Text>\r\n                    <Text\r\n                      style={{\r\n                        fontSize: 12,\r\n                        fontFamily: \"regular\",\r\n                        marginHorizontal: 2,\r\n                      }}\r\n                    >\r\n                      {\" \"}\r\n                      | {item.date}\r\n                    </Text>\r\n                    <Text style={{ fontSize: 12, fontFamily: \"regular\" }}>\r\n                      {\" \"}\r\n                      | {item.order_Products.length} Items\r\n                    </Text>\r\n                  </View>\r\n                </View>\r\n              </View>\r\n              <Text\r\n                style={{\r\n                  fontSize: 14,\r\n                  textDecorationLine: \"underline\",\r\n                  textDecorationColor: COLORS.gray5,\r\n                  fontFamily: \"regular\",\r\n                }}\r\n              >\r\n                {item.receipt}\r\n              </Text>\r\n            </View>\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                justifyContent: \"space-between\",\r\n                marginVertical: 18,\r\n              }}\r\n            >\r\n              <TouchableOpacity\r\n                style={{\r\n                  height: 38,\r\n                  width: 140,\r\n                  alignItems: \"center\",\r\n                  justifyContent: \"center\",\r\n                  backgroundColor: COLORS.primary,\r\n                  borderRadius: 8,\r\n                }}\r\n                onPress={() =>\r\n                  navigation.navigate(\"MyOrderDetails\", {\r\n                    itemId: item.id,\r\n                  })\r\n                }\r\n              >\r\n                <Text\r\n                  style={{\r\n                    color: COLORS.white,\r\n                    fontSize: 14,\r\n                    fontFamily: \"regular\",\r\n                  }}\r\n                >\r\n                  Show order\r\n                </Text>\r\n              </TouchableOpacity>\r\n            </View>\r\n          </View>\r\n        )}\r\n      />\r\n    </View>\r\n  );\r\n};\r\n\r\nconst renderScene = SceneMap({\r\n  first: OngoingRoute,\r\n  second: HistoryRoute,\r\n});\r\n\r\nconst MyOrders = ({ navigation }) => {\r\n  const layout = useWindowDimensions();\r\n  const user = useSelector((state) => state.user);\r\n  if (!user) return navigation.navigate(\"Menu\");\r\n  const [index, setIndex] = React.useState(0);\r\n\r\n  const [routes] = React.useState([\r\n    { key: \"first\", title: \"Ongoing\" },\r\n    { key: \"second\", title: \"History\" },\r\n  ]);\r\n\r\n  const renderTabBar = (props) => (\r\n    <TabBar\r\n      {...props}\r\n      indicatorStyle={{\r\n        backgroundColor: COLORS.primary,\r\n      }}\r\n      style={{\r\n        backgroundColor: \"#fff\",\r\n      }}\r\n      renderLabel={({ route, focused, color }) => (\r\n        <Text style={[{ color: focused ? COLORS.black : \"gray\" }]}>\r\n          {route.title}\r\n        </Text>\r\n      )}\r\n    />\r\n  );\r\n  const renderHeader = () => {\r\n    const navigation = useNavigation();\r\n    return (\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          justifyContent: \"space-between\",\r\n          marginTop: 20,\r\n          marginHorizontal: 16,\r\n        }}\r\n      >\r\n        <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.goBack()}\r\n            style={commonStyles.header1Icon}\r\n          >\r\n            <Image\r\n              resizeMode=\"contain\"\r\n              source={icons.arrowLeft}\r\n              style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n            />\r\n          </TouchableOpacity>\r\n          <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n            My Orders\r\n          </Text>\r\n        </View>\r\n        <TouchableOpacity\r\n          onPress={() => console.log(\"Pressed\")}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.more}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n      </View>\r\n    );\r\n  };\r\n  return (\r\n    <SafeAreaView style={{ flex: 1, backgroundColor: COLORS.white }}>\r\n      <StatusBar hidden={true} />\r\n      <View style={{ flex: 1 }}>\r\n        {renderHeader()}\r\n        <View\r\n          style={{\r\n            flex: 1,\r\n            marginHorizontal: 22,\r\n          }}\r\n        >\r\n          <TabView\r\n            navigationState={{ index, routes }}\r\n            renderScene={renderScene}\r\n            onIndexChange={setIndex}\r\n            initialLayout={{ width: layout.width }}\r\n            renderTabBar={renderTabBar}\r\n          />\r\n        </View>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default MyOrders;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\App.js\r\nimport \"expo-dev-client\";\r\nimport \"react-native-gesture-handler\";\r\nimport * as SplashScreen from \"expo-splash-screen\";\r\nimport { SafeAreaProvider } from \"react-native-safe-area-context\";\r\nimport { useFonts } from \"expo-font\";\r\nimport { useCallback } from \"react\";\r\nimport { FONTS } from \"./constants/fonts\";\r\nimport AppNavigation from \"./navigations/AppNavigation\";\r\nimport { LogBox } from \"react-native\";\r\nimport { Provider, useDispatch } from \"react-redux\";\r\nimport { store } from \"./store\";\r\nimport { saveCart } from \"./store/cartSlice\";\r\nimport { ToastProvider } from \"react-native-toast-notifications\";\r\n\r\n//Ignore all log notifications\r\nLogBox.ignoreAllLogs();\r\n\r\nSplashScreen.preventAutoHideAsync();\r\n\r\nexport default function App() {\r\n  const [fontsLoaded] = useFonts(FONTS);\r\n\r\n  const onLayoutRootView = useCallback(async () => {\r\n    if (fontsLoaded) {\r\n      await SplashScreen.hideAsync();\r\n    }\r\n  }, [fontsLoaded]);\r\n\r\n  if (!fontsLoaded) {\r\n    return null;\r\n  }\r\n\r\n  return (\r\n    <Provider store={store}>\r\n      <ToastProvider>\r\n        <SafeAreaProvider onLayout={onLayoutRootView}>\r\n          <AppNavigation />\r\n        </SafeAreaProvider>\r\n      </ToastProvider>\r\n    </Provider>\r\n  );\r\n}\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\navigations\\AppNavigation.js\r\nimport { createNativeStackNavigator } from \"@react-navigation/native-stack\";\r\nimport AsyncStorage from \"@react-native-async-storage/async-storage\";\r\nimport React, { useState, useEffect } from \"react\";\r\nimport {\r\n  Onboarding1,\r\n  Onboarding2,\r\n  Onboarding3,\r\n  Onboarding4,\r\n  Signup,\r\n  Verification,\r\n  Login,\r\n  StartUpScreen,\r\n  ForgotPassword,\r\n  ResetPassword,\r\n  LocationAccess,\r\n  SuccessRegister,\r\n  AddNewAddress,\r\n  Address,\r\n  Faqs,\r\n  PaymentDeclined,\r\n  PaymentMethod,\r\n  PaymentSuccess,\r\n  Settings,\r\n  EditProfile,\r\n  Cart,\r\n  EditCart,\r\n  AddNewPaymentCard,\r\n  PaymentCardSuccess,\r\n  PaymentCardDeclined,\r\n  SubmitQuestion,\r\n  UserReviews,\r\n  ProductByKeywords,\r\n  ShopView1,\r\n  ShopView2,\r\n  ProductDetailsV1,\r\n  ProductReviews,\r\n  ProductDetailsV2,\r\n  PaymentMethodNoCard,\r\n  TrackingOrderV1,\r\n  TrackingOrderV2,\r\n  Call,\r\n  Message,\r\n  Favourite,\r\n} from \"../screens\";\r\nimport { NavigationContainer } from \"@react-navigation/native\";\r\nimport BottomTabNavigation from \"./BottomTabNavigation\";\r\nimport PersonalProfile from \"../screens/PersonalProfile\";\r\nimport { useDispatch } from \"react-redux\";\r\nimport { saveCart } from \"../store/cartSlice\";\r\nimport { getCart } from \"../api/cartFn\";\r\nimport AddNewProduct from \"../screens/Admin/Products/AddNewProduct\";\r\nimport AddNews from \"../screens/Admin/News/AddNews\";\r\nimport ProductsListAdmin from \"../screens/Admin/Products/ProductsListAdmin\";\r\nimport NewsListAdmin from \"../screens/Admin/News/NewsListAdmin\";\r\nimport EditProductAdmin from \"../screens/Admin/Products/ProductEditAdmin\";\r\nimport AdminNewsShow from \"../screens/Admin/News/AdminNewsShow\";\r\nimport NewsAdminEdit from \"../screens/Admin/News/NewsAdminEdit\";\r\nimport AddAdvertisment from \"../screens/Admin/Advertisments/AddAdvertisment\";\r\nimport AdminAdvertismentEdit from \"../screens/Admin/Advertisments/AdminAdvertismentEdit\";\r\nimport AdminAdvertismentList from \"../screens/Admin/Advertisments/AdminAdvertismentList\";\r\nimport AdminAdvertismentShow from \"../screens/Admin/Advertisments/AdminAdvertismentShow\";\r\nimport AdvertismentSingle from \"../screens/AdvertismentSingle\";\r\nimport NewsList from \"../screens/NewsList\";\r\nimport NewsSingle from \"../screens/NewsSingle\";\r\nimport MyOrderDetails from \"../screens/MyOrderDetails\";\r\nimport PreRegister from \"../screens/PreRegister\";\r\n\r\nconst Stack = createNativeStackNavigator();\r\n\r\nconst AppNavigation = () => {\r\n  const dispatch = useDispatch();\r\n\r\n  const [isFirstLaunch, setIsFirstLaunch] = useState(null);\r\n  const [isLoading, setIsLoading] = useState(true);\r\n\r\n  useEffect(() => {\r\n    const checkIfFirstLaunch = async () => {\r\n      try {\r\n        const value = await AsyncStorage.getItem(\"alreadyLaunched\");\r\n        if (value === null) {\r\n          await AsyncStorage.setItem(\"alreadyLaunched\", \"true\");\r\n          setIsFirstLaunch(true);\r\n        } else {\r\n          setIsFirstLaunch(false);\r\n        }\r\n      } catch (error) {\r\n        setIsFirstLaunch(false);\r\n      }\r\n      setIsLoading(false); // Set loading state to false once the check is complete\r\n    };\r\n\r\n    checkIfFirstLaunch();\r\n  }, []);\r\n\r\n  // useEffect(() => {\r\n  //   dispatch(saveCart());\r\n  // }, []);\r\n\r\n  if (isLoading) {\r\n    return null; // Render a loader or any other loading state component\r\n  }\r\n\r\n  return (\r\n    <NavigationContainer>\r\n      <Stack.Navigator initialRouteName={\"BottomTabNavigation\"}>\r\n        <Stack.Screen\r\n          name=\"Onboarding1\"\r\n          component={Onboarding1}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Onboarding2\"\r\n          component={Onboarding2}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Onboarding3\"\r\n          component={Onboarding3}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Onboarding4\"\r\n          component={Onboarding4}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"Signup\"\r\n          component={Signup}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"PreRegister\"\r\n          component={PreRegister}\r\n          options={{ headerShown: false }}\r\n        />\r\n        <Stack.Screen\r\n          name=\"StartUpScreen\"\r\n          component={StartUpScreen}\r\n          options={{ headerShown: false }}\r\n        />\r\n       