n, storeLogout } from \"../../api/login\";\r\n// import { storeLogin } from \"../../api/login\";\r\n\r\nconst initialState = {\r\n  data: null,\r\n  isLoggedIn: false,\r\n};\r\n\r\nexport const loginSlice = createSlice({\r\n  name: \"login\",\r\n  initialState,\r\n  reducers: {\r\n    setLogin: (state, action) => {\r\n      storeLogin(action.payload);\r\n      state.data = action.payload;\r\n      state.isLoggedIn = true;\r\n    },\r\n    setLogout: (state, action) => {\r\n      storeLogout();\r\n      state.data = null;\r\n      state.isLoggedIn = false;\r\n    },\r\n  },\r\n});\r\n\r\n// Action creators are generated for each case reducer function\r\nexport const { setLogin, setLogout } = loginSlice.actions;\r\nconst loginReducer = loginSlice.reducer;\r\nexport default loginReducer;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\store\\cartSlice\\index.js\r\nimport { createSlice } from \"@reduxjs/toolkit\";\r\nimport { calcTotal } from \"../../helpers/settings\";\r\nimport { storeCart, getCart, removeCart } from \"../../api/cartFn\";\r\n\r\nconst initialState = {\r\n  items: [],\r\n  totalQty: 0,\r\n  totalPrice: 0,\r\n};\r\n\r\nconst cartSlice = createSlice({\r\n  name: \"cart\",\r\n  initialState,\r\n  reducers: {\r\n    addToCart: (state, action) => {\r\n      let product = action.payload.product;\r\n      const foundProduct = state.items?.find((item) => item.id === product.id);\r\n      let newArr;\r\n      if (foundProduct) {\r\n        newArr = state.items.map((item) => {\r\n          if (item.id === product.id) {\r\n            item.qty += action.payload.qty;\r\n            item[\"totalPrice\"] = item.qty * item.price;\r\n          }\r\n          return item;\r\n        });\r\n        state.totalPrice = calcTotal(newArr);\r\n        state.items = newArr;\r\n        storeCart(state);\r\n      } else {\r\n        product[\"qty\"] = action.payload.qty;\r\n        state.totalQty++;\r\n        product[\"totalPrice\"] = product[\"qty\"] * product.price;\r\n        state.totalPrice += product[\"totalPrice\"];\r\n        state.items = [...state.items, product];\r\n        storeCart(state);\r\n      }\r\n    },\r\n\r\n    saveCart: (state, action) => {\r\n      if (getCart()) {\r\n        let cart = getCart();\r\n        state.items = cart.items;\r\n        state.totalPrice = cart.totalPrice;\r\n        state.totalQty = cart.totalQty;\r\n      }\r\n    },\r\n\r\n    addQty: (state, action) => {\r\n      const newArr = state.items.map((item) => {\r\n        if (item.id === action.payload) {\r\n          item[\"qty\"]++;\r\n          item[\"totalPrice\"] = item.qty * item.price;\r\n        }\r\n        return item;\r\n      });\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.items = newArr;\r\n      storeCart(state);\r\n    },\r\n\r\n    decreaseQty: (state, action) => {\r\n      const newArr = state.items.map((item) => {\r\n        if (item.id === action.payload && item.qty > 1) {\r\n          item[\"qty\"]--;\r\n          item[\"totalPrice\"] = item.qty * item.price;\r\n        }\r\n        return item;\r\n      });\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.items = newArr;\r\n      storeCart(state);\r\n    },\r\n\r\n    removeItem: (state, action) => {\r\n      const newArr = state.items.filter((item) => item.id !== action.payload);\r\n      state.totalPrice = calcTotal(newArr);\r\n      state.totalQty--;\r\n      state.items = newArr;\r\n      storeCart(state);\r\n    },\r\n\r\n    emptyCart: (state, action) => {\r\n      state.items = [];\r\n      state.totalQty = 0;\r\n      state.totalPrice = 0;\r\n      removeCart();\r\n    },\r\n  },\r\n});\r\n\r\nexport const {\r\n  addToCart,\r\n  saveCart,\r\n  removeItem,\r\n  addQty,\r\n  decreaseQty,\r\n  setTotalPriceCart,\r\n  emptyCart,\r\n} = cartSlice.actions;\r\nconst cartReducer = cartSlice.reducer;\r\nexport default cartReducer;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\store\\userRegisterSlice\\index.js\r\nimport { createSlice } from \"@reduxjs/toolkit\";\r\n\r\nconst initialState = {\r\n  roleId: 2,\r\n};\r\n\r\nexport const userRegisterSlice = createSlice({\r\n  name: \"userRegister\",\r\n  initialState,\r\n  reducers: {\r\n    setUserRegister: (state, action) => {\r\n      state.roleId = action.payload;\r\n    },\r\n  },\r\n});\r\n\r\n// Action creators are generated for each case reducer function\r\nexport const { setUserRegister } = userRegisterSlice.actions;\r\nconst userRegisterReducer = userRegisterSlice.reducer;\r\nexport default userRegisterReducer;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Faqs.js\r\nimport { View, Text, TouchableOpacity, Image, LayoutAnimation, StyleSheet } from \'react-native\'\r\nimport React, { useState } from \'react\'\r\nimport { SafeAreaView } from \'react-native-safe-area-context\'\r\nimport { COLORS, SIZES, icons } from \'../constants\'\r\nimport { commonStyles } from \'../styles/CommonStyles\'\r\nimport { ScrollView } from \'react-native-virtualized-view\'\r\nimport Button from \'../components/Button\'\r\nimport { FaqsData } from \'../data/faqs\'\r\n\r\nconst Faqs = ({ navigation }) => {\r\n    /**\r\n     * Render FAQS header\r\n     */\r\n    function renderHeader() {\r\n        return (\r\n            <View style={{\r\n                flexDirection: \'row\',\r\n                alignItems: \'center\',\r\n                marginTop: 20,\r\n            }}>\r\n                <TouchableOpacity\r\n                    onPress={() => navigation.goBack()}\r\n                    style={commonStyles.header1Icon}\r\n                >\r\n                    <Image\r\n                        resizeMode=\'contain\'\r\n                        source={icons.arrowLeft}\r\n                        style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n                    />\r\n                </TouchableOpacity>\r\n                <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \'regular\' }}>FAQS</Text>\r\n            </View>\r\n        )\r\n    }\r\n\r\n    /***\r\n     * Render common question asked\r\n     */\r\n\r\n    function renderFAQS(){\r\n        const [expanded, setExpanded] = useState(-1);\r\n      \r\n        const toggleExpand = (index) => {\r\n          LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);\r\n          if (expanded === index) {\r\n            setExpanded(-1);\r\n          } else {\r\n            setExpanded(index);\r\n          }\r\n        };\r\n\r\n        \r\n        return (\r\n            <View style={styles.container}>\r\n            {FaqsData.map((faq, index) => (\r\n                <View key={index} style={styles.faqContainer}>\r\n                <TouchableOpacity onPress={() => toggleExpand(index)} activeOpacity={0.8}>\r\n                    <View style={styles.questionContainer}>\r\n                    <Text style={styles.question}>{faq.question}</Text>\r\n                    <Text style={styles.icon}>{expanded === index ? \'-\' : \'+\'}</Text>\r\n                    </View>\r\n                </TouchableOpacity>\r\n                {expanded === index && <Text style={styles.answer}>{faq.answer}</Text>}\r\n                </View>\r\n            ))}\r\n            </View>\r\n        )\r\n    }\r\n\r\n    /**Render Button to ask question */\r\n\r\n    function renderActionButtons (){\r\n        return (\r\n            <Button\r\n              title=\"ASK QUESTION\"\r\n              onPress={()=>navigation.navigate(\"SubmitQuestion\")}\r\n              filled\r\n              style={{\r\n                width: SIZES.width - 32,\r\n                backgroundColor: COLORS.red,\r\n                borderColor: COLORS.red,\r\n                marginVertical: 12\r\n              }}\r\n            />\r\n        )\r\n    }\r\n    return (\r\n        <SafeAreaView style={{\r\n            flex: 1,\r\n            backgroundColor: COLORS.white\r\n        }}>\r\n            <View style={{\r\n                flex: 1,\r\n                marginHorizontal: 16\r\n            }}>\r\n                {renderHeader()}\r\n                <ScrollView>\r\n                    {renderFAQS()}\r\n                    {renderActionButtons()}\r\n                </ScrollView>\r\n            </View>\r\n        </SafeAreaView>\r\n    )\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n    container: {\r\n        flex: 1,\r\n        backgroundColor: \'#f8f8f8\',\r\n        paddingHorizontal: 16,\r\n        paddingTop: 20,\r\n      },\r\n      faqContainer: {\r\n        marginBottom: 20,\r\n        backgroundColor: \'#fff\',\r\n        borderRadius: 8,\r\n        shadowColor: \'#000\',\r\n        shadowOffset: { width: 0, height: 1 },\r\n        shadowOpacity: 0.1,\r\n        shadowRadius: 1,\r\n        elevation: 1,\r\n      },\r\n      questionContainer: {\r\n        flexDirection: \'row\',\r\n        justifyContent: \'space-between\',\r\n        alignItems: \'center\',\r\n        paddingVertical: 10,\r\n        paddingHorizontal: 16,\r\n      },\r\n      question: {\r\n        flex: 1,\r\n        fontSize: 16,\r\n        fontFamily: \'medium\',\r\n        color: \'#333\',\r\n      },\r\n      icon: {\r\n        fontSize: 18,\r\n        color: \'#666\',\r\n      },\r\n      answer: {\r\n        fontSize: 14,\r\n        marginTop: 10,\r\n        paddingHorizontal: 16,\r\n        paddingBottom: 10,\r\n        fontFamily: \'regular\',\r\n        color: \'#666\',\r\n      },\r\n  });\r\n\r\nexport default Faqs\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Advertisments.js\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  Image,\r\n  ImageBackground,\r\n  SafeAreaView,\r\n  ScrollView,\r\n  StatusBar,\r\n  StyleSheet,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { getAdvertisments } from \"../api/advertisments\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { COLORS, icons } from \"../constants\";\r\n\r\nconst Advertisments = ({ navigation }) => {\r\n  const [ads, setAds] = useState(null);\r\n\r\n  useEffect(() => {\r\n    getAdvertisments({ locale: \"en\" }).then((res) => {\r\n      setAds(res.data.advertisements);\r\n    });\r\n  }, []);\r\n\r\n  const renderHeader = () => {\r\n    return (\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Advertisments\r\n        </Text>\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderAds = () => {\r\n    return ads?.map((item) => {\r\n      return (\r\n        <TouchableOpacity\r\n          onPress={() =>\r\n            navigation.navigate(\"AdvertismentSingle\", {\r\n              itemId: item.id,\r\n            })\r\n          }\r\n        >\r\n          <View style={{ borderRadius: 8, overflow: \"hidden\" }}>\r\n            <ImageBackground\r\n              source={{ uri: item.image }}\r\n              resizeMode=\"cover\"\r\n              style={styles.image}\r\n            >\r\n              <Text style={styles.text}>{item.product.title}</Text>\r\n            </ImageBackground>\r\n          </View>\r\n        </TouchableOpacity>\r\n      );\r\n    });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView style={styles.area}>\r\n      <StatusBar hidden={true} />\r\n      <View style={{ flex: 1, paddingHorizontal: 16 }}>\r\n        {renderHeader()}\r\n        <ScrollView style={{ marginTop: 30 }}>{renderAds()}</ScrollView>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  container: {\r\n    flex: 1,\r\n  },\r\n  area: {\r\n    flex: 1,\r\n    backgroundColor: COLORS.white,\r\n  },\r\n  image: {\r\n    flex: 1,\r\n    justifyContent: \"center\",\r\n    width: \"100%\",\r\n    height: 200,\r\n    borderRadius: 8,\r\n  },\r\n  text: {\r\n    color: \"white\",\r\n    fontSize: 22,\r\n    lineHeight: 84,\r\n    fontWeight: \"bold\",\r\n    textAlign: \"center\",\r\n    justifyContent: \"flex-end\",\r\n    backgroundColor: \"#000000c0\",\r\n    position: \"absolute\",\r\n    bottom: 0,\r\n    width: \"100%\",\r\n  },\r\n});\r\n\r\nexport default Advertisments;\r\n\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\Settings.js\r\nimport { View, Text, TouchableOpacity, Image, StyleSheet, Switch, Modal, FlatList } from \'react-native\'\r\nimport React, { useState } from \'react\'\r\nimport { SafeAreaView } from \'react-native-safe-area-context\'\r\nimport { COLORS, FONTS, SIZES, icons } from \'../constants\'\r\nimport { commonStyles } from \'../styles/CommonStyles\'\r\nimport { StatusBar } from \'expo-status-bar\'\r\n\r\nconst Settings = ({ navigation }) => {\r\n    /**\r\n     * Render header component\r\n     */\r\n    function renderHeader() {\r\n        return (\r\n            <View style={{\r\n                flexDirection: \'row\',\r\n                alignItems: \'center\',\r\n                marginTop: 20,\r\n            }}>\r\n                <TouchableOpacity\r\n                    onPress={() => navigation.goBack()}\r\n                    style={commonStyles.header1Icon}\r\n                >\r\n                    <Image\r\n                        resizeMode=\'contain\'\r\n                        source={icons.arrowLeft}\r\n                        style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n                    />\r\n                </TouchableOpacity>\r\n                <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \'regular\' }}>Settings</Text>\r\n            </View>\r\n        )\r\n    }\r\n\r\n    /***\r\n     * Render App Settings\r\n     */\r\n\r\n    function renderAppSettings() {\r\n        const [notificationEnabled, setNotificationEnabled] = useState(false);\r\n        const [darkModeEnabled, setDarkModeEnabled] = useState(false);\r\n        const [locationEnabled, setLocationEnabled] = useState(true);\r\n        const [currency, setCurrency] = useState(\'USD\');\r\n        const [language, setLanguage] = useState(\'English\');\r\n        const [isCurrencyModalVisible, setCurrencyModalVisible] = useState(false);\r\n        const [isLanguageModalVisible, setLanguageModalVisible] = useState(false);\r\n\r\n        const handleNotificationToggle = () => {\r\n            setNotificationEnabled((prevValue) => !prevValue);\r\n        };\r\n\r\n        const handleDarkModeToggle = () => {\r\n            setDarkModeEnabled((prevValue) => !prevValue);\r\n        };\r\n\r\n        const handleLocationToggle = () => {\r\n            setLocationEnabled((prevValue) => !prevValue);\r\n          };\r\n        \r\n          const handleCurrencyChange = (value) => {\r\n            setCurrency(value);\r\n            setCurrencyModalVisible(false);\r\n          };\r\n        \r\n          const handleLanguageChange = (value) => {\r\n            setLanguage(value);\r\n            setLanguageModalVisible(false);\r\n          };\r\n\r\n          const currencies = [\r\n            { id: \'USD\', name: \'USD - United States Dollar\' },\r\n            { id: \'EUR\', name: \'EUR - Euro\' },\r\n            { id: \'GBP\', name: \'GBP - British Pound Sterling\' },\r\n            { \"id\": \"JPY\", name: \"JPY - Japanese Yen\" },\r\n            { \"id\": \"CAD\", name: \"CAD - Canadian Dollar\" },\r\n            { \"id\": \"AUD\", name: \"AUD - Australian Dollar\" },\r\n            { \"id\": \"CHF\", name: \"CHF - Swiss Franc\" },\r\n            { \"id\": \"CNY\", name: \"CNY - Chinese Yuan\" }\r\n            // Add more currencies here\r\n          ];\r\n        \r\n          const languages = [\r\n            { id: \'English\', name: \'English\' },\r\n            { id: \'Spanish\', name: \'Spanish\' },\r\n            { id: \'French\', name: \'French\' },\r\n            { \"id\": \"German\", name: \"German\" },\r\n            { \"id\": \"Italian\", name: \"Italian\" },\r\n            { \"id\": \"Portuguese\", name: \"Portuguese\" },\r\n            { \"id\": \"Japanese\", name: \"Japanese\" },\r\n            { \"id\": \"Chinese\", name: \"Chinese\" }\r\n            // Add more languages here\r\n          ];\r\n\r\n          const renderCurrencyItem = ({ item }) => (\r\n            <TouchableOpacity\r\n              style={[styles.optionButton, currency === item.id && styles.optionButtonSelected]}\r\n              onPress={() => handleCurrencyChange(item.id)}\r\n            >\r\n              <Text style={[styles.optionText, currency === item.id && styles.optionTextSelected]}>{item.name}</Text>\r\n            </TouchableOpacity>\r\n          );\r\n        \r\n          const renderLanguageItem = ({ item }) => (\r\n            <TouchableOpacity\r\n              style={[styles.optionButton, language === item.id && styles.optionButtonSelected]}\r\n              onPress={() => handleLanguageChange(item.id)}\r\n            >\r\n              <Text style={[styles.optionText, language === item.id && styles.optionTextSelected]}>{item.name}</Text>\r\n            </TouchableOpacity>\r\n          );\r\n       \r\n        return (\r\n          <View style={styles.container}>\r\n            <View style={styles.settingContainer}>\r\n              <Text style={styles.settingLabel}>Enable Notifications</Text>\r\n              <Switch\r\n                value={notificationEnabled}\r\n                onValueChange={handleNotificationToggle}\r\n                thumbColor={notificationEnabled ? COLORS.primary : COLORS.white3}\r\n                trackColor={{ false: COLORS.white3, true: COLORS.primary }}\r\n              />\r\n            </View>\r\n      \r\n            <View style={styles.settingContainer}>\r\n              <Text style={styles.settingLabel}>Dark Mode</Text>\r\n              <Switch\r\n                value={darkModeEnabled}\r\n                onValueChange={handleDarkModeToggle}\r\n                thumbColor={darkModeEnabled ? COLORS.primary : COLORS.white3}\r\n                trackColor={{ false: COLORS.white3, true: COLORS.primary }}\r\n              />\r\n            </View>\r\n\r\n            <View style={styles.settingContainer}>\r\n        <Text style={styles.settingLabel}>Enable Location</Text>\r\n        <Switch\r\n          value={locationEnabled}\r\n          onValueChange={handleLocationToggle}\r\n          thumbColor={locationEnabled ? COLORS.primary : COLORS.white3}\r\n          trackColor={{false: COLORS.white3, true: COLORS.primary }}\r\n        />\r\n      </View>\r\n\r\n      <View style={styles.settingContainer}>\r\n        <Text style={styles.settingLabel}>Currency</Text>\r\n        <TouchableOpacity\r\n          style={styles.modalButton}\r\n          onPress={() => setCurrencyModalVisible(true)}\r\n        >\r\n          <Text style={styles.modalButtonText}>{currency}</Text>\r\n        </TouchableOpacity>\r\n        <Modal\r\n          visible={isCurrencyModalVisible}\r\n          animationType=\"slide\"\r\n          onRequestClose={() => setCurrencyModalVisible(false)}\r\n        >\r\n          <View style={styles.modalContainer}>\r\n            <Text style={styles.modalTitle}>Select Currency</Text>\r\n            <FlatList\r\n              data={currencies}\r\n              renderItem={renderCurrencyItem}\r\n              keyExtractor={(item) => item.id}\r\n              showsVerticalScrollIndicator={false}\r\n            />\r\n            <TouchableOpacity\r\n              style={styles.modalCloseButton}\r\n              onPress={() => setCurrencyModalVisible(false)}\r\n            >\r\n              <Text style={styles.modalCloseButtonText}>Close</Text>\r\n            </TouchableOpacity>\r\n          </View>\r\n        </Modal>\r\n      </View>\r\n\r\n      <View style={styles.settingContainer}>\r\n        <Text style={styles.settingLabel}>Language</Text>\r\n        <TouchableOpacity\r\n          style={styles.modalButton}\r\n          onPress={() => setLanguageModalVisible(true)}\r\n        >\r\n          <Text style={styles.modalButtonText}>{language}</Text>\r\n        </TouchableOpacity>\r\n        <Modal\r\n          visible={isLanguageModalVisible}\r\n          animationType=\"slide\"\r\n          onRequestClose={() => setLanguageModalVisible(false)}\r\n        >\r\n          <View style={styles.modalContainer}>\r\n            <Text style={styles.modalTitle}>Select Language</Text>\r\n            <FlatList\r\n              data={languages}\r\n              renderItem={renderLanguageItem}\r\n              keyExtractor={(item) => item.id}\r\n              showsVerticalScrollIndicator={false}\r\n            />\r\n            <TouchableOpacity\r\n              style={styles.modalCloseButton}\r\n              onPress={() => setLanguageModalVisible(false)}\r\n            >\r\n              <Text style={styles.modalCloseButtonText}>Close</Text>\r\n            </TouchableOpacity>\r\n          </View>\r\n        </Modal>\r\n      </View>\r\n\r\n    </View>\r\n    )\r\n    }\r\n\r\n  return (\r\n   <SafeAreaView style={{\r\n    flex: 1,\r\n    backgroundColor: COLORS.white\r\n   }}>\r\n       <StatusBar hidden={true} />\r\n        <View style={{\r\n            marginHorizontal: 12\r\n        }}>     \r\n            {renderHeader()}\r\n        </View>\r\n        {renderAppSettings()}\r\n   </SafeAreaView>\r\n  )\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n    container: {\r\n        flex: 1,\r\n        backgroundColor: \'#f8f8f8\',\r\n        padding: 16,\r\n        marginTop: 16\r\n      },\r\n      title: {\r\n        fontSize: 24,\r\n        fontWeight: \'bold\',\r\n        marginBottom: 24,\r\n        color: \'#333\',\r\n      },\r\n      settingContainer: {\r\n        flexDirection: \'row\',\r\n        justifyContent: \'space-between\',\r\n        alignItems: \'center\',\r\n        marginBottom: 16,\r\n      },\r\n      settingLabel: {\r\n        fontSize: 16,\r\n        color: \'#333\',\r\n        fontFamily: \'regular\'\r\n      },\r\n      modalButton: {\r\n        paddingVertical: 8,\r\n        paddingHorizontal: 12,\r\n        borderRadius: 8,\r\n        backgroundColor: \'#fff\',\r\n        marginRight: 10,\r\n        borderWidth: 1,\r\n        borderColor: COLORS.primary,\r\n        \r\n      },\r\n      modalButtonText: {\r\n        fontSize: 16,\r\n        color: COLORS.primary,\r\n        fontFamily: \'regular\'\r\n      },\r\n      modalContainer: {\r\n        flex: 1,\r\n        backgroundColor: COLORS.white,\r\n        padding: 16,\r\n      },\r\n      modalTitle: {\r\n        fontFamily: \'semiBold\',\r\n        fontSize: 16,\r\n        marginBottom: 16,\r\n        color: \'#333\',\r\n      },\r\n      modalCloseButton: {\r\n        backgroundColor: COLORS.primary,\r\n        borderRadius: 8,\r\n        paddingVertical: 12,\r\n        alignItems: \'center\',\r\n        marginTop: 16,\r\n      },\r\n      modalCloseButtonText: {\r\n        fontSize: 16,\r\n        fontFamily: \'semiBold\',\r\n        color: \'#fff\',\r\n      },\r\n      optionButton: {\r\n        paddingVertical: 8,\r\n        paddingHorizontal: 12,\r\n        borderRadius: 8,\r\n        backgroundColor: \'#fff\',\r\n        marginRight: 10,\r\n        borderWidth: 1,\r\n        borderColor: \'rgba(0,0,0,.5)\',\r\n        marginBottom: 8,\r\n      },\r\n      optionButtonSelected: {\r\n        backgroundColor: COLORS.primary,\r\n        borderWidth: 0,\r\n      },\r\n      optionText: {\r\n        fontSize: 18,\r\n        color: \'rgba(0,0,0,.5)\',\r\n      },\r\n      optionTextSelected: {\r\n        color: \'#fff\',\r\n      },\r\n  });\r\n\r\nexport default Settings\r\nE:\\xampp\\htdocs\\Shoppa\\Shoppa\\screens\\ProductDetailsV1.js\r\nimport { View, Image, TouchableOpacity, Text, StyleSheet } from \"react-native\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport { COLORS, SIZES, icons, images } from \"../constants\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { useNavigation, useRoute } from \"@react-navigation/native\";\r\nimport {\r\n  Ionicons,\r\n  MaterialCommunityIcons,\r\n  Fontisto,\r\n  Octicons,\r\n} from \"@expo/vector-icons\";\r\nimport { ScrollView } from \"react-native-virtualized-view\";\r\nimport Button from \"../components/Button\";\r\nimport ColorPicker from \"../components/ColorPicker\";\r\nimport { StatusBar } from \"expo-status-bar\";\r\nimport { getProduct } from \"../api/products\";\r\n\r\nconst ProductDetailsV1 = () => {\r\n  const { postId } = useRoute().params;\r\n  const navigation = useNavigation();\r\n  const [product, setProduct] = useState({});\r\n\r\n  useEffect(() => {\r\n    getProduct({ locale: \"en\", itemId: postId }).then((res) => {\r\n      setProduct(res.data.product);\r\n    });\r\n  }, []);\r\n\r\n  const renderHeader = () => {\r\n    return (\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Details\r\n        </Text>\r\n      </View>\r\n    );\r\n  };\r\n\r\n  const renderProductDetails = () => {\r\n    const [isFavourite, setIsFavourite] = useState(false);\r\n    const [quantity, setQuantity] = useState(2);\r\n    const navigation = useNavigation();\r\n    const [selectedColor, setSelectedColor] = useState(\"#FF0000\"); // Default color\r\n\r\n    const handleColorChange = (color) => {\r\n      setSelectedColor(color);\r\n    };\r\n\r\n    const [selectedSize, setSelectedSize] = useState(null);\r\n    const handleSizeSelection = (size) => {\r\n      setSelectedSize(size);\r\n    };\r\n    return (\r\n      <View style={{ marginVertical: 16 }}>\r\n        {/* Product details images */}\r\n        <View>\r\n          <Image\r\n            source={{uri: product.image}}\r\n            resizeMode=\"contain\"\r\n            style={{\r\n              width: SIZES.width - 32,\r\n              height: 184,\r\n              borderRadius: 32,\r\n              borderColor: COLORS.gray6,\r\n              borderWidth: 1,\r\n            }}\r\n          />\r\n        </View>\r\n        {/* Product details infos */}\r\n        <View style={{ marginVertical: 16 }}>\r\n          <View\r\n            style={{\r\n              flexDirection: \"column\",\r\n              height: 47,\r\n              borderRadius: 50,\r\n              paddingHorizontal: 16,\r\n              alignItems: \"center\",\r\n              borderWidth: 1,\r\n              borderColor: COLORS.gray6,\r\n            }}\r\n          >\r\n            <Text\r\n              style={{\r\n                marginLeft: 12,\r\n                fontFamily: \"regular\",\r\n                fontSize: 14,\r\n              }}\r\n            >\r\n              Company name: {product.company_name}\r\n            </Text>\r\n            <Text\r\n              style={{\r\n                marginLeft: 12,\r\n                fontFamily: \"regular\",\r\n                fontSize: 14,\r\n              }}\r\n            >\r\n              Category: {product?.category?.title}\r\n            </Text>\r\n          </View>\r\n          <Text\r\n            style={{\r\n              fontSize: 18,\r\n              fontFamily: \"bold\",\r\n              textTransform: \"capitalize\",\r\n              marginVertical: 10,\r\n            }}\r\n          >\r\n            {product && product.title}\r\n          </Text>\r\n          <View\r\n            style={{\r\n              backgroundColor: COLORS.tertiaryGray,\r\n              borderRadius: 24,\r\n              paddingHorizontal: 10,\r\n              paddingVertical: 16,\r\n            }}\r\n          >\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                justifyContent: \"space-between\",\r\n                // marginBottom: 16,\r\n              }}\r\n            >\r\n              <Text style={{ fontSize: 28, fontFamily: \"regular\" }}>EGP {product.price}</Text>\r\n              \r\n            </View>\r\n          </View>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            {product.description}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Factory name: {product.factory_name}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Type: {product.type}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Active substances: {product.active_substances}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Retail units no: {product.retail_units_no}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Weight: {product.weight}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Price: {product.price}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Stock: {product.stock}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Discount: {product.discount}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Pharmaceutical form: {product.pharmaceutical_form}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Way used: {product.way_used}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Geographical distribution: {product.geographical_distribution}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Is active: {product.is_active ? \'true\' : \'false\'}\r\n          </Text>\r\n          <Text\r\n            style={{\r\n              fontSize: 13,\r\n              fontFamily: \"regular\",\r\n              color: COLORS.gray5,\r\n            }}\r\n          >\r\n            Is agent: {product.is_agent ? \'true\' : \'false\'}\r\n          </Text>\r\n\r\n          {/* <View style={{ flexDirection: \"row\", marginTop: 16 }}>\r\n            <TouchableOpacity\r\n              onPress={() => navigation.navigate(\"ProductReviews\")}\r\n              style={{ flexDirection: \"row\", alignItems: \"center\" }}\r\n            >\r\n              <Octicons name=\"star\" size={24} color={COLORS.primary} />\r\n              <Text style={{ marginLeft: 8 }}>4.7</Text>\r\n            </TouchableOpacity>\r\n            <View\r\n              style={{\r\n                flexDirection: \"row\",\r\n                alignItems: \"center\",\r\n                marginHorizontal: SIZES.padding3,\r\n              }}\r\n            >\r\n              <MaterialCommunityIcons\r\n                name=\"truck-delivery-outline\"\r\n                size={24}\r\n                color={COLORS.primary}\r\n              />\r\n              <Text style={{ marginLeft: 8 }}>Free</Text>\r\n            </View>\r\n            <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n              <Fontisto name=\"stopwatch\" size={22} color={COLORS.primary} />\r\n              <Text style={{ marginLeft: 8 }}>3 days</Text>\r\n            </View>\r\n          </View> */}\r\n\r\n          {/* <View\r\n            style={{\r\n              flexDirection: \"row\",\r\n              alignItems: \"center\",\r\n              marginBottom: 10,\r\n            }}\r\n          >\r\n            <Text\r\n              style={{ fontSize: 14, fontFamily: \"regular\", marginRight: 20 }}\r\n            >\r\n              SIZE:{\" \"}\r\n            </Text>\r\n\r\n            <View style={{ flexDirection: \"row\", marginVertical: 18 }}>\r\n              <TouchableOpacity\r\n                style={[\r\n                  styles.checkboxContainer,\r\n                  selectedSize === \"X\" && styles.selectedCheckbox,\r\n                ]}\r\n                onPress={() => handleSizeSelection(\"X\")}\r\n              >\r\n                <Text style={[selectedSize === \"X\" && styles.checkboxText]}>\r\n                  X\r\n                </Text>\r\n              </TouchableOpacity>\r\n\r\n              <TouchableOpacity\r\n                style={[\r\n                  styles.checkboxContainer,\r\n                  selectedSize === \"XL\" && styles.selectedCheckbox,\r\n                ]}\r\n                onPress={() => handleSizeSelection(\"XL\")}\r\n              >\r\n                <Text style={[selectedSize === \"XL\" && styles.checkboxText]}>\r\n                  XL\r\n                </Text>\r\n              </TouchableOpacity>\r\n\r\n              <TouchableOpacity\r\n                style={[\r\n                  styles.checkboxContainer,\r\n                  selectedSize === \"M\" && styles.selectedCheckbox,\r\n                ]}\r\n                onPress={() => handleSizeSelection(\"M\")}\r\n              >\r\n                <Text style={[selectedSize === \"M\" && styles.checkboxText]}>\r\n                  M\r\n                </Text>\r\n              </TouchableOpacity>\r\n            </View>\r\n          </View>\r\n\r\n          <View>\r\n            <Text\r\n              style={{\r\n                fontSize: 14,\r\n                fontFamily: \"regular\",\r\n                textTransform: \"uppercase\",\r\n              }}\r\n            >\r\n              Select color:{\" \"}\r\n            </Text>\r\n            <ColorPicker onColorChange={handleColorChange} />\r\n          </View> */}\r\n\r\n          \r\n        </View>\r\n      </View>\r\n    );\r\n  };\r\n  return (\r\n    <SafeAreaView style={{ flex: 1, backgroundColor: COLORS.white }}>\r\n      <StatusBar hidden={true} />\r\n      <View style={{ flex: 1, paddingHorizontal: 16 }}>\r\n        {renderHeader()}\r\n        <ScrollView>{renderProductDetails()}</ScrollView>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  checkboxContainer: {\r\n    alignItems: \"center\",\r\n    justifyContent: \"center\",\r\n    height: 48,\r\n    width: 48,\r\n    borderRadius: 22,\r\n    borderWidth: 1,\r\n    borderColor: COLORS.gray,\r\n    backgroundColor: COLORS.gray,\r\n    marginRight: 12,\r\n  },\r\n  selectedCheckbox: {\r\n    backgroundColor: COLORS.primary,\r\n  },\r\n  checkboxText: {\r\n    color: COLORS.white,\r\n    fontSize: 16,\r\n    fontFamily: \"regular\",\r\n  },\r\n  selectedColorSwatch: {\r\n    width: 50,\r\n    height: 50,\r\n    borderRadius: 25,\r\n    borderWidth: 1,\r\n    borderColor: \"#ccc\",\r\n    marginTop: 20,\r\n  },\r\n  selectedColorText: {\r\n    fontSize: 18,\r\n    marginTop: 10,\r\n  },\r\n});\r\n\r\nexport default ProductDetailsV1;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Appointments\\index.js\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  FlatList,\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport { getAppointments } from \"../../api/appointments\";\r\n\r\nconst Appointments = ({ navigation }) => {\r\n  const [items, setItems] = useState(null);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n\r\n  useEffect(() => {\r\n    getAppointments({ token })\r\n      .then((res) => {\r\n        setItems(res.data);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ error: err?.respon