tCourse({ courseId }).then((res) => {\r\n      console.log({ course: res.data });\r\n      setCourse(res.data.course);\r\n    });\r\n  }, []);\r\n\r\n  const onToggleSwitch = () => setIsReady(!isReady);\r\n\r\n  const handleSubmit = () => {\r\n    createBooking({\r\n      values: {\r\n        course_id: courseId,\r\n        category_id: course.category_id,\r\n        choose_zone: selectedZone.name,\r\n        is_appointment: selectedIsAppointments.name,\r\n        appointment: selectedAppointment.name,\r\n      },\r\n      token,\r\n    })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        toast.show(\"Made a booking successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        setBooking(\"\");\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err?.response.data.substring(0, 400) });\r\n      });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Request a booking\r\n        </Text>\r\n      </View>\r\n      <View\r\n        style={{\r\n          alignItems: \"center\",\r\n          padding: 15,\r\n        }}\r\n      >\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Are you ready?\r\n        </Text>\r\n        <Switch\r\n          value={isReady}\r\n          isChecked={isReady}\r\n          onValueChange={onToggleSwitch}\r\n        />\r\n        {!isReady && (\r\n          <Fragment>\r\n            <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n              tell us when you are ready\r\n            </Text>\r\n            <TouchableOpacity onPress={() => setOpen(true)}>\r\n              <Input\r\n                id=\"description\"\r\n                value={new Date(date).toLocaleString(\"en-GB\", {\r\n                  year: \"numeric\",\r\n                  month: \"2-digit\",\r\n                  day: \"numeric\",\r\n                })}\r\n                onChangeText={setDate}\r\n                autoCapitalize=\"none\"\r\n                placeholder=\"Pick a date\"\r\n                placeholderTextColor={COLORS.black}\r\n                keyboardType=\"default\"\r\n                editable={false}\r\n              />\r\n            </TouchableOpacity>\r\n            <DatePickerModal\r\n              locale=\"en\"\r\n              mode=\"single\"\r\n              visible={open}\r\n              onDismiss={onDismissSingle}\r\n              date={date}\r\n              onConfirm={onConfirmSingle}\r\n            />\r\n          </Fragment>\r\n        )}\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Select your zone\r\n        </Text>\r\n        <SelectDropdown\r\n          data={zones}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const foundAppoint = zones.find(\r\n              (item) => item.name === selectedItem.name\r\n            );\r\n            setSelectedZone(foundAppoint);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>\r\n                  {selectedZone.value}\r\n                </Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item.value}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Select your appointment\r\n        </Text>\r\n        <SelectDropdown\r\n          data={isAppointments}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const foundAppoint = appointments.find(\r\n              (item) => item.name === selectedItem.name\r\n            );\r\n            console.log({ foundAppoint });\r\n            setSelectedAppointments(foundAppoint);\r\n            setSelectedIsAppointments(selectedItem);\r\n            setSelectedAppointment(foundAppoint.value[0]);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>\r\n                  {selectedIsAppointments.value}\r\n                </Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item.value}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n        {selectedIsAppointments.name !== \"any\" && (\r\n          <Fragment>\r\n            <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n              Select your time\r\n            </Text>\r\n            <SelectDropdown\r\n              data={selectedAppointments.value}\r\n              onSelect={(selectedItem, index) => {\r\n                console.log({ selectedItem });\r\n                const foundAppoint = appointments.find(\r\n                  (item) => item.name === selectedItem.name\r\n                );\r\n                console.log({ selectedItem });\r\n                // setSelectedAppointments(foundAppoint);\r\n                // setSelectedAppointment(foundAppoint);\r\n              }}\r\n              renderButton={(selectedItem, isOpened) => {\r\n                return (\r\n                  <View style={styles.dropdownButtonStyle}>\r\n                    <Text style={styles.dropdownButtonTxtStyle}>\r\n                      {selectedItem\r\n                        ? selectedItem.value\r\n                        : selectedAppointment.value}\r\n                    </Text>\r\n                  </View>\r\n                );\r\n              }}\r\n              renderItem={(item, index, isSelected) => {\r\n                return (\r\n                  <View\r\n                    style={{\r\n                      ...styles.dropdownItemStyle,\r\n                      ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                    }}\r\n                  >\r\n                    <Text style={styles.dropdownItemTxtStyle}>\r\n                      {item.value}\r\n                    </Text>\r\n                  </View>\r\n                );\r\n              }}\r\n              showsVerticalScrollIndicator={false}\r\n              dropdownStyle={styles.dropdownMenuStyle}\r\n            />\r\n          </Fragment>\r\n        )}\r\n        <Button\r\n          title=\"Submit\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  dropdownButtonStyle: {\r\n    width: \"100%\",\r\n    height: 50,\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 12,\r\n    flexDirection: \"row\",\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingHorizontal: 12,\r\n    marginTop: 20,\r\n  },\r\n  dropdownButtonTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 18,\r\n    fontWeight: \"500\",\r\n    color: \"#151E26\",\r\n  },\r\n  dropdownButtonArrowStyle: {\r\n    fontSize: 28,\r\n  },\r\n  dropdownButtonIconStyle: {\r\n    fontSize: 28,\r\n    marginRight: 8,\r\n  },\r\n  dropdownMenuStyle: {\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 8,\r\n  },\r\n  dropdownItemStyle: {\r\n    width: \"100%\",\r\n    flexDirection: \"row\",\r\n    paddingHorizontal: 12,\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingVertical: 8,\r\n  },\r\n  dropdownItemTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 18,\r\n    fontWeight: \"500\",\r\n    color: \"#151E26\",\r\n  },\r\n  dropdownItemIconStyle: {\r\n    fontSize: 28,\r\n    marginRight: 8,\r\n  },\r\n});\r\n\r\nexport default CreateBooking;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Bookings\\index.js\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  FlatList,\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport { getBookings } from \"../../api/bookings\";\r\nimport Card from \"../../components/Card\";\r\nimport { Heading } from \"native-base\";\r\nimport Loader from \"../../components/Loader\";\r\n\r\nconst Bookings = ({ navigation }) => {\r\n  const [categories, setCategories] = useState(null);\r\n  const [loading, setLoading] = useState(true);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n\r\n  useEffect(() => {\r\n    getBookings({ token, locale: \"en\" })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        setCategories(res.data.bookings);\r\n        setLoading(false);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ error: err?.response.data.substring(0, 100) });\r\n      });\r\n  }, []);\r\n\r\n  if (loading) {\r\n    return <Loader />;\r\n  }\r\n\r\n  const displayBookings = () => {\r\n    return categories?.map((item) => {\r\n      return (\r\n        <View key={item.id}>\r\n          <Heading fontSize=\"xl\" p=\"4\" pb=\"3\">\r\n            {item.category.title}\r\n          </Heading>\r\n          <FlatList\r\n            style={{ marginStart: 20 }}\r\n            horizontal={true}\r\n            data={item?.category.courses}\r\n            keyExtractor={(item) => item.id}\r\n            renderItem={({ item }) => <Card key={item.id} course={item} />}\r\n          />\r\n        </View>\r\n      );\r\n    });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Bookings\r\n        </Text>\r\n      </View>\r\n      <View>{displayBookings()}</View>\r\n      <View>\r\n        <Text>{categories && categories[0].title}</Text>\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default Bookings;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Complains\\CreateComplain.js\r\nimport React, { useState } from \"react\";\r\nimport {\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport Input from \"../../components/Input\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\nimport Button from \"../../components/Button\";\r\nimport { createComplain } from \"../../api/complains\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { useToast } from \"react-native-toast-notifications\";\r\n\r\nconst CreateComplain = ({ navigation }) => {\r\n  const [complain, setComplain] = useState(\"\");\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n  const toast = useToast();\r\n\r\n  const handleSubmit = () => {\r\n    createComplain({ values: complain, token })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        toast.show(\"Made a complain successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        setComplain(\"\");\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err?.response.data.substring(0, 100) });\r\n      });\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          Create a complain\r\n        </Text>\r\n      </View>\r\n      <View\r\n        style={{\r\n          alignItems: \"center\",\r\n          padding: 15,\r\n        }}\r\n      >\r\n        <Text style={commonStyles.inputHeader}>Write your complain</Text>\r\n        <Input\r\n          id=\"complain\"\r\n          value={complain}\r\n          onChangeText={setComplain}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your complain here\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n          maxLength={100}\r\n        />\r\n        <Button\r\n          title=\"Submit\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default CreateComplain;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Complains\\index.j\r\nimport React, { useEffect, useState } from \"react\";\r\nimport {\r\n  FlatList,\r\n  Image,\r\n  SafeAreaView,\r\n  Text,\r\n  TouchableOpacity,\r\n  View,\r\n} from \"react-native\";\r\nimport { getComplains } from \"../../api/complains\";\r\nimport { useSelector } from \"react-redux\";\r\nimport { COLORS, icons } from \"../../constants\";\r\nimport { commonStyles } from \"../../styles/CommonStyles\";\r\n\r\nconst Complains = ({ navigation }) => {\r\n  const [items, setItems] = useState(null);\r\n  const user = useSelector((state) => state.user);\r\n  const token = user?.data.access_token;\r\n\r\n  useEffect(() => {\r\n    getComplains({ token })\r\n      .then((res) => {\r\n        console.log({ resData: res.data });\r\n        setItems(res.data);\r\n      })\r\n      .catch((err) => {\r\n        console.log({ error: err?.response.data.substring(0, 100) });\r\n      });\r\n  }, []);\r\n\r\n  return (\r\n    <SafeAreaView>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style={{ height: 24, width: 24, tintColor: COLORS.black }}\r\n          />\r\n        </TouchableOpacity>\r\n        <Text style={{ marginLeft: 12, fontSize: 17, fontFamily: \"regular\" }}>\r\n          My complains\r\n        </Text>\r\n      </View>\r\n      <View>\r\n        <FlatList\r\n          // style={{ marginStart: 20 }}\r\n          horizontal={false}\r\n          data={items}\r\n          keyExtractor={(item) => item.id}\r\n          renderItem={({ item }) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  borderStyle: \"solid\",\r\n                  borderWidth: 3,\r\n                  borderColor: \"gray\",\r\n                  paddingHorizontal: 20,\r\n                  paddingVertical: 10,\r\n                  marginBottom: 20,\r\n                  marginHorizontal: 10,\r\n                }}\r\n              >\r\n                <Text>{item.complain}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n        />\r\n      </View>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nexport default Complains;\r\n\r\nE:\\xampp\\htdocs\\expo_sch