om \"expo-document-picker\";\r\n\r\nconst JobApply = ({ route, navigation }) => {\r\n  const { jobId, jobTitle } = route.params;\r\n  const toast = useToast();\r\n  const [isDatePickerVisible, setDatePickerVisibility] = useState(false);\r\n  const [email, setEmail] = useState(\"\");\r\n  const [name, setName] = useState(\"\");\r\n  const [phone, setPhone] = useState(\"\");\r\n  const [address, setAddress] = useState(\"\");\r\n  const [appliedFor, setAppliedFor] = useState(\"\");\r\n  const [dateOfBirth, setDateOfBirth] = useState(new Date(Date.now()));\r\n  const [nationality, setNationality] = useState(\"\");\r\n  const [idNumber, setIdNumber] = useState(\"\");\r\n  const [maritalStatus, setMaritalStatus] = useState(\"Single\");\r\n  const [gender, setGender] = useState(\"male\");\r\n  const [word, setWord] = useState(\"\");\r\n  const [excel, setExcel] = useState(\"\");\r\n  const [powerpoint, setPowerpoint] = useState(\"\");\r\n  const [explainMainTasks, setExplainMainTasks] = useState(\"\");\r\n  const [factorsPrompted, setFactorsPrompted] = useState(\"\");\r\n  const [period, setPeriod] = useState(\"\");\r\n  const [wordValue, setWordValue] = useState(\"poor\");\r\n  const [excelValue, setExcelValue] = useState(\"poor\");\r\n  const [powerpointValue, setPowerpointValue] = useState(\"poor\");\r\n  const [isLoading, setIsLoading] = useState(false);\r\n  const [success, setSuccess] = useState(false);\r\n  const [qualifications, setQualifications] = useState(\"\");\r\n  const [trainingCourses, setTrainingCourses] = useState(\"\");\r\n  const [langauges, setLangauges] = useState(\"\");\r\n  const [references, setReferences] = useState(\"\");\r\n  const [practicalExperiences, setPracticalExperiences] = useState(\"\");\r\n  const [file, setFile] = useState(null);\r\n\r\n  console.log({ file });\r\n\r\n  const handlePickDocument = async () => {\r\n    let result = await DocumentPicker.getDocumentAsync({\r\n      type: \"application/pdf\",\r\n    });\r\n    console.log({ result: result.assets });\r\n    if (result.canceled) {\r\n      console.log(\"cancelled\");\r\n    } else {\r\n      setFile(result.assets[0]);\r\n    }\r\n  };\r\n  const maritalStatuses = [\"single\", \"married\", \"divorced\", \"widowed\"];\r\n  const genders = [\"male\", \"female\"];\r\n\r\n  const handleConfirm = (date) => {\r\n    hideDatePicker();\r\n    setDateOfBirth(date);\r\n  };\r\n\r\n  const hideDatePicker = () => {\r\n    setDatePickerVisibility(false);\r\n  };\r\n\r\n  const onChange = (event, newDate) => {\r\n    setDateOfBirth(newDate);\r\n  };\r\n\r\n  const handleSubmit = () => {\r\n    setIsLoading(true);\r\n    const values = {\r\n      email,\r\n      name,\r\n      phone,\r\n      address,\r\n      jobOpp_id: jobId,\r\n      file,\r\n    };\r\n    applyJob({ values })\r\n      .then((res) => {\r\n        console.log({ res: res.data });\r\n        setIsLoading(false);\r\n        setSuccess(true);\r\n        toast.show(\"Applied successfully!\", {\r\n          type: \"success\",\r\n          placement: \"top\",\r\n          duration: 4000,\r\n          offset: 30,\r\n          style: { top: 50 },\r\n          animationType: \"slide-in\",\r\n        });\r\n        handleReset();\r\n      })\r\n      .catch((err) => {\r\n        console.log({ err: err.response.data.substring(0, 500) });\r\n        setIsLoading(false);\r\n      });\r\n  };\r\n\r\n  const handleReset = () => {\r\n    setEmail(\"\");\r\n    setName(\"\");\r\n    setPhone(\"\");\r\n    setAddress(\"\");\r\n  };\r\n\r\n  return (\r\n    <SafeAreaView style={{ flex: 1 }}>\r\n      <View\r\n        style={{\r\n          flexDirection: \"row\",\r\n          alignItems: \"center\",\r\n          marginTop: 20,\r\n        }}\r\n      >\r\n        <TouchableOpacity\r\n          onPress={() => navigation.goBack()}\r\n          style={commonStyles.header1Icon}\r\n        >\r\n          <Image\r\n            resizeMode=\"contain\"\r\n            source={icons.arrowLeft}\r\n            style=