",\r\n            day: \"2-digit\",\r\n          })}\r\n          isLoading={isLoading}\r\n          onPress={() => setDatePickerVisibility(true)}\r\n          style={{ ...commonStyles.btn, marginTop: 20 }}\r\n        />\r\n        <DateTimePickerModal\r\n          testID=\"dateTimePicker\"\r\n          isVisible={isDatePickerVisible}\r\n          mode=\"date\"\r\n          onConfirm={handleConfirm}\r\n          onCancel={hideDatePicker}\r\n          value={dateOfBirth}\r\n          is24Hour={false}\r\n          display=\"default\"\r\n          onChange={onChange}\r\n        />\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Your marital status\r\n        </Text>\r\n        <SelectDropdown\r\n          data={maritalStatuses}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const marital = maritalStatuses.find(\r\n              (item) => item === selectedItem\r\n            );\r\n            setMaritalStatus(marital);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>\r\n                  {maritalStatus}\r\n                </Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Your Gender\r\n        </Text>\r\n        <SelectDropdown\r\n          data={genders}\r\n          onSelect={(selectedItem, index) => {\r\n            console.log({ selectedItem });\r\n            const marital = genders.find((item) => item === selectedItem);\r\n            setGender(marital);\r\n          }}\r\n          renderButton={(selectedItem, isOpened) => {\r\n            return (\r\n              <View style={styles.dropdownButtonStyle}>\r\n                <Text style={styles.dropdownButtonTxtStyle}>{gender}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          renderItem={(item, index, isSelected) => {\r\n            return (\r\n              <View\r\n                style={{\r\n                  ...styles.dropdownItemStyle,\r\n                  ...(isSelected && { backgroundColor: \"#D2D9DF\" }),\r\n                }}\r\n              >\r\n                <Text style={styles.dropdownItemTxtStyle}>{item}</Text>\r\n              </View>\r\n            );\r\n          }}\r\n          showsVerticalScrollIndicator={false}\r\n          dropdownStyle={styles.dropdownMenuStyle}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          How good are you in Microsoft Word?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={wordValue}\r\n          onChange={(nextValue) => {\r\n            setWordValue(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"poor\" my=\"1\">\r\n            Poor\r\n          </Radio>\r\n          <Radio value=\"good\" my=\"1\">\r\n            Good\r\n          </Radio>\r\n          <Radio value=\"excellent\" my=\"1\">\r\n            Excellent\r\n          </Radio>\r\n        </Radio.Group>\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          How good are you in Microsoft Excel?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={excelValue}\r\n          onChange={(nextValue) => {\r\n            setExcelValue(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"poor\" my=\"1\">\r\n            Poor\r\n          </Radio>\r\n          <Radio value=\"good\" my=\"1\">\r\n            Good\r\n          </Radio>\r\n          <Radio value=\"excellent\" my=\"1\">\r\n            Excellent\r\n          </Radio>\r\n        </Radio.Group>\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          How good are you in Microsoft Powerpoint?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={powerpointValue}\r\n          onChange={(nextValue) => {\r\n            setPowerpointValue(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"poor\" my=\"1\">\r\n            Poor\r\n          </Radio>\r\n          <Radio value=\"good\" my=\"1\">\r\n            Good\r\n          </Radio>\r\n          <Radio value=\"excellent\" my=\"1\">\r\n            Excellent\r\n          </Radio>\r\n        </Radio.Group>\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Describe your responsbilities in last job\r\n        </Text>\r\n        <Input\r\n          id=\"reason\"\r\n          value={explainMainTasks}\r\n          onChangeText={setExplainMainTasks}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your description\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          The factors prompted you to apply for this job\r\n        </Text>\r\n        <Input\r\n          id=\"reason\"\r\n          value={explainMainTasks}\r\n          onChangeText={setExplainMainTasks}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"Write your factors here\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          Available day or night?\r\n        </Text>\r\n        <Radio.Group\r\n          name=\"myRadioGroup\"\r\n          value={period}\r\n          onChange={(nextValue) => {\r\n            setPeriod(nextValue);\r\n          }}\r\n        >\r\n          <Radio value=\"1\" my=\"1\">\r\n            Day\r\n          </Radio>\r\n          <Radio value=\"0\" my=\"1\">\r\n            Night\r\n          </Radio>\r\n        </Radio.Group>\r\n\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          qualifications\r\n        </Text>\r\n        <Input\r\n          id=\"qualifications\"\r\n          value={qualifications}\r\n          onChangeText={setQualifications}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Your qualifications:ex. Engineering, specialization: ex. computer science, university: ex. AAST, graduation date: 2024-06-29, gpa: ex. 3.5\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          languages\r\n        </Text>\r\n        <Input\r\n          id=\"langauges\"\r\n          value={langauges}\r\n          onChangeText={setLangauges}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, English: reading (advanced), writing (intermediate), listening (weak), conversation (intermediate), Arabic: ...\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          training courses\r\n        </Text>\r\n        <Input\r\n          id=\"trainingCourses\"\r\n          value={trainingCourses}\r\n          onChangeText={setTrainingCourses}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, Teacher, certification title, certification date, entity\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          practical experience\r\n        </Text>\r\n        <Input\r\n          id=\"practicalExperiences\"\r\n          value={practicalExperiences}\r\n          onChangeText={setPracticalExperiences}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, entity, employment type, work time, reason of resignation\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n        <Text style={{ ...commonStyles.inputHeader, marginTop: 20 }}>\r\n          references\r\n        </Text>\r\n        <Input\r\n          id=\"references\"\r\n          value={references}\r\n          onChangeText={setReferences}\r\n          autoCapitalize=\"none\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"default\"\r\n          placeholder=\"Example, the company name, manager name, your work type, manager number\"\r\n          multiline={true}\r\n          numberOfLines={4}\r\n        />\r\n\r\n        <View style={{ marginTop: 20 }}>\r\n          <TouchableOpacity onPress={handlePickDocument}>\r\n            <Text style={commonStyles.inputHeader}>Upload CV</Text>\r\n          </TouchableOpacity>\r\n          {file ? <Text>{file.name}</Text> : null}\r\n        </View>\r\n\r\n        <Button\r\n          title=\"SUBMIT\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={{ ...commonStyles.btn, marginTop: 50 }}\r\n        />\r\n      </ScrollView>\r\n    </SafeAreaView>\r\n  );\r\n};\r\n\r\nconst styles = StyleSheet.create({\r\n  dropdownButtonStyle: {\r\n    width: \"100%\",\r\n    height: 50,\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 12,\r\n    flexDirection: \"row\",\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingHorizontal: 12,\r\n    marginTop: 20,\r\n  },\r\n  dropdownButtonTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 18,\r\n    fontWeight: \"500\",\r\n    color: \"#151E26\",\r\n    textTransform: \"capitalize\",\r\n  },\r\n  dropdownButtonArrowStyle: {\r\n    fontSize: 28,\r\n  },\r\n  dropdownButtonIconStyle: {\r\n    fontSize: 28,\r\n    marginRight: 8,\r\n  },\r\n  dropdownMenuStyle: {\r\n    backgroundColor: \"#E9ECEF\",\r\n    borderRadius: 8,\r\n  },\r\n  dropdownItemStyle: {\r\n    width: \"100%\",\r\n    flexDirection: \"row\",\r\n    paddingHorizontal: 12,\r\n    justifyContent: \"center\",\r\n    alignItems: \"center\",\r\n    paddingVertical: 8,\r\n  },\r\n  dropdownItemTxtStyle: {\r\n    flex: 1,\r\n    fontSize: 18,\r\n    fontWeight: \"500\",\r\n    color: \"#151E26\",\r\n    textTransform: \"capitalize\",\r\n  },\r\n  dropdownItemIconStyle: {\r\n    fontSize: 28,\r\n    marginRight: 8,\r\n  },\r\n});\r\n\r\nexport default JobApply;\r\n\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\Posts\\index.js\r\nimport React, { useEffect, useState } from \'react\'\r\nimport { ScrollView, View } from \'react-native\';\r\nimport { Heading } from \"native-base\";\r\nimport { getPosts } from \'../../api/posts\';\r\nimport PostCard from \'../../components/PostCard\';\r\nimport Loader from \'../../components/Loader\';\r\n\r\nconst PostsPage = () => {\r\n    const [loading, setLoading] = useState(true);\r\n    const [posts, setPosts] = useState(null);\r\n\r\n    useEffect(() => {\r\n        getPosts({ locale: \'en\' }).then(res => {\r\n            setPosts(res.data.posts);\r\n   