uchableOpacity\r\n                        onPress={() => navigation.goBack()}\r\n                        style={{ ...commonStyles.header1Icon, position: \'absolute\', top: 34, left: 14, backgroundColor: \'#9f7aea\' }}\r\n                    >\r\n                        <Image\r\n                            resizeMode=\"contain\"\r\n                            source={icons.arrowLeft}\r\n                            style={{ height: 24, width: 24, tintColor: COLORS.white }}\r\n                        />\r\n                    </TouchableOpacity>\r\n                </View>\r\n                <View style={styles.detailsContainer}>\r\n                    <Heading fontSize=\"xl\" p=\"4\" pb=\"3\">\r\n                        {post?.title}\r\n                    </Heading>\r\n                    <View style={{ marginStart: 15 }}>\r\n                        <Text>{post?.description}</Text>\r\n                    </View>\r\n                </View>\r\n            </ScrollView>\r\n        </View>\r\n    )\r\n}\r\n\r\nconst styles = StyleSheet.create({\r\n    imageCountainer: {\r\n        position: \'relative\'\r\n    },\r\n    image: {\r\n        width: \'100%\',\r\n        height: 270,\r\n    },\r\n    detailsContainer: {\r\n        borderTopLeftRadius: 40,\r\n        borderTopRightRadius: 40,\r\n        marginTop: -12,\r\n        paddingTop: 6,\r\n        paddingHorizontal: 15,\r\n        backgroundColor: \'#fff\',\r\n        minHeight: 610\r\n    },\r\n    descriptionContainer: {\r\n        width: \"100%\"\r\n    },\r\n    descriptionWrapper: {\r\n        backgroundColor: \'#9f7aea\',\r\n        width: \'100%\',\r\n        height: 50,\r\n        display: \'flex\',\r\n        flexDirection: \'row\',\r\n        alignItems: \'center\',\r\n        justifyContent: \'space-between\',\r\n        paddingHorizontal: 15,\r\n        borderRadius: 50\r\n    }\r\n})\r\n\r\nexport default PostDetails\r\nE:\\xampp\\htdocs\\expo_school_basic\\screens\\CourseDetails.js\r\nimport { Heading, Image, ScrollView, StatusBar, Text, View } from \"native-base\";\r\nimport React, { useEffect, useState } from \"react\";\r\nimport { ImageBackground, StyleSheet, TouchableOpacity } from \"react-native\";\r\nimport * as Animatable from \"react-native-animatable\";\r\nimport { getCourse } from \"../api/courses\";\r\nimport { COLORS, icons } from \"../constants\";\r\nimport { commonStyles } from \"../styles/CommonStyles\";\r\nimport { SafeAreaView } from \"react-native-safe-area-context\";\r\nimport Loader from \"../components/Loader\";\r\nimport Button from \"../components/Button\";\r\nimport { useSelector } from \"react-redux\";\r\n\r\nconst CourseDetails = ({ route, navigation }) => {\r\n  const { courseId } = route.params;\r\n  const [course, setCourse] = useState(null);\r\n  const [loading, setLoading] = useState(true);\r\n  const [clicked, setClicked] = useState(false);\r\n  const user = useSelector((state) => state.user);\r\n\r\n  useEffect(() => {\r\n    getCourse({ locale: \"en\", courseId }).then((res) => {\r\n      setCourse(res.data.course);\r\n      setLoading(false);\r\n    });\r\n  }, []);\r\n\r\n  if (loading) {\r\n    return <Loader />;\r\n  }\r\n\r\n  const handleSubmit = () => {};\r\n\r\n  return (\r\n    <View>\r\n      <ScrollView>\r\n        <View>\r\n          <View style={styles.imageCountainer}>\r\n            <Image\r\n              style={styles.image}\r\n              source={{ uri: course?.image }}\r\n              alt={course?.title}\r\n            />\r\n          </View>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.goBack()}\r\n            style={{\r\n              ...commonStyles.header1Icon,\r\n              position: \"absolute\",\r\n              top: 34,\r\n              left: 14,\r\n              backgroundColor: \"#9f7aea\",\r\n            }}\r\n          >\r\n            <Image\r\n              resizeMode=\"contain\"\r\n              source={icons.arrowLeft}\r\n              style={{ height: 24, width: 24, tintColor: COLORS.white }}\r\n            />\r\n          </TouchableOpacity>\r\n        </View>\r\n        <View style={styles.detailsContainer}>\r\n          <Heading fontSize=\"xl\" p=\"4\" pb=\"3\">\r\n            {course?.title}\r\n          </Heading>\r\n          <View style={styles.categoryContainer}>\r\n            <View style={styles.categoryWrapper}>\r\n              <Text style={{ color: \"#fff\" }}>\r\n                Category: {course?.category}\r\n              </Text>\r\n              <Text style={{ color: \"#fff\" }}>${course?.course_price}</Text>\r\n            </View>\r\n          </View>\r\n          <View>\r\n            <View style={styles.titleWrapper}>\r\n              <Heading fontSize=\"md\" p=\"4\" pb=\"3\">\r\n                {course?.program?.title}\r\n              </Heading>\r\n            </View>\r\n            {course?.program?.levels.map((item) => {\r\n              return (\r\n                <View style={{ paddingStart: 15 }}>\r\n                  <Text>{item.title}</Text>\r\n                </View>\r\n              );\r\n            })}\r\n          </View>\r\n\r\n          {course?.courseAppointments.map((item) => {\r\n            return (\r\n              <View style={{ paddingStart: 15, marginTop: 15 }}>\r\n                <Heading fontSize={\"lg\"} style={{ marginBottom: 5 }}>\r\n                  Start date: {item?.start_date}\r\n                </Heading>\r\n                <Heading fontSize={\"lg\"}>End date: {item?.end_date}</Heading>\r\n                <Heading fontSize={\"lg\"}>Code: {item?.course_code}</Heading>\r\n              </View>\r\n            );\r\n          })}\r\n          <Button\r\n            title=\"Book\"\r\n            isLoading={clicked}\r\n            filled\r\n            onPress={() =>\r\n              user.isLoggedIn\r\n                ? navigation.navigate(\"CreateBooking\", {\r\n                    courseId,\r\n                  })\r\n                : navigation.navigate(\"Login\")\r\n      