\n  // implementing apple authentication\r\n  const appleAuthHandler = () => {\r\n    return null;\r\n  };\r\n\r\n  return (\r\n    <ImageBackground\r\n      source={images.background1}\r\n      style={{ flex: 1, backgroundColor: COLORS.blue }}\r\n    >\r\n      <StatusBar style=\"light\" />\r\n      <View style={commonStyles.header}>\r\n        <Text style={commonStyles.headerTitle}>Log In</Text>\r\n        <Text style={commonStyles.subHeaderTitle}>\r\n          Please sign in to your existing account\r\n        </Text>\r\n      </View>\r\n      <Animatable.View animation=\"fadeInUpBig\" style={commonStyles.footer}>\r\n        <Text style={commonStyles.inputHeader}>Email</Text>\r\n        <Input\r\n          id=\"email\"\r\n          value={email}\r\n          onChangeText={setEmail}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"example@gmail.com\"\r\n          placeholderTextColor={COLORS.black}\r\n          keyboardType=\"email-address\"\r\n        />\r\n        <Text style={commonStyles.inputHeader}>Password</Text>\r\n        <Input\r\n          id=\"password\"\r\n          value={password}\r\n          onChangeText={setPassword}\r\n          autoCapitalize=\"none\"\r\n          placeholder=\"*************\"\r\n          placeholderTextColor={COLORS.black}\r\n          secureTextEntry={true}\r\n        />\r\n\r\n        <View style={commonStyles.checkBoxContainer}>\r\n          <View style={{ flexDirection: \"row\", alignItems: \"center\" }}>\r\n            <Checkbox\r\n              style={commonStyles.checkbox}\r\n              value={isChecked}\r\n              color={isChecked ? COLORS.primary : COLORS.black}\r\n              onValueChange={setChecked}\r\n            />\r\n            <Text style={{ ...FONTS.body4 }}>Remenber me</Text>\r\n          </View>\r\n          <TouchableOpacity\r\n            onPress={() => navigation.navigate(\"ForgotPassword\")}\r\n          >\r\n            <Text style={{ ...FONTS.body4, color: COLORS.primary }}>\r\n              Forgot Password ?\r\n            </Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n\r\n        <Button\r\n          title=\"LOG IN\"\r\n          isLoading={isLoading}\r\n          filled\r\n          onPress={handleSubmit}\r\n          style={commonStyles.btn}\r\n        />\r\n        <View style={commonStyles.center}>\r\n          <Text style={{ ...FONTS.body4, color: COLORS.black }}>\r\n            Don\'t have an account?{\" \"}\r\n          </Text>\r\n          <TouchableOpacity onPress={() => navigation.navigate(\"Signup\")}>\r\n            <Text style={{ ...FONTS.body4, color: COLORS.primary }}>\r\n              SIGN UP\r\n            </Text>\r\n          </TouchableOpacity>\r\n        </View>\r\n        {/* <Text style={{ ...FONTS.body4, color: COLORS.black, textAlign: \'center\' }}>Or</Text>\r\n\r\n        <View style={commonStyles.socialContainer}>\r\n          <TouchableOpacity\r\n            onPress={facebookAuthHandler}\r\n            style={commonStyles.socialIconContainer}\r\n          >\r\n            <Image\r\n              source={icons.facebook}\r\n              resizeMode=\"contain\"\r\n              style={commonStyles.socialLogo}\r\n            />\r\n          </TouchableOpacity>\r\n          <TouchableOpacity\r\n            onPress={twitterAuthHandler}\r\n            style={commonStyles.socialIconContainer}\r\n          >\r\n            <Image\r\n              source={icons.twitter}\r\n              resizeMode=\"contain\"\r\n              style={commonStyles.socialLogo}\r\n            />\r\n          </TouchableOpacity>\r\n          <TouchableOpacity\r\n            onPress={appleAuthHandler}\r\n            style={commonStyles.socialIconContainer}\r\n          >\r\n            <Image\r\n              source={icons.apple}\r\n              resizeMode=\"contain\"\r\n              style={commonStyles.socialLogo}\r\n            />\r\n          </TouchableOpacity>\r\n        </View> */}\r\n      </Animatable.View>\r\n  