Links` = \'$.ajax({\\n    url: `/products/${productId}`, // The route with the product ID\\n    type: \\\'GET\\\',                   // HTTP method\\n    success: function(response) {\\n        // Handle success response\\n        console.log(response);\\n        // You can update your HTML here with the product data\\n    },\\n    error: function(xhr, status, error) {\\n        // Handle error response\\n        console.log(\\\"Error: \\\" + error);\\n    }\\n});\', `created_at` = \'2024-09-20 01:15:22\', `id` = \'17\', `isOverthinking` = \'0\', `script` = \'\', `title` = \'Ajax get\', `updated_at` = \'2025-07-13 05:58:06\'\r\n                WHERE id = 17;\r\n            \r\n','2025-07-13 19:05:39','2025-07-13 19:05:39'),(807,'\r\n                UPDATE yousabte_workspace.issues\r\n                SET `codeLinks` = \'$(document).ready(function() {\\r\\n    $(\\\'#contactForm\\\').submit(function(event) {\\r\\n      event.preventDefault();\\r\\n      var formData = $(this).serialize();\\r\\n      $.ajax({\\r\\n        type: \\\'POST\\\',\\r\\n        url: \\\'{{route(\\\"message.store\\\")}}\\\',\\r\\n        data: formData,\\r\\n        dataType: \\\'json\\\',\\r\\n        success: function(response) {\\r\\n          if (response.success) {\\r\\n            $(\\\'#successMsg\\\').text(response.message);\\r\\n            $(\\\'#contactForm\\\')[0].reset();\\r\\n          } else {\\r\\n            $(\\\'#successMsg\\\').text(\\\'\\\');\\r\\n            $.each(response.errors, function(key, value) {\\r\\n              $(\\\'#\\\' + key + \\\'Error\\\').text(value);\\r\\n            });\\r\\n          }\\r\\n        }\\r\\n      });\\r\\n    });\\r\\n  });\', `created_at` = \'2024-09-20 01:15:31\', `id` = \'18\', `isOverthinking` = \'0\', `script` = \'\', `title` = \'Ajax post\', `updated_at` = \'2025-07-13 05:58:06\'\r\n                WHERE id = 18;\r\n            \r\n','2025-07-13 19:05:39','2025-07-13 19:05:39'),(808,'\r\n                UPDATE yousabte_workspace.