\\Http\\Request  $request\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function store(GeneralRequest $request)\r\n    {\r\n        $data = $request->all();\r\n        if ($request->hasFile(\'image\')) {\r\n            $file = $request->file(\'image\');\r\n            $data[\'image\']  = upload_image($file, \'image_\');\r\n        } else {\r\n            $data[\'image\'] = \'\';\r\n        }\r\n        $data[\'type\'] = \'slider\';\r\n        $general = General::create($data);\r\n        return $general ? redirect(route(\'sliders.index\'))->with([\'success\' => trans(\'general.added_success\')]) : redirect()->back();\r\n    }\r\n \r\n    /**\r\n     * Display the specified resource.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function show($id)\r\n    {\r\n        $data = General::findorfail($id);\r\n \r\n        return view(\'admin.sliders.show\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Show the form for editing the specified resource.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function edit($id)\r\n    {\r\n        $data = General::findOrfail($id);\r\n        return view(\'admin.sliders.edit\', compact(\'data\'));\r\n    }\r\n \r\n    /**\r\n     * Update the specified resource in storage.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function update(GeneralRequest $request, $id)\r\n    {\r\n        $data =  $request->all();\r\n        $general = General::findOrfail($id);\r\n        if ($request->hasFile(\'image\')) {\r\n            $file = $request->file(\'image\');\r\n            $data[\'image\']  = upload_image($file, \'image_\');\r\n            if(file_exists($general->image))\r\n            File::delete($general->image);\r\n        } else {\r\n            $data[\'image\'] =  $general->image;\r\n        }\r\n        $general->fill($data)->save();\r\n        return $general ? redirect(route(\'sliders.index\', $id))->with([\'success\' => trans(\'general.updated_success\')]) : redirect()->back();\r\n    }\r\n \r\n    /**\r\n     * Remove the specified resource from storage.\r\n     *\r\n     * @param  int  $id\r\n     * @return \\Illuminate\\Http\\Response\r\n     */\r\n    public function destroy($id)\r\n    {\r\n        $general = General::findOrfail($id);\r\n        $general->translations()->delete();\r\n        $general->delete();\r\n        return redirect(route(\'sliders.index\'))->with([\'success\' => trans(\'general.deleted_success\')]);\r\n    }\r\n}\r\n \r\n \r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(154,'Slider.Request\r\n<?php\r\n \r\nnamespace App\\Http\\Requests;\r\n \r\nuse Illuminate\\Foundation\\Http\\FormRequest;\r\n \r\nclass GeneralRequest extends FormRequest\r\n{\r\n    public function authorize()\r\n    {\r\n        return true;\r\n    }\r\n \r\n    public function rules()\r\n    {\r\n        //to add or remove input from request in validation class use $this->merge\r\n         $this->merge([\'user_id\' => auth(\'api\')->user()->id]);\r\n\r\n        $image = request()->isMethod(\'put\') ? \'nullable\' : \'required\';\r\n        $rules = [\r\n            \'image\' =>  $image ,\r\n        ];\r\n        foreach (config(\'translatable.locales\') as $locale) {\r\n            $rules += [$locale . \'.title\' => [\'required\', \'string\']];\r\n            $rules += [$locale . \'.description\' => [\'required\']];\r\n        }\r\n        return  $rules;\r\n    }\r\n    public function messages()\r\n    {\r\n        $messages = [\r\n            \'image.required\' => trans(\'requests.image_required\'),\r\n        ];\r\n        foreach (config(\'translatable.locales\') as $locale) {\r\n            $messages += [$locale . \'.title.required\' => trans(\'requests.title_required_\' . $locale)];\r\n            $messages += [$locale . \'.description.required\' => trans(\'requests.desc_required_\' . $locale)];\r\n        }\r\n        return $messages;\r\n    }\r\n \r\n}\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(155,'Home.Apicontroller\r\n<?php\r\n \r\nnamespace App\\Http\\Controllers\\Api;\r\n \r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Resources\\GeneralResource;\r\nuse App\\Http\\Resources\\PageResource;\r\nuse App\\Http\\Resources\\PropertiesResource;\r\nuse App\\Http\\Resources\\TeamResource;\r\nuse App\\Http\\Resources\\ToothResource;\r\nuse App\\Http\\Resources\\SettingsResource;\r\nuse App\\Models\\Category;\r\nuse App\\Models\\General;\r\nuse App\\Models\\OurTeam;\r\nuse App\\Models\\Page;\r\nuse App\\Models\\Property;\r\nuse App\\Models\\PropertyTranslation;\r\nuse App\\Models\\Setting;\r\nuse GrahamCampbell\\ResultType\\Success;\r\nuse Illuminate\\Http\\Request;\r\n \r\nclass HomeController extends Controller\r\n{\r\n    public function home(Request $request)\r\n    {\r\n        $data[\'sliders\'] = GeneralResource::collection(General::where(\'type\',\'slider\')->get());\r\n        $data[\'services\'] = GeneralResource::collection(General::where(\'type\',\'service\')->get());\r\n        $data[\'appointment_page\'] = new PageResource(Page::where(\'identifier\',\'appointment\')->first());\r\n        $data[\'about_page\'] = new PageResource(Page::where(\'identifier\',\'about\')->first());\r\n        $data[\'testimonials\'] = GeneralResource::collection(General::where(\'type\',\'testimonial\')->get());\r\n        $data[\'our_team\'] = TeamResource::collection(OurTeam::get());\r\n        $data[\'tooth_page\'] = new ToothResource(Page::where(\'identifier\',\'tooth_cleaning\')->first());\r\n \r\n        return response()->json([\r\n            \'status\' => \'Success\',\r\n            \'data\'   => $data\r\n        ]);\r\n    }\r\n \r\n}\r\n \r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(156,'General.Resource\r\n<?php\r\n \r\nnamespace App\\Http\\Resources;\r\n \r\nuse Illuminate\\Http\\Resources\\Json\\JsonResource;\r\n \r\nclass GeneralResource extends JsonResource\r\n{\r\n    /**\r\n     * Transform the resource into an array.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @return array|\\Illuminate\\Contracts\\Support\\Arrayable|\\JsonSerializable\r\n     */\r\n    public function toArray($request)\r\n    {\r\n        return [\r\n            \'id\' => $this->id,\r\n            \'title\' => $this->translate($request->lang)->title,\r\n            \'description\' => $this->translate($request->lang)->description,\r\n            \'image\' =>$this->image ? asset($this->image) : asset(settings()->logo),\r\n        ];\r\n    }\r\n}\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(157,'General.Model.php\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Astrotomic\\Translatable\\Contracts\\Translatable as TranslatableContract;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\nuse Astrotomic\\Translatable\\Translatable;\r\n \r\nclass General extends Model implements TranslatableContract\r\n{\r\n    use Translatable;\r\n \r\n    public $translatedAttributes = [\r\n        \'title\',\r\n        \'description\'\r\n    ];\r\n \r\n    protected $fillable = [\'image\',\'type\'];\r\n}\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(158,'GeneralTranslation.Model.php\r\n<?php\r\n \r\nnamespace App\\Models;\r\n \r\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\n \r\nclass GeneralTranslation extends Model\r\n{\r\n    protected $fillable = [\r\n        \'title\',\r\n        \'description\',\r\n    ];\r\n}\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(159,'General.migration\r\n<?php\r\n \r\nuse Illuminate\\Database\\Migrations\\Migration;\r\nuse Illuminate\\Database\\Schema\\Blueprint;\r\nuse Illuminate\\Support\\Facades\\Schema;\r\n \r\nclass CreateGeneralsTable extends Migration\r\n{\r\n    /**\r\n     * Run the migra