\\Http\\Controllers\\Api\\AboutController@appointment\');\r\nRoute::post(\'question\', \'App\\Http\\Controllers\\Api\\AboutController@post_question\');\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(162,'Appointment and Contact Api controller\r\n<?php\r\nnamespace App\\Http\\Controllers\\Api;\r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\Site\\ContactFormRequest;\r\nuse App\\Http\\Requests\\ContactRequest;\r\nuse App\\Models\\Contact;\r\nuse App\\Models\\Page;\r\nuse App\\Models\\Setting;\r\nuse Illuminate\\Http\\Request;\r\nuse Validator;\r\nuse App\\Http\\Controllers\\Api\\BaseController as BaseController;\r\nuse App\\Models\\Appointment;\r\nuse App\\Models\\Question;\r\n \r\nclass AboutController extends BaseController\r\n{\r\n \r\n    public function contact(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'name\' => \'required\',\r\n            \'phone\' => \'required\',\r\n            \'message\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Contact::create($data);\r\n        return $this->sendResponse($success, \'تم ارسال الرسالة بنح\');\r\n    }\r\n    public function appointment(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'first_name\' => \'required\',\r\n            \'last_name\' => \'required\',\r\n            \'age\' => \'required\',\r\n            \'phone\' => \'required\',\r\n            \'service\' => \'required\',\r\n            \'date_time\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Appointment::create($data);\r\n        return $this->sendResponse($success, \'تم حجز الموعد بنجاح\');\r\n    }\r\n \r\n    public function post_question(Request $request) {\r\n        $validator = Validator::make($request->all(), [\r\n            \'name\' => \'required\',\r\n            \'phone\' => \'required|numeric\',\r\n            \'message\' => \'required\',\r\n        ]);\r\n        if ($validator->fails()) {\r\n            return $this->sendError(\'Validation Error.\', $validator->errors());\r\n        }\r\n        $data = $request->all();\r\n        $success = Question::create($data);\r\n        return $this->sendResponse($success, \'تم ارسال السؤال بنجاح\');\r\n    }\r\n \r\n    public function setting(Request $request){\r\n        $data = Setting::first();\r\n        $data[\'logo\'] = asset($data->logo);\r\n        $data[\'breadcrumb\'] = asset($data->breadcrumb);\r\n        $data[\'website_title\'] = $data->translate($request->lang)->website_title;\r\n        $data[\'meta_title\'] = $data->translate($request->lang)->meta_title;\r\n        $data[\'meta_description\'] = $data->translate($request->lang)->meta_description;\r\n        $data[\'meta_keywords\'] = $data->translate($request->lang)->meta_keywords;\r\n        $data[\'address\'] = $data->translate($request->lang)->address;\r\n        $data[\'footer_description\'] = $data->translate($request->lang)->footer_description;\r\n        return response()->json([\r\n            \'status\' => \'true\',\r\n            \'data\'   => $data\r\n        ]);\r\n    }\r\n}\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(163,'NBE payment gate way\r\npublic function store(Request $request){\r\n$data=$request->all();\r\n$last_invoice = Invoice::create($data);\r\n// $last_invoice=Invoice::where(\'name\',$data[\'name\'])->first();\r\n$username=\'merchant.TESTEGPTEST\';\r\n$password=\'c622b7e9e550292df400be7d3e846476\';\r\n \r\n$url = \'https://test-\r\nnbe.gateway.mastercard.com/api/rest/version/65/merchant/TESTEGPTEST/session\';\r\n \r\n$data = array(\"apiOperation\" => \"INITIATE_CHECKOUT\",\r\n        \"interaction\" => array (\"operation\" => \"AUTHORIZE\" ,\"returnUrl\"\r\n        =>\"http://127.0.0.1:8000/success_invoice/\".$last_invoice->id,\"cancelUrl\" =>\r\n        \"http://127.0.0.1:8000/cancel_invoice/\".$last_invoice->id),\r\n        \"order\" => array (\"currency\" => \"EGP\" ,\"id\" =>\r\n \r\n        $last_invoice->id,\"amount\" => $last_invoice->price,\"description\"=>\'description\')\r\n \r\n);\r\n \r\n$postdata = json_encode($data);\r\n$ch = curl_init($url);\r\ncurl_setopt($ch, CURLOPT_POST, 1);\r\ncurl_setopt($ch, CURLOPT_POSTFIELDS, $postdata);\r\ncurl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);\r\ncurl_setopt($ch, CURLOPT_HTTPHEADER, array(\'Content-Type:\r\napplication/json\'));\r\ncurl_setopt($ch, CURLOPT_USERPWD, \"$username:$password\");\r\n$result = curl_exec($ch);\r\ncurl_close($ch);\r\n$seeion_id = json_decode($result)->session->id ;\r\n \r\n$newUrl = \'https://test-\r\nnbe.gateway.mastercard.com/api/rest/version/65/merchant/TESTEGPTEST/session/\'.$seeion_id;\r\n$data_two = array(\"apiOperation\" => \"UPDATE_SESSION\",\r\n\"order\" => array (\"currency\" => \"EGP\" ,\"id\" =>\r\n$last_invoice->id,\"amount\" => $last_invoice->price)\r\n);\r\n \r\n$postdata_two = json_encode($data_two);\r\n$ch = curl_init($newUrl);\r\ncurl_setopt($ch, CURLOPT_POST, 1);\r\ncurl_setopt($ch, CURLOPT_POSTFIELDS, $postdata_two);\r\ncurl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);\r\ncurl_setopt($ch, CURLOPT_HTTPHEADER, array(\'Content-Type:\r\napplication/json\'));\r\ncurl_setopt($ch, CURLOPT_USERPWD, \"$username:$password\");\r\n$result = curl_exec($ch);\r\ncurl_close($ch);\r\n// $seeion_id = json_decode($result)->session->id ;\r\nreturn view(\'user.marwan_payment\',compact(\'seeion_id\'));\r\n \r\n}\r\n \r\npublic function cancel_invoice($id){\r\n    $invoice=Invoice::findOrFail($id);\r\n    $invoice->update([\"status\"=>\"canceled\"]);\r\n    return view(\'user.cancel_payment\');\r\n    }\r\n \r\n    public function success_invoice($id){\r\n    $invoice=Invoice::findOrFail($id);\r\n    $invoice->update([\"status\"=>\"success\"]);\r\n    return view(\'user.sucdcess_payment\');\r\n    }\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(164,'Invoice form\r\n<form action=\"{{getRoute(\'invoices.store\')}}\"\r\n \r\n    method=\"POST\" id=\"invoice_form\">\r\n    @csrf\r\n    <div class=\"row\">\r\n        <div class=\"col-lg-6\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الاسم <label>\r\n                <input class=\"form-control\" type=\"text\" name=\"name\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-6\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الهاتف/>* label>\r\n                <input class=\"form-control\" type=\"number\" name=\"phone\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">االلكتروني البريد/>label>\r\n                <input class=\"form-control\" type=\"text\" name=\"email\" >\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">الخدمة/>label>\r\n                <select name=\"product_id\" id=\"product_select\" class=\"form-control\">\r\n                    @foreach ($products as $product)\r\n                        <option product-price=\"{{ $product->price }}\" value=\"{{ $product->id }}\">{{ $product->name }}</option>\r\n                    @endforeach\r\n                </select>\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12\">\r\n            <div class=\"form-group\">\r\n                <label for=\"\">السعر) L.E)</label>\r\n                <input class=\"form-control\" type=\"text\" name=\"price\" id=\"price\" readonly>\r\n            </div>\r\n        </div>\r\n        <div class=\"col-lg-12 text-center\">\r\n            <button class=\"btn btn-primary \" type=\