rder-radius: 50%;\r\n    -webkit-transition: all 0.5s;\r\n    -o-transition: all 0.5s;\r\n    transition: all 0.5s;\r\n    -webkit-box-shadow: 2px 2px 5px #b0afaf, -2px -2px 5px #b0afaf;\r\n    box-shadow: 2px 2px 5px #b0afaf, -2px -2px 5px #b0afaf;\r\n}\r\n.whats:hover {\r\n    -webkit-box-shadow: 2px 2px 5px #7a7979, -2px -2px 5px #7a7979;\r\n    box-shadow: 2px 2px 5px #7a7979, -2px -2px 5px #7a7979;\r\n}\r\n.whats i {\r\n    font-size: 45px;\r\n    color: #fff;\r\n}\r\n[٦/‏٢, ١:٥٣ م] ‏+20 106 167 6252‬‏: css ar‬‬‬\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(224,'Auto scroll down in chat\r\n  <div id=\"messages\">\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n    <div class=\"message\">\r\n      Hello world\r\n    </div>\r\n  </div>\r\n\r\n<script>\r\n    const messages = document.getElementById(\'messages\');\r\n\r\n    function appendMessage() {\r\n        const message = document.getElementsByClassName(\'message\')[0];\r\n        const newMessage = message.cloneNode(true);\r\n        messages.appendChild(newMessage);\r\n    }\r\n\r\n    function getMessages() {\r\n        // Prior to getting your messages.\r\n        shouldScroll = messages.scrollTop + messages.clientHeight === messages.scrollHeight;\r\n        /*\r\n         * Get your messages, we\'ll just simulate it by appending a new one syncronously.\r\n         */\r\n        appendMessage();\r\n        // After getting your messages.\r\n        if (!shouldScroll) {\r\n            scrollToBottom();\r\n        }\r\n    }\r\n\r\n    function scrollToBottom() {\r\n        messages.scrollTop = messages.scrollHeight;\r\n    }\r\n\r\n    scrollToBottom();\r\n\r\n    setInterval(getMessages, 100);\r\n</script>\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(225,'request->add()\r\n        if (!$request->has(\'status\'))\r\n            $request->request->add([\'status\' => 0]);\r\n        else\r\n            $request->request->add([\'status\' => 1]);\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(226,'A very creative way to deal with pages in a laravel project\r\nif (!function_exists(\'pages\'))\r\n{\r\n    function pages($page)\r\n    {\r\n        // dd(Page::where(\'identifier\',\'aboutus\')->first());\r\n\r\n        return Page::where(\'identifier\',$page)->first();\r\n    }\r\n}\r\n//blade\r\n{{ pages(\'aboutus\')->title }}\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(227,'Use use inside a function($q)\r\n            $course=$this->course->where(\'id\', $request->id)->first();\r\n            $data[\'course\'] = new CourseResource($this->course->where(\'id\', $request->id)->first());\r\n            $courses = $this->course->where(\'section_id\', \'!=\', null)->where(\'city_id\', \'!=\', null)->where(\'id\',   \'!=\', $course->id)->whereHas(\'translations\', function ($q2) use($course) {\r\n                $q2->where(\'title\', \'like\', \'%\' . $course->title . \'%\');\r\n            })->where(\'start_date\', \'>=\', $dt->format(\'Y-m-d\'))->search()->latest(\'id\')->get();\r\n            $data[\'related_courses\'] = CourseResource::collection($courses)->response()->getData(true);\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(228,'How we get index in foreach\r\n          foreach($phone as $key=>$value){\r\n            $phones[$key][\'label\']=$labels[$key];\r\n            $phones[$key][\'value\']=$value;\r\n          }\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(229,'3 days ago example\r\n<?php\r\nnamespace App\\Models;\r\nuse App\\Traits\\Files\\HasFile;\r\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\r\nuse Illuminate\\Database\\Eloquent\\Model;\r\nclass Job extends Model\r\n{\r\npublic function getTimeAgo($carbonObject) {\r\n    return str_ireplace(\r\n        [\' seconds\', \' second\', \' minutes\', \' minute\', \' hours\', \' hour\', \' days\', \' day\', \' weeks\', \' week\'],\r\n        [\' seconds\', \' second\', \' minutes\', \' minute\', \' hours\', \' hour\', \' days\', \' day\', \' weeks\', \' week\'],\r\n        $carbonObject->diffForHumans()\r\n    );\r\n}\r\n}\r\n\r\n<?php\r\nnamespace App\\Http\\Resources;\r\nuse Illuminate\\Http\\Resources\\Json\\JsonResource;\r\nclass JobResource extends JsonResource\r\n{\r\n    /**\r\n     * Transform the resource into an array.\r\n     *\r\n     * @param  \\Illuminate\\Http\\Request  $request\r\n     * @return array|\\Illuminate\\Contracts\\Support\\Arrayable|\\JsonSerializable\r\n     */\r\n    public function toArray($request)\r\n    {\r\n        return [\r\n            \'created_at\'=>$this->getTimeAgo($this->created_at),\r\n        ];\r\n    }   \r\n}\r\n\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(230,'Image picker\r\n                    @include(\'admin.components.image\', [\r\n                        \'label\' => __(\'words.image\'),\r\n                        \'value\' => old(\'image\'),\r\n                        \'name\' => \'image\',\r\n                        \'id\' => \'kt_image_3\',\r\n                        \'accept\' => \'image/*\',\r\n                        \'required\' => true,\r\n                    ])\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(231,'Multi Select in laravel\r\n//create\r\n<div class=\"form-group row\">\r\n    <label class=\"col-form-label text-right col-lg-3 col-sm-12\">{{__(\"words.specifications\")}}</label>\r\n    <div class=\"col-lg-4 col-md-9 col-sm-12\">\r\n        <select class=\"form-control selectpicker\" id=\"multiSelect1\" multiple=\"multiple\"\r\n                data-live-search=\"true\" name=\"specifications[]\">\r\n            @foreach($specifications as $specification)\r\n                <option value=\"{{$specification->id}}\" {{(collect(old(\'specifications\'))->contains($specification->id)) ? \'selected\':\'\' }}>{!! $specification->description !!}</option>\r\n            @endforeach\r\n        </select>\r\n    </div>\r\n</div>\r\n\r\n//edit\r\n<div class=\"form-group row\">\r\n    <label class=\"col-form-label text-right col-lg-3 col-sm-12\">{{__(\"words.specifications\")}}</label>\r\n    <div class=\"col-lg-4 col-md-9 col-sm-12\">\r\n        <select class=\"form-control selectpicker\" id=\"multiSelect1\" multiple=\"multiple\"\r\n                data-live-search=\"true\" name=\"specifications[]\">\r\n            @foreach($all_specifications as $specification)\r\n                <option value=\"{{$specification->id}}\" {{(collect(old(\'specifications\',$specifications))->contains($specification->id)) ? \'selected\':\'\' }}>{!! $specification->description !!}</option>\r\n            @endforeach\r\n        </select>\r\n    </div>\r\n</div>\r\n\r\n\r\n//store\r\nif ($request->has(\'specifications\')) {\r\n// return \'yes\';\r\n$specifications = array_map(function ($value) {\r\nreturn intval(($value));\r\n}, $request->specifications);\r\n$project->specifications()->attach($specifications);\r\n}\r\n\r\n//edit\r\npublic function edit(Project $project)\r\n{\r\n$all_specifications = $this->specification->get();\r\n$specifications = $project->specifications->pluck(\'id\');\r\nreturn view(\'admin.projects.edit\', compact(\'project\', \'specifications\', \'all_specifications\'));\r\n}\r\n\r\n    public function services()\r\n    {\r\n        return $this->belongsToMany(Service::class , \'color_product\');\r\n    }\r\n\r\n\r\n<?php\r\n\r\nnamespace App\\Http\\Controllers\\Dashboard;\r\n\r\nuse App\\Http\\Controllers\\Controller;\r\nuse App\\Http\\Requests\\Dashboard\\PackageRequest;\r\nuse App\\Models\\Package;\r\nuse App\\Models\\Service;\r\nuse Illuminate\\Http\\Request;\r\nuse Illuminate\\Support\\Carbon;\r\n\r\nclass PackageController extends Controller\r\n{\r\n    private $package;\r\n    private $service;\r\n\r\n    public function __construct(Package $package, Service $service)\r\n    {\r\n        $this->middleware([\'permission:read-package\'])->only(\'index\', \'show\');\r\n        $this->middleware([\'permission:create-package\'])->only(\'create\', \'store\');\r\n        $this->middleware([\'permission:update-package\'])->only(\'edit\', \'update\');\r\n        $this->middleware([\'permission:delete-package\'])->only(\'destroy\');\r\n        $this->package = $package;\r\n        $this->service = $service;\r\n    }\r\n\r\n    public function index()\r\n    {\r\n        try {\r\n            $packages = $this->package->latest(\'id\')->get();\r\n            return view(\'admin.package.index\', compact(\'packages\'));\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(\'message.something_wrong\')]);\r\n        }\r\n    }\r\n\r\n    public function create()\r\n    {\r\n        $services = $this->service->latest(\'id\')->get();\r\n        return view(\'admin.package.create\', compact(\'services\'));\r\n    }\r\n   \r\n    public function store(PackageRequest $request)\r\n    {\r\n        try {\r\n            if (!$request->has(\'status\'))\r\n            $request->request->add([\'status\' => 0]);\r\n            else\r\n            $request->request->add([\'status\' => 1]);\r\n           \r\n            $requested_data = $request->except([\'_token\', \'profile_avatar_remove\', \'services\',\'image\']);\r\n            $package = $this->package->create($requested_data);\r\n            $package->uploadFile();\r\n            if ($request->has(\'services\')) {\r\n                // return \'yes\';\r\n                $services = array_map(function ($value) {\r\n                    return intval(($value));\r\n                }, $request->services);\r\n                $package->services()->attach($services);\r\n            }\r\n\r\n\r\n            return redirect()->route(\'package.index\')->with([\'success\' => __(\'message.created_successfully\')]);\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __($e->getMessage())]);\r\n        }\r\n    }\r\n   \r\n    public function show(Package $package)\r\n    {\r\n        return view(\'admin.package.show\', compact(\'package\'));\r\n    }\r\n   \r\n    public function edit(Package $package)\r\n    {\r\n        $services = $this->service->latest(\'id\')->get();\r\n        $ids=[];\r\n        foreach ($package->services as $service)\r\n        array_push($ids, $service->id);\r\n        return view(\'admin.package.edit\', compact(\'package\',\'services\',\'ids\'));\r\n    }\r\n\r\n    public function update(PackageRequest $request, Package $package)\r\n    {\r\n        try {\r\n            if (!$request->has(\'status\'))\r\n                $request->request->add([\'status\' => 0]);\r\n            else\r\n                $request->request->add([\'status\' => 1]);\r\n\r\n            $requested_data = $request->except([\'_token\', \'profile_avatar_remove\', \'image\',\'services\']);\r\n            $requested_data[\'updated_at\'] = Carbon::now();\r\n            $package->update($requested_data);\r\n\r\n            $package->updateFile();\r\n\r\n            $package->services()->detach();\r\n            if ($request->has(\'services\')) {\r\n                // return \'yes\';\r\n                $services = array_map(function ($value) {\r\n                    return intval(($value));\r\n                }, $request->services);\r\n                $package->services()->attach($services);\r\n            }\r\n\r\n            return redirect()->route(\'package.index\')->with([\'success\' => __(\'message.updated_successfully\')]);\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __($e->getMessage())]);\r\n        }\r\n    }\r\n\r\n    public function destroy(Package $package)\r\n    {\r\n        try {\r\n            $package->deleteFile();\r\n            $package->delete();\r\n            return redirect()->route(\'package.index\')->with([\'success\' => __(\'message.deleted_successfully\')]);\r\n        } catch (\\Exception $e) {\r\n            return redirect()->back()->with([\'error\' => __(\'message.deleted_successfully\')]);\r\n        }\r\n    }\r\n}\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(232,'How to get selected option value and text\r\nvar conceptName = $(\'#aioConceptName\').find(\":selected\").text();\r\nvar conceptName = $(\'#aioConceptName\').find(\":selected\").val();\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n','2024-02-09 02:00:21','2024-02-09 02:00:21'),(233,'How to keep all form inputs values even if after reload or after shutdown the device\r\n@push(\'scripts\')\r\n    <script>\r\n        $(document).ready(function() {\r\n        //    save data once entered\r\n            $(\"input\").each(function() {\r\n                $(this).bind(\"input\", function(event) {\r\n                    localStorage.setItem($(this).attr(\'name\')+\'student\', $(this).val());\r\n                });\r\n                if (localStorage.getItem($(this).attr(\'name\')+\'student\') !== null)\r\n                            $(this).val(localStorage.getItem($(this).attr(\'name\')+\'student\'));\r\n            });\r\n        });\r\n    </script>\r\n@endpush','2024-02-09 02:00:21','2024-02-09 02:00:21'),(234,'Angular\r\n\r\n	\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(235,'Angular 14 CRUD Project\r\n\r\nNotes\r\nLearn angular from github app\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:1