*****************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(238,'app.component.html\r\n<nav class=\"navbar navbar-expand-lg navbar-dark bg-warning\">\r\n  <div class=\"container-fluid\">\r\n    <div class=\"container\">\r\n      <div class=\"row\">\r\n        <div class=\"col-1\">\r\n          <span class=\"form-inline\">\r\n            <select class=\"form-control\" #selectedLang (change)=\"switchLang(selectedLang.value)\">\r\n              <option *ngFor=\"let language of translate.getLangs()\" [value]=\"language\"\r\n                [selected]=\"language === translate.currentLang\">\r\n                {{ language }}\r\n              </option>\r\n            </select>\r\n          </span>\r\n        </div>\r\n        <div class=\"col text-center\">\r\n          <a class=\"navbar-brand text-dark fw-bold\">{{ \'dashboard\' | translate }}</a>\r\n        </div>\r\n        <div class=\"col-3  align-items-center d-flex justify-content-end\">\r\n          <a class=\"navbar-brand text-dark\" routerLink=\"/fruits/home\" routerLinkActive=\"active\"\r\n            [routerLinkActiveOptions]=\"{exact:true}\">{{ \'fruits\' | translate }}</a>\r\n          <a class=\"navbar-brand text-dark\" routerLink=\"/posts/home\" routerLinkActive=\"active\"\r\n            [routerLinkActiveOptions]=\"{exact:true}\">{{ \'posts\' | translate }}</a>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n</nav>\r\n<router-outlet></router-outlet>\r\n\r\n****************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(239,'app.component.ts\r\nimport { Component } from \'@angular/core\';\r\nimport { TranslateService } from \'@ngx-translate/core\';\r\nimport { FruitsService } from \'./fruits/fruits.service\';\r\n\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  styleUrls: [\'./app.component.css\']\r\n})\r\nexport class AppComponent {\r\n  title = \'Angular_CRUD\';\r\n\r\n\r\n\r\n  constructor(public translate: TranslateService, private fruitService: FruitsService) {\r\n    // this language will be used as a fallback when a translation isn\'t found in the current language\r\n    translate.addLangs([\'en\', \'ar\']);\r\n    translate.setDefaultLang(\'en\');\r\n    document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", this.translate.getDefaultLang());\r\n\r\n    // the lang to use, if the lang isn\'t available, it will use the current loader to get them\r\n    // translate.use(\'en\');\r\n  }\r\n  public static appLang: string = \'en\';\r\n\r\n  switchLang(lang: string) {\r\n\r\n    AppComponent.appLang = lang;\r\n    this.translate.use(lang);\r\n\r\n    this.fruitService.get(lang).subscribe((data) => {\r\n      this.fruitService.allFruits = data.data.fruits;\r\n    });\r\n\r\n    if (lang === \'ar\') {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"rtl\");\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", \"ar\");\r\n    }\r\n    else {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"ltr\");\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", \"en\");\r\n    }\r\n  }\r\n\r\n\r\n}\r\n\r\n********************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(240,'app-routing.module.ts\r\n\r\nimport { NgModule } from \'@angular/core\';\r\nimport { RouterModule, Routes } from \'@angular/router\';\r\n\r\n\r\nconst routes: Routes = [\r\n    {\r\n      path: \'\',\r\n      redirectTo: \'posts/home\',\r\n      pathMatch: \'full\',\r\n    }    \r\n  ];\r\n\r\n  @NgModule({\r\n    imports: [RouterModule.forRoot(routes)],\r\n    exports: [RouterModule]\r\n  })\r\n\r\n  export class AppRoutingModule {\r\n}\r\n********************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(241,'fruits.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { CommonModule } from \'@angular/common\';\r\n\r\nimport { FruitsRoutingModule } from \'./fruits-routing.module\';\r\nimport { HomeComponent } from \'./home/home.component\';\r\nimport { CreateComponent } from \'./create/create.component\';\r\nimport { FormsModule, ReactiveFormsModule } from \'@angular/forms\';\r\nimport { EditComponent } from \'./edit/edit.component\';\r\nimport {TranslateModule} from \'@ngx-translate/core\';\r\n\r\n\r\n@NgModule({\r\n  declarations: [\r\n    HomeComponent,\r\n    CreateComponent,\r\n    EditComponent\r\n  ],\r\n  imports: [\r\n    CommonModule,\r\n    FruitsRoutingModule,\r\n    FormsModule,\r\n    ReactiveFormsModule,\r\n    TranslateModule,\r\n  ]\r\n})\r\nexport class FruitsModule { }\r\n*************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(242,'fruits.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { HttpClient } from \'@angular/common/http\';\r\nimport { Fruits } from \'./fruits\';\r\nimport { Observable } from \'rxjs\';\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class FruitsService {\r\n  constructor(private http: HttpClient) {}\r\n\r\n  allFruits: Fruits[] = [];\r\n\r\n  get(lang:string):Observable<any>  {\r\n    return this.http.get<any>(\'http://127.0.0.1:8000/api/fruits?lang=\'+lang);\r\n  }\r\n\r\n  create(payload: any) {\r\n    return this.http.post<any>(\'http://localhost:3000/fruits\', payload);\r\n  }\r\n\r\n  getById(id: number , lang:string) {\r\n    // return this.http.get<any>(`http://localhost:3000/fruits/${id}`);\r\n    console.log(id);\r\n   \r\n    return this.http.get<any>(`http://127.0.0.1:8000/api/fruit/${id}?lang=${lang}`);\r\n   }\r\n   \r\n   update(payload:any){\r\n    return this.http.put(`http://localhost:3000/fruits/${payload.id}`,payload);\r\n   }\r\n\r\n   delete(id:number){\r\n    return this.http.delete<any>(`http://localhost:3000/fruits/${id}`);\r\n }\r\n\r\n}\r\n\r\n****************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(243,'fruits.ts\r\nexport interface Fruits {\r\n    id: number;\r\n    name: string;\r\n    quantity: number;\r\n    price: number;\r\n  }\r\n*******************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(244,'fruits-routing.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { RouterModule, Routes } from \'@angular/router\';\r\nimport { HomeComponent } from \'./home/home.component\';\r\nimport { CreateComponent } from \'./create/create.component\';\r\nimport { EditComponent } from \'./edit/edit.component\';\r\n\r\n\r\n\r\nconst routes: Routes = [  {\r\n  path: \'fruits/home\',\r\n  component: HomeComponent,\r\n},\r\n{\r\n  path: \'fruits/create\',\r\n  component: CreateComponent,\r\n},\r\n{\r\n  path:\'fruits/edit/:id\',\r\n  component: EditComponent\r\n}\r\n];\r\n\r\n@NgModule({\r\n  imports: [RouterModule.forRoot(routes)],\r\n  exports: [RouterModule]\r\n})\r\nexport class FruitsRoutingModule { }\r\n**************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(245,'home.component.html\r\n<!-- Modal -->\r\n<div class=\"modal fade\" id=\"deleteModal\" tabindex=\"-1\" aria-labelledby=\"exampleModalLabel\" aria-hidden=\"true\">\r\n  <div class=\"modal-dialog\">\r\n    <div class=\"modal-content\">\r\n      <div class=\"modal-header\">\r\n        <h5 class=\"modal-title\" id=\"exampleModalLabel\">{{ \'warning\' | translate }}</h5>\r\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"></button>\r\n      </div>\r\n      <div class=\"modal-body\">\r\n        {{ \'sure\' | translate }}\r\n      </div>\r\n      <div class=\"modal-footer\">\r\n        <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">{{ \'close\' | translate }}</button>\r\n        <button type=\"button\" class=\"btn btn-danger\" (click)=\"delete()\">{{ \'confirm_delete\' | translate }}</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div class=\"container\">\r\n  <div class=\"container\">\r\n    <div class=\"row mt-2\">\r\n      <div class=\"col col-md-12 offset-md-12\">\r\n        <a class=\"btn btn-success\" routerLink=\"/fruits/create\">{{ \'create\' | translate }}</a>\r\n      </div>\r\n    </div>\r\n  </div>\r\n  <table class=\"table\">\r\n    <thead>\r\n      <tr>\r\n        <th scope=\"col\">#</th>\r\n        <th scope=\"col\">{{ \'name\' | translate }}</th>\r\n        <th scope=\"col\">{{ \'quantity\' | translate }}</th>\r\n        <th scope=\"col\">{{ \'price\' | translate }}</th>\r\n        <th scope=\"col\"></th>\r\n        <th scope=\"col\"></th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n     <ng-container *ngFor=\"let item of _fruitService.allFruits; let indexOfelement=index;\">\r\n      <tr>\r\n        <th scope=\"row\">{{ indexOfelement+1 }}</th>\r\n        <td>{{ item.name }}</td>\r\n        <td>{{ item.quantity }}</td>\r\n        <td>{{ item.price }}</td>\r\n        <td>\r\n          <a class=\"btn btn-primary\" [routerLink]=\"[\'/fruits/edit\', item.id]\">{{ \'edit\' | translate }}</a>\r\n        </td>\r\n        <td>\r\n          <button type=\"button\" (click)=\"openDeleteModal(item.id)\" class=\"btn btn-danger\">{{ \'delete\' |          translate }}</button>\r\n        </td>\r\n      </tr>\r\n    </ng-container>\r\n    </tbody>\r\n  </table>\r\n</div>\r\n***************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(246,'home.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { AppComponent } from \'src/app/app.component\';\r\nimport { Fruits } from \'../fruits\';\r\nimport { FruitsService } from \'../fruits.service\';\r\n \r\ndeclare var window: any;\r\n \r\n@Component({\r\n  selector: \'app-home\',\r\n  templateUrl: \'./home.component.html\',\r\n  styleUrls: [\'./home.component.css\'],\r\n})\r\nexport class HomeComponent implements OnInit {\r\n  deleteModal: any;\r\n  idTodelete: number = 0;\r\n\r\n \r\n  constructor(public _fruitService: FruitsService) {\r\n    this.get(AppComponent.appLang);\r\n  }\r\n \r\n  ngOnInit(): void {\r\n    this.deleteModal = new window.bootstrap.Modal(\r\n      document.getElementById(\'deleteModal\')\r\n    );\r\n \r\n   \r\n   \r\n  }\r\n \r\n  get(lang: string) {\r\n      this._fruitService.get(lang).subscribe((data) => {\r\n      this._fruitService.allFruits = data.data.fruits;\r\n    });\r\n  }\r\n \r\n  openDeleteModal(id: number) {\r\n    this.idTodelete = id;\r\n    this.deleteModal.show();\r\n  }\r\n \r\n  delete() {\r\n    this._fruitService.delete(this.idTodelete).subscribe({\r\n      next: (data) => {\r\n        this._fruitService.allFruits = this._fruitService.allFruits .filter(_ => _.id != this.idTodelete)\r\n        this.deleteModal.hide();\r\n      },\r\n    });\r\n  }\r\n}\r\n**************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(247,'edit.component.html\r\n<div class=\"container\">\r\n  <legend>{{ \'edit_item\' | translate }}</legend>\r\n  <form [formGroup]=\"fruitForm\" (ngSubmit)=\"update()\">\r\n     \r\n    <div class=\"form-group\">\r\n        <label for=\"name\">{{ \'name\' | translate }}</label>\r\n        <input\r\n            formControlName=\"name\"\r\n            [(ngModel)] = \"form.name\"\r\n            id=\"name\"\r\n            type=\"text\"\r\n            class=\"form-control\">\r\n        <div *ngIf=\"f[\'name\'].touched && f[\'name\'].invalid\" class=\"alert alert-danger\">\r\n            <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'required\']\">{{ \'name_required\' | translate }}</div>\r\n            <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'minlength\']\">{{ \'name_character\' | translate }}</div>\r\n        </div>\r\n    </div>\r\n     \r\n    <div class=\"form-group\">\r\n        <label for=\"price\">{{ \'price\' | translate }}</label>\r\n        <input\r\n            formControlName=\"price\"\r\n            [(ngModel)] = \"form.price\"\r\n            id=\"price\"\r\n            type=\"text\"\r\n            class=\"form-control\">\r\n        <div *ngIf=\"f[\'price\'].touched && f[\'price\'].invalid\" class=\"alert alert-danger\">\r\n            <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'required\']\">{{ \'price_required\' | translate }}</div>\r\n            <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'pattern\']\">{{ \'price_number\' | translate }}</div>\r\n        </div>\r\n    </div>\r\n     \r\n    <div class=\"form-group\">\r\n        <label for=\"quantity\">{{ \'quantity\' | translate }}</label>\r\n        <input\r\n            formControlName=\"quantity\"\r\n            [(ngModel)] = \"form.quantity\"\r\n            id=\"quantity\"\r\n            type=\"number\"\r\n            class=\"form-control\">\r\n        <div *ngIf=\"f[\'quantity\'].touched && f[\'quantity\'].invalid\" class=\"alert alert-danger\">\r\n            <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'required\']\">{{ \'quantity_required\' | translate }}</div>\r\n            <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'pattern\']\">{{ \'quantity_number\' | translate }}</div>\r\n        </div>\r\n    </div>\r\n   \r\n    <div class=\"pt-2\">\r\n      <button class=\"btn btn-primary\" [disabled]=\"fruitForm.invalid\" type=\"submit\">{{ \'edit\' | translate }}</button>\r\n    </div>\r\n</form>\r\n</div>\r\n****************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(248,'edit.component.ts\r\nimport { Component, OnInit, Input, Output } from \'@angular/core\';\r\nimport { ActivatedRoute, Router } from \'@angular/router\';\r\nimport { Fruits } from \'../fruits\';\r\nimport { FruitsService } from \'../fruits.service\';\r\nimport { FormGroup, FormControl, Validators} from \'@angular/forms\';\r\nimport { AppComponent } from \'src/app/app.component\';\r\n@Component({\r\n  selector: \'app-edit\',\r\n  templateUrl: \'./edit.component.html\',\r\n  styleUrls: [\'./edit.component.css\'],\r\n})\r\nexport class EditComponent implements OnInit {\r\n  form: Fruits = {\r\n    id: 0,\r\n    name: \'\',\r\n    price: 0,\r\n    quantity: 0,\r\n  };\r\n\r\n  fruitForm= new FormGroup({\r\n    name: new FormControl(\'\', [Validators.required, Validators.minLength(3)]),\r\n    price: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n    quantity: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n  });\r\n\r\n  // @Output() x = 50;\r\n  constructor(\r\n    private route: ActivatedRoute,\r\n    private router: Router,\r\n    private fruitService: FruitsService\r\n  ) {\r\n  }\r\n\r\n  ngOnInit(): void {\r\n    this.route.paramMap.subscribe((param) => {\r\n      var id = Number(param.get(\'id\'));      \r\n      this.getById(id);\r\n\r\n    });\r\n  }\r\n\r\n  getById(id: number) {\r\n    this.fruitService.getById(id , AppComponent.appLang).subscribe((data) => {\r\n      this.form = data.data.fruit;\r\n    });\r\n  }\r\n\r\n  update() {\r\n    this.fruitService.update(this.form)\r\n      .subscribe({\r\n        next: (data) => {\r\n          this.router.navigate([\"/fruits/home\"]);\r\n        },\r\n        error: (err) => {\r\n          console.log(err);\r\n        }\r\n      })\r\n  }\r\n\r\n  get f(){\r\n    return this.fruitForm.controls;\r\n  }\r\n \r\n\r\n\r\n}\r\n**************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(249,'create.component.html\r\n<div class=\"container\">\r\n    <legend>{{ \'create_item\' | translate }}</legend>\r\n    <form [formGroup]=\"fruitForm\" (ngSubmit)=\"create()\">\r\n       \r\n      <div class=\"form-group\">\r\n          <label for=\"name\">{{ \'name\' | translate }}</label>\r\n          <input\r\n              formControlName=\"name\"\r\n              [(ngModel)] = \"form.name\"\r\n              id=\"name\"\r\n              type=\"text\"\r\n              class=\"form-control\">\r\n          <div *ngIf=\"f[\'name\'].touched && f[\'name\'].invalid\" class=\"alert alert-danger\">\r\n              <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'required\']\">{{ \'name_required\' | translate }}</div>\r\n              <div *ngIf=\"f[\'name\'].errors && f[\'name\'].errors[\'minlength\']\">{{ \'name_character\' | translate }}</div>\r\n          </div>\r\n      </div>\r\n       \r\n      <div class=\"form-group\">\r\n          <label for=\"price\">{{ \'price\' | translate }}</label>\r\n          <input\r\n              formControlName=\"price\"\r\n              [(ngModel)] = \"form.price\"\r\n              id=\"price\"\r\n              type=\"text\"\r\n              class=\"form-control\">\r\n          <div *ngIf=\"f[\'price\'].touched && f[\'price\'].invalid\" class=\"alert alert-danger\">\r\n              <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'required\']\">{{ \'price_required\' | translate }}</div>\r\n              <div *ngIf=\"f[\'price\'].errors && f[\'price\'].errors[\'pattern\']\">{{ \'price_number\' | translate }}</div>\r\n          </div>\r\n      </div>\r\n       \r\n      <div class=\"form-group\">\r\n          <label for=\"quantity\">{{ \'quantity\' | translate }}</label>\r\n          <input\r\n              formControlName=\"quantity\"\r\n              [(ngModel)] = \"form.quantity\"\r\n              id=\"quantity\"\r\n              type=\"number\"\r\n              class=\"form-control\">\r\n          <div *ngIf=\"f[\'quantity\'].touched && f[\'quantity\'].invalid\" class=\"alert alert-danger\">\r\n              <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'required\']\">{{ \'quantity_required\' | translate }}</div>\r\n              <div *ngIf=\"f[\'quantity\'].errors && f[\'quantity\'].errors[\'pattern\']\">{{ \'quantity_number\' | translate }}</div>\r\n          </div>\r\n      </div>\r\n     \r\n      <div class=\"pt-2\">\r\n        <button class=\"btn btn-primary\" [disabled]=\"fruitForm.invalid\" type=\"submit\">{{ \'submit\' | translate }}</button>\r\n      </div>\r\n  </form>\r\n  </div>\r\n\r\n******************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(250,'create.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { Fruits } from \'../fruits\';\r\nimport { FruitsService } from \'../fruits.service\';\r\nimport { FormGroup, FormControl, Validators} from \'@angular/forms\';\r\n\r\n@Component({\r\n  selector: \'app-create\',\r\n  templateUrl: \'./create.component.html\',\r\n  styleUrls: [\'./create.component.css\'],\r\n})\r\nexport class CreateComponent implements OnInit {\r\n  form: Fruits = {\r\n    id: 0,\r\n    name: \'\',\r\n    price: 0,\r\n    quantity: 0,\r\n  };\r\n\r\n  fruitForm= new FormGroup({\r\n    name: new FormControl(\'\', [Validators.required, Validators.minLength(3)]),\r\n    price: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n    quantity: new FormControl(\'\', [Validators.required,Validators.pattern(\'[0-9]*\')]),\r\n  });\r\n\r\n//  form: any;\r\n\r\n  constructor(private fruitService: FruitsService,\r\n    private router: Router) { }\r\n\r\n  ngOnInit(): void { }\r\n\r\n  create() {\r\n    this.fruitService.create(this.form)\r\n    .subscribe({\r\n      next: (data) => {\r\n        this.router.navigate([\"/fruits/home\"])\r\n      },\r\n      error: (err) => {\r\n        console.log(err);\r\n      }\r\n    })\r\n  }\r\n\r\n  get f(){\r\n    return this.fruitForm.controls;\r\n  }\r\n \r\n}\r\n************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(251,'Angular Basics\r\n\r\n<p>{{ \'Server\' }} with ID {{ serverId }} is {{ getServerStatus() }}</p>\r\n***********************************************************************\r\nimport { Component } from \'@angular/core\';\r\n\r\n@Component({\r\n  selector: \'app-server\',\r\n  templateUrl: \'./server.component.html\'\r\n})\r\nexport class ServerComponent {\r\n  serverId: number = 10;\r\n  serverStatus: string = \'offline\';\r\n\r\n  getServerStatus() {\r\n    return this.serverStatus;\r\n  }\r\n}\r\n**********************************************************************\r\n<div class=\"container\">\r\n  <div class=\"row\">\r\n    <div class=\"col-xs-12\">\r\n      <h3>I\'m in the AppComponent!</h3>\r\n      <hr>\r\n      <app-servers></app-servers>\r\n      <!--<div app-servers></div>-->\r\n      <!--<div class=\"app-servers\"></div>-->\r\n    </div>\r\n  </div>\r\n</div>\r\n*********************************************************************\r\nimport { Component } from \'@angular/core\';\r\n\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  // styleUrls: [\'./app.component.css\']\r\n  styles: [`\r\n    h3 {\r\n      color: dodgerblue;\r\n    }\r\n  `]\r\n})\r\nexport class AppComponent {\r\n}\r\n\r\n*******************************************************************\r\n\r\n<p\r\n  [ngStyle]=\"{backgroundColor: getColor()}\"\r\n  [ngClass]=\"{online: serverStatus === \'online\'}\">\r\n  {{ \'Server\' }} with ID {{ serverId }} is {{ getServerStatus() }}\r\n</p>\r\n******************************************************************\r\nimport { Component } from \'@angular/core\';\r\n\r\n@Component({\r\n  selector: \'app-server\',\r\n  templateUrl: \'./server.component.html\',\r\n  styles: [`\r\n    .online {\r\n      color: white;\r\n    }\r\n  `]\r\n})\r\nexport class ServerComponent {\r\n  serverId: number = 10;\r\n  serverStatus: string = \'offline\';\r\n\r\n  constructor() {\r\n    this.serverStatus = Math.random() > 0.5 ? \'online\' : \'offline\';\r\n  }\r\n\r\n  getServerStatus() {\r\n    return this.serverStatus;\r\n  }\r\n\r\n  getColor() {\r\n    return this.serverStatus === \'online\' ? \'green\' : \'red\';\r\n  }\r\n}\r\n*********************************************************************\r\n<label>Server Name</label>\r\n<input\r\n  type=\"text\"\r\n  class=\"form-control\"\r\n  (input)=\"onUpdateServerName($event)\">\r\n\r\n  <p>{{ serverName }}</p>\r\n  <p [innerText]=\"allowNewServer\"></p>\r\n  <p>{{ serverCreationStatus }}</p>\r\n\r\n\r\n<br>\r\n\r\n<input\r\n  type=\"text\"\r\n  class=\"form-control\"\r\n  [(ngModel)]=\"serverName\">\r\n\r\n<button\r\n  class=\"btn btn-primary\"\r\n  [disabled]=\"!allowNewServer\"\r\n  (click)=\"onCreateServer()\">Add Server</button>\r\n\r\n<p *ngIf=\"serverCreated\">Server was created, server name is {{ serverName }}</p>\r\n<app-server *ngFor=\"let server of servers\"></app-server>\r\n*****************************************************************************\r\nimport { Component, OnInit } from \'@angular/core\';\r\n\r\n@Component({\r\n  // selector: \'[app-servers]\',\r\n  // selector: \'.app-servers\',\r\n  selector: \'app-servers\',\r\n  // template: `\r\n  //   <app-server></app-server>\r\n  //   <app-server></app-server>`,\r\n  templateUrl: \'./servers.component.html\',\r\n  styleUrls: [\'./servers.component.css\']\r\n})\r\nexport class ServersComponent implements OnInit {\r\n  allowNewServer = false;\r\n  serverCreationStatus = \'No server was created!\';\r\n  serverName = \'Testserver\';\r\n  serverCreated = false;\r\n  servers = [\'Testserver\', \'Testserver 2\'];\r\n\r\n  constructor() {\r\n    setTimeout(() => {\r\n      this.allowNewServer = true;\r\n    }, 2000);\r\n  }\r\n\r\n  ngOnInit() {\r\n  }\r\n\r\n  onCreateServer() {\r\n    this.serverCreated = true;\r\n    this.servers.push(this.serverName);\r\n    this.serverCreationStatus = \'Server was created! Name is \' + this.serverName;\r\n  }\r\n\r\n  onUpdateServerName(event: Event) {\r\n    this.serverName = (<HTMLInputElement>event.target).value;\r\n  }\r\n}\r\n\r\n*************************************************************************\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(252,'Angular Login and Register\r\n\r\nauth-state.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { BehaviorSubject } from \'rxjs/internal/BehaviorSubject\';\r\nimport { TokenService } from \'../shared/token.service\';\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class AuthStateService {\r\n  private userState = new BehaviorSubject<boolean>(this.token.isLoggedIn()!);\r\n  userAuthState = this.userState.asObservable();\r\n  constructor(public token: TokenService) {}\r\n  setAuthState(value: boolean) {\r\n    this.userState.next(value);\r\n  }\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(253,'auth.interceptor.ts\r\nimport { Injectable } from \"@angular/core\";\r\nimport { HttpInterceptor, HttpRequest, HttpHandler } from \"@angular/common/http\";\r\nimport { TokenService } from \"../shared/token.service\";\r\n@Injectable()\r\nexport class AuthInterceptor implements HttpInterceptor {\r\n    constructor(private tokenService: TokenService) { }\r\n    intercept(req: HttpRequest<any>, next: HttpHandler) {\r\n        const accessToken = this.tokenService.getToken();\r\n        req = req.clone({\r\n            setHeaders: {\r\n                Authorization: \"Bearer \" + accessToken\r\n            }\r\n        });\r\n        return next.handle(req);\r\n    }\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(254,'auth.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { Observable } from \'rxjs\';\r\nimport { HttpClient } from \'@angular/common/http\';\r\n// User interface\r\nexport class User {\r\n  name!: String;\r\n  email!: String;\r\n  password!: String;\r\n  password_confirmation!: String;\r\n}\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class AuthService {\r\n  constructor(private http: HttpClient) {}\r\n  // User registration\r\n  register(user: User): Observable<any> {\r\n    return this.http.post(\'http://127.0.0.1:8000/api/auth/register\', user);\r\n  }\r\n  // Login\r\n  signin(user: User): Observable<any> {\r\n    return this.http.post<any>(\'http://127.0.0.1:8000/api/auth/login\', user);\r\n  }\r\n  // Access user profile\r\n  profileUser(): Observable<any> {\r\n    return this.http.get(\'http://127.0.0.1:8000/api/auth/user-profile\');\r\n  }\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(255,'token.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\n@Injectable({\r\n  providedIn: \'root\',\r\n})\r\nexport class TokenService {\r\n  private issuer = {\r\n    login: \'http://127.0.0.1:8000/api/auth/login\',\r\n    register: \'http://127.0.0.1:8000/api/auth/register\',\r\n  };\r\n  constructor() {}\r\n  handleData(token: any) {\r\n    localStorage.setItem(\'auth_token\', token);\r\n  }\r\n  getToken() {\r\n    return localStorage.getItem(\'auth_token\');\r\n  }\r\n  // Verify the token\r\n  isValidToken() {\r\n    const token = this.getToken();\r\n    if (token) {\r\n      const payload = this.payload(token);\r\n      if (payload) {\r\n        return Object.values(this.issuer).indexOf(payload.iss) > -1\r\n          ? true\r\n          : false;\r\n      }\r\n      return false;\r\n    } else {\r\n      return false;\r\n    }\r\n  }\r\n  payload(token: any) {\r\n    const jwtPayload = token.split(\'.\')[1];\r\n    return JSON.parse(atob(jwtPayload));\r\n  }\r\n  // User state based on valid token\r\n  isLoggedIn() {\r\n    return this.isValidToken();\r\n  }\r\n  // Remove token\r\n  removeToken() {\r\n    localStorage.removeItem(\'auth_token\');\r\n  }\r\n}\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(256,'app.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { BrowserModule } from \'@angular/platform-browser\';\r\nimport { AppComponent } from \'./app.component\';\r\nimport { AppRoutingModule } from \'./app-routing.module\';\r\nimport { SigninComponent } from \'./components/signin/signin.component\';\r\nimport { SignupComponent } from \'./components/signup/signup.component\';\r\nimport { HttpClientModule, HTTP_INTERCEPTORS } from \'@angular/common/http\';\r\nimport { ReactiveFormsModule, FormsModule } from \'@angular/forms\';\r\nimport { AuthInterceptor } from \'shared/auth.interceptor\';\r\nimport { UserProfileComponent } from \'./components/user-profile/user-profile.component\';\r\n\r\n\r\n\r\n\r\n@NgModule({\r\n  declarations: [\r\n    AppComponent,\r\n    SigninComponent,\r\n    SignupComponent,\r\n    UserProfileComponent\r\n  ],\r\n  imports: [\r\n    BrowserModule, HttpClientModule,ReactiveFormsModule,\r\n    FormsModule, AppRoutingModule,\r\n  ],\r\n  providers: [    {\r\n    provide: HTTP_INTERCEPTORS,\r\n    useClass: AuthInterceptor,\r\n    multi: true\r\n  }],\r\n  bootstrap: [AppComponent]\r\n})\r\nexport class AppModule { }\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(257,'app-routing.module.ts\r\nimport { NgModule } from \'@angular/core\';\r\nimport { Routes, RouterModule } from \'@angular/router\';\r\nimport { SigninComponent } from \'./components/signin/signin.component\';\r\nimport { SignupComponent } from \'./components/signup/signup.component\';\r\nimport { UserProfileComponent } from \'./components/user-profile/user-profile.component\';\r\nconst routes: Routes = [\r\n  { path: \'\', redirectTo: \'/login\', pathMatch: \'full\' },\r\n  { path: \'login\', component: SigninComponent },\r\n  { path: \'register\', component: SignupComponent },\r\n  { path: \'profile\', component: UserProfileComponent },\r\n];\r\n@NgModule({\r\n  imports: [RouterModule.forRoot(routes)],\r\n  exports: [RouterModule],\r\n})\r\nexport class AppRoutingModule {}\r\n\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(258,'app.component.html\r\n<div class=\"d-flex flex-column flex-md-row align-items-center mb-5 p-4 shadow sticky-top\">\r\n  <h5 class=\"my-0 mr-md-auto font-weight-normal\">Laravel Angular JWT Auth</h5>\r\n  <nav class=\"my-2 my-md-0 mr-md-3\">\r\n    <a class=\"p-2 text-dark\" routerLink=\"/profile\" routerLinkActive=\"active\" *ngIf=\"isSignedIn\">User Profile</a>\r\n    <a class=\"p-2 text-dark\" *ngIf=\"!isSignedIn\" routerLink=\"/login\" routerLinkActive=\"active\">Log in</a>\r\n    <a class=\"p-2 text-dark\" routerLink=\"/register\" routerLinkActive=\"active\">Register</a>\r\n  </nav>\r\n  <button class=\"btn btn-outline-primary\" (click)=\"signOut()\" *ngIf=\"isSignedIn\">Log out</button>\r\n</div>\r\n<router-outlet></router-outlet>\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(259,'app.component.css\r\n.active{\r\n    background: black;\r\n    color: white !important;\r\n    border-radius: 10px;\r\n}\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(260,'app.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { TokenService } from \'shared/token.service\';\r\nimport { AuthStateService } from \'shared/auth-state.service\';\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  styleUrls: [\'./app.component.css\'],\r\n})\r\nexport class AppComponent implements OnInit {\r\n  isSignedIn!: boolean;\r\n  constructor(\r\n    private auth: AuthStateService,\r\n    public router: Router,\r\n    public token: TokenService\r\n  ) {}\r\n  ngOnInit() {\r\n    this.auth.userAuthState.subscribe((val) => {\r\n      this.isSignedIn = val;\r\n    });\r\n  }\r\n  // Signout\r\n  signOut() {\r\n    this.auth.setAuthState(false);\r\n    this.token.removeToken();\r\n    this.router.navigate([\'login\']);\r\n  }\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(261,'signin.component.html\r\n<div class=\"container\">\r\n  <div class=\"row align-items-center justify-content-center\">\r\n    <div class=\"col-md-6\">\r\n      <div class=\"auth-wrapper\">\r\n        <form class=\"form-signin\" [formGroup]=\"loginForm\" (ngSubmit)=\"onSubmit()\">\r\n          <h3 class=\"h3 mb-3 font-weight-normal text-center\">Sign in</h3>\r\n          <!-- Errors -->\r\n          <div *ngIf=\"errors?.email\" class=\"alert alert-danger mt-3\">\r\n            {{ errors?.email }}\r\n          </div>\r\n          <div *ngIf=\"errors?.password\" class=\"alert alert-danger mt-3\">\r\n            {{ errors?.password }}\r\n          </div>\r\n          <div *ngIf=\"errors?.error\" class=\"alert alert-danger mt-3\">\r\n            {{ errors?.error }}\r\n          </div>\r\n          <!-- Login -->\r\n          <div class=\"form-group\">\r\n            <label>Email address</label>\r\n            <input type=\"email\" class=\"form-control\" formControlName=\"email\">\r\n          </div>\r\n          <div class=\"form-group\">\r\n            <label>Password</label>\r\n            <input type=\"password\" class=\"form-control\" formControlName=\"password\">\r\n          </div>\r\n          <button type=\"submit\" class=\"btn px-4 mt-3 btn-block btn-primary\">Log in</button>\r\n        </form>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(262,'signin.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { AuthService } from \'shared/auth.service\';\r\nimport { FormBuilder, FormGroup } from \'@angular/forms\';\r\nimport { TokenService } from \'shared/token.service\';\r\nimport { AuthStateService } from \'shared/auth-state.service\';\r\n@Component({\r\n  selector: \'app-signin\',\r\n  templateUrl: \'./signin.component.html\',\r\n  styleUrls: [\'./signin.component.css\'],\r\n})\r\nexport class SigninComponent implements OnInit {\r\n  loginForm: FormGroup;\r\n  errors:any = null;\r\n  constructor(\r\n    public router: Router,\r\n    public fb: FormBuilder,\r\n    public authService: AuthService,\r\n    private token: TokenService,\r\n    private authState: AuthStateService\r\n  ) {\r\n    this.loginForm = this.fb.group({\r\n      email: [],\r\n      password: [],\r\n    });\r\n  }\r\n  ngOnInit() {}\r\n  onSubmit() {\r\n    this.authService.signin(this.loginForm.value).subscribe(\r\n      (result) => {\r\n        this.responseHandler(result);\r\n      },\r\n      (error) => {\r\n        this.errors = error.error;\r\n      },\r\n      () => {\r\n        this.authState.setAuthState(true);\r\n        this.loginForm.reset();\r\n        this.router.navigate([\'profile\']);\r\n      }\r\n    );\r\n  }\r\n  // Handle response\r\n  responseHandler(data:any) {\r\n    this.token.handleData(data.access_token);\r\n  }\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(263,'signup.component.html\r\n<div class=\"auth-wrapper\">\r\n    <form class=\"form-signin\" [formGroup]=\"registerForm\" (ngSubmit)=\"onSubmit()\">\r\n      <h3 class=\"h3 mb-3 font-weight-normal text-center\">Register User</h3>\r\n      <!-- Errors -->\r\n      <div *ngIf=\"errors?.name\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.name }}\r\n      </div>\r\n      <div *ngIf=\"errors?.email\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.email }}\r\n      </div>\r\n      <div *ngIf=\"errors?.password\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.password }}\r\n      </div>\r\n      <div *ngIf=\"errors?.password_confirmation\" class=\"alert alert-danger mt-3\">\r\n        {{ errors?.password_confirmation }}\r\n      </div>\r\n      <!-- Signup form -->\r\n      <div class=\"form-group\">\r\n        <label>Name</label>\r\n        <input type=\"text\" class=\"form-control\" formControlName=\"name\" />\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label>Email address</label>\r\n        <input type=\"email\" class=\"form-control\" formControlName=\"email\" />\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label>Password</label>\r\n        <input type=\"password\" class=\"form-control\" formControlName=\"password\" />\r\n      </div>\r\n      <div class=\"form-group\">\r\n        <label>Confirm Password</label>\r\n        <input\r\n          type=\"password\"\r\n          class=\"form-control\"\r\n          formControlName=\"password_confirmation\"\r\n        />\r\n      </div>\r\n      <button type=\"submit\" class=\"btn btn-block btn-primary\">\r\n        Register User\r\n      </button>\r\n    </form>\r\n  </div>\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(264,'signup.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { Router } from \'@angular/router\';\r\nimport { AuthService } from \'shared/auth.service\';\r\nimport { FormBuilder, FormGroup } from \'@angular/forms\';\r\n@Component({\r\n  selector: \'app-signup\',\r\n  templateUrl: \'./signup.component.html\',\r\n  styleUrls: [\'./signup.component.css\'],\r\n})\r\nexport class SignupComponent implements OnInit {\r\n  registerForm: FormGroup;\r\n  errors: any = null;\r\n  constructor(\r\n    public router: Router,\r\n    public fb: FormBuilder,\r\n    public authService: AuthService\r\n  ) {\r\n    this.registerForm = this.fb.group({\r\n      name: [\'\'],\r\n      email: [\'\'],\r\n      password: [\'\'],\r\n      password_confirmation: [\'\'],\r\n    });\r\n  }\r\n  ngOnInit() {}\r\n  onSubmit() {\r\n    this.authService.register(this.registerForm.value).subscribe(\r\n      (result) => {\r\n        console.log(result);\r\n      },\r\n      (error) => {\r\n        this.errors = error.error;\r\n      },\r\n      () => {\r\n        this.registerForm.reset();\r\n        this.router.navigate([\'login\']);\r\n      }\r\n    );\r\n  }\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(265,'user-profile.component.html\r\n<div class=\"container\">\r\n    <div class=\"card inner-main\">\r\n      <div class=\"card-header\">\r\n        User Profile\r\n      </div>\r\n      <div class=\"card-body\">\r\n        <p class=\"card-text\">Name: <strong>{{UserProfile.name}}</strong></p>\r\n        <p class=\"card-text\">Email: <strong>{{UserProfile.email}}</strong></p>\r\n      </div>\r\n    </div>\r\n  </div>\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(266,'user-profile.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { AuthService } from \'shared/auth.service\';\r\n// User interface\r\nexport class User {\r\n  name: any;\r\n  email: any;\r\n}\r\n@Component({\r\n  selector: \'app-user-profile\',\r\n  templateUrl: \'./user-profile.component.html\',\r\n  styleUrls: [\'./user-profile.component.css\'],\r\n})\r\nexport class UserProfileComponent implements OnInit {\r\n  UserProfile!: User;\r\n  constructor(public authService: AuthService) {\r\n    this.authService.profileUser().subscribe((data: any) => {\r\n      this.UserProfile = data;\r\n    });\r\n  }\r\n  ngOnInit() {}\r\n}\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(267,'register.json\r\n{\r\n    \"message\": \"User successfully registered\",\r\n    \"user\": {\r\n        \"name\": \"Boula\",\r\n        \"email\": \"boula.nessim.soliman@gmail.com\",\r\n        \"updated_at\": \"2022-09-26T13:44:21.000000Z\",\r\n        \"created_at\": \"2022-09-26T13:44:21.000000Z\",\r\n        \"id\": 2\r\n    }\r\n}\r\n\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(268,'login.json\r\n{\r\n    \"access_token\": \"eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9.eyJpc3MiOiJodHRwOlwvXC8xMjcuMC4wLjE6ODAwMFwvYXBpXC9hdXRoXC9sb2dpbiIsImlhdCI6MTY2NDE5OTk0MiwiZXhwIjoxNjY0MjAzNTQyLCJuYmYiOjE2NjQxOTk5NDIsImp0aSI6IjVSbjhVUlZSdXFua1hSbE4iLCJzdWIiOjIsInBydiI6Ijg3ZTBhZjFlZjlmZDE1ODEyZmRlYzk3MTUzYTE0ZTBiMDQ3NTQ2YWEifQ.dgTsZQhYVZq9BcKVf1rMoQ1BIvmkqqIDBP-1pZlHXJ0\",\r\n    \"token_type\": \"bearer\",\r\n    \"expires_in\": 3600,\r\n    \"user\": {\r\n        \"id\": 2,\r\n        \"name\": \"Boula\",\r\n        \"email\": \"boula.nessim.soliman@gmail.com\",\r\n        \"email_verified_at\": null,\r\n        \"created_at\": \"2022-09-26T13:44:21.000000Z\",\r\n        \"updated_at\": \"2022-09-26T13:44:21.000000Z\"\r\n    }\r\n}\r\n\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(269,'Bootstrap classes\r\nbg-dark, text-dark, d-flex, alert alert-danger, mt-3 , mb-3,h3, mb-3, font-weight-normal, text-center\r\nalign-items-center, justify-content-center,my-0, mr-md-auto,d-flex, flex-column, flex-md-row, align-items-center, mb-5, p-4, shadow, sticky-top, text-dark,btn btn-outline-primary, btn btn-secondary,col col-md-12, offset-md-12, table, btn btn-primary, form-group, form-control, \r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(270,'Js functions\r\nwindow.location.href.split(\'/\')[3]; //To get part of url\r\narr.push(obj) //to push an object inside array\r\nwindow.location.reload();\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(271,'Using headers to get date according to lang\r\n  get(lang:string, model:string):Observable<any>  {\r\n    const httpOptions = {\r\n      headers: new HttpHeaders().set(\'content-type\', \'application/json\').set(\'locale\', lang)\r\n    }\r\n    return this.http.get(`${this.baseUrl}${model}`, httpOptions);\r\n  }\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(272,'Oxford Training application\r\n\r\nhome.component.ts\r\nimport { Component, OnInit } from \'@angular/core\';\r\nimport { OwlOptions } from \'ngx-owl-carousel-o\';\r\nimport { AppComponent } from \'../app.component\';\r\nimport { AppService } from \'../app.service\';\r\n\r\n\r\n\r\n\r\n\r\n@Component({\r\n  selector: \'app-home\',\r\n  templateUrl: \'./home.component.html\',\r\n  styleUrls: [\'./home.component.css\']\r\n})\r\nexport class HomeComponent implements OnInit {\r\n\r\n  data: any = [];\r\n  allCategories: any[] = [];\r\n  trendingCats: any[] = [];\r\n  trendingCourses: any = [];\r\n  courses: any = [];\r\n\r\n\r\n\r\n  carouselOption: OwlOptions = {\r\n    loop: true,\r\n    mouseDrag: true,\r\n    touchDrag: false,\r\n    pullDrag: false,\r\n    dots: false,\r\n    autoplay: true,\r\n    navSpeed: 700,\r\n    autoplaySpeed: 200,\r\n    navText: [\'\', \'\'],\r\n    responsive: {\r\n      0: {\r\n        items: 1\r\n      },\r\n      400: {\r\n        items: 1\r\n      },\r\n      740: {\r\n        items: 1\r\n      },\r\n      940: {\r\n        items: 4\r\n      }\r\n    },\r\n    nav: false\r\n  }\r\n\r\n  constructor(public _appService: AppService, public app: AppComponent) {\r\n    this.get();\r\n  }\r\n\r\n  get() {\r\n    this._appService.get(this.app.translate.currentLang, \'home\').subscribe((data) => {\r\n      this.data = data.data;\r\n      console.log(\'get fun in home is fired\');\r\n      console.log(this.data);\r\n      this.getTrendingCats();\r\n    });\r\n\r\n    this._appService.get(this.app.translate.currentLang, \'categories\').subscribe((data) => {\r\n      this.allCategories = data.data.category;\r\n    });\r\n  }\r\n\r\n  getTrendingCats() {\r\n    this.trendingCourses = this.data[\'trending-courses\'];\r\n    let categories: any = [];\r\n    for (let course of this.trendingCourses) {\r\n      categories.push({ category_id: course.category_id, category_name: course.category });\r\n    }\r\n\r\n    this.trendingCats = categories.filter((item: any, index: number, arr: any) => {\r\n      return this.findIndex(arr, item.category_id) === index;\r\n    });\r\n  }\r\n\r\n  findIndex(arr: any, itemId: any) {\r\n    let index;\r\n    for (let i = 0; i < arr.length; i++) {\r\n      if (arr[i].category_id === itemId) {\r\n        index = i;\r\n      }\r\n    }\r\n    return index;\r\n  }\r\n\r\n  getCoursesByCategoryId(categoryId: number): void {\r\n    for (let item of this.trendingCourses) {\r\n      if (item.category_id === categoryId)\r\n        this.courses.push(item);\r\n    }\r\n\r\n    console.log(\'courses\', this.courses);\r\n\r\n  }\r\n\r\n\r\n\r\n  ngOnInit(): void {\r\n  }\r\n\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(273,'app.component.ts\r\nimport { Component, Inject, LOCALE_ID } from \'@angular/core\';\r\nimport { TranslateService } from \'@ngx-translate/core\';\r\nimport { LocalizeRouterService } from \'@gilsdav/ngx-translate-router\';\r\nimport { AppService } from \'./app.service\';\r\n\r\n\r\n@Component({\r\n  selector: \'app-root\',\r\n  templateUrl: \'./app.component.html\',\r\n  styleUrls: [\'./app.component.css\']\r\n})\r\nexport class AppComponent {\r\n  title = \'oxford-training\';\r\n\r\n\r\n\r\n\r\n\r\n  public static appLang: any = localStorage.getItem(\"language\");\r\n\r\n  constructor(@Inject(LOCALE_ID) public activeLocale: string, public translate: TranslateService, private localize: LocalizeRouterService,\r\n    public _appService: AppService) {\r\n    // this language will be used as a fallback when a translation isn\'t found in the current language\r\n    translate.addLangs([\'en\', \'ar\']);\r\n    this.translate.currentLang = AppComponent.appLang;\r\n    translate.use(AppComponent.appLang);\r\n    document.getElementsByTagName(\"html\")[0].setAttribute(\"lang\", this.translate.currentLang);\r\n    if (AppComponent.appLang === \'ar\') {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"rtl\");\r\n    }\r\n    else {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"ltr\");\r\n    }\r\n\r\n  }\r\n\r\n\r\n  switchLang(lang: string) {\r\n    AppComponent.appLang = lang;\r\n    AppComponent.appLang=window.location.pathname.slice(-2)==\'ar\';\r\n    this.translate.currentLang = AppComponent.appLang;\r\n    this.translate.use(AppComponent.appLang);\r\n    localStorage.setItem(\"language\", lang);\r\n    this.localize.changeLanguage(lang);\r\n    if (localStorage.getItem(\"language\") === \'ar\') {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"rtl\");\r\n    }\r\n    else {\r\n      document.getElementsByTagName(\"html\")[0].setAttribute(\"dir\", \"ltr\");\r\n    }\r\n\r\n     window.location.reload();\r\n\r\n\r\n  }\r\n}\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(274,'app.service.ts\r\nimport { Injectable } from \'@angular/core\';\r\nimport { Observable } from \'rxjs\';\r\nimport { HttpClient, HttpHeaders } from \'@angular/common/http\';\r\n\r\n\r\n@Injectable({\r\n  providedIn: \'root\'\r\n})\r\nexport class AppService {\r\n\r\n  constructor(private http: HttpClient ) {}\r\n\r\n  baseUrl: any = \"http://127.0.0.1:8000/api/\";\r\n\r\n\r\n  get(lang:string, model:string):Observable<any>  {\r\n    const httpOptions = {\r\n      headers: new HttpHeaders().set(\'content-type\', \'application/json\').set(\'locale\', lang)\r\n    }\r\n\r\n    return this.http.get(`${this.baseUrl}${model}`, httpOptions);\r\n  }\r\n}\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(275,'app.module.ts\r\nimport { LOCALE_ID, NgModule } from \'@angular/core\';\r\nimport { BrowserModule } from \'@angular/platform-browser\';\r\n\r\nimport { AppComponent } from \'./app.component\';\r\nimport { NavbarComponent } from \'./navbar/navbar.component\';\r\nimport { PreloaderComponent } from \'./preloader/preloader.component\';\r\nimport { HomeComponent } from \'./home/home.component\';\r\nimport { FooterComponent } from \'./footer/footer.component\';\r\nimport { AppRoutingModule } from \'./app-routing.module\';\r\nimport { HttpClient, HttpClientModule } from \'@angular/common/http\';\r\nimport { TranslateLoader, TranslateModule, TranslateService } from \'@ngx-translate/core\';\r\nimport { TranslateHttpLoader } from \'@ngx-translate/http-loader\';\r\nimport { CarouselModule } from \'ngx-owl-carousel-o\';\r\nimport { BrowserAnimationsModule } from \'@angular/platform-browser/animations\';\r\nimport { AboutComponent } from \'./about/about.component\';\r\nimport { LocalizeParser, LocalizeRouterModule, LocalizeRouterSettings, ManualParserLoader } from \'@gilsdav/ngx-translate-router\';\r\nimport {Location} from \'@angular/common\';\r\n// import {LocalizeRouterHttpLoader} from \'@gilsdav/ngx-translate-router-http-loader\';\r\nimport {RouterModule} from \'@angular/router\';\r\nimport {routes} from \'../app/app-routing.module\';\r\n\r\n\r\n\r\n\r\n// AOT compilation support\r\n// AOT compilation support\r\nexport function httpTranslateLoader(http: HttpClient) {\r\n  return new TranslateHttpLoader(http);\r\n}\r\n@NgModule({\r\n  declarations: [\r\n    AppComponent,\r\n    NavbarComponent,\r\n    PreloaderComponent,\r\n    HomeComponent,\r\n    FooterComponent,\r\n    AboutComponent\r\n  ],\r\n  imports: [\r\n    BrowserModule,\r\n    AppRoutingModule,\r\n    HttpClientModule,\r\n    BrowserAnimationsModule,\r\n    CarouselModule,\r\n    TranslateModule.forRoot({\r\n      loader: {\r\n        provide: TranslateLoader,\r\n        useFactory: httpTranslateLoader,\r\n        deps: [HttpClient]\r\n      }\r\n    }),\r\n    RouterModule.forRoot(routes),\r\n    LocalizeRouterModule.forRoot(routes, {\r\n      parser: {\r\n        provide: LocalizeParser,\r\n        useFactory: (translate: TranslateService, location: Location, settings: LocalizeRouterSettings) =>\r\n            new ManualParserLoader(translate, location, settings, [\'en\',\'ar\']),\r\n        deps: [TranslateService, Location, LocalizeRouterSettings]\r\n      }\r\n    })\r\n  ],\r\n  providers: [{\r\n    provide: LOCALE_ID,\r\n    useValue: AppComponent.appLang\r\n  }],\r\n  bootstrap: [AppComponent]\r\n})\r\nexport class AppModule { }\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(276,'How to make an attribute dynamic ba addin attr.\r\nattr.data-bs-target=\"{{ cat.category_id }}\"\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(277,'How to make @Input()\r\n//breadcrumb.component.ts\r\nexport class BreadcrumbComponent {\r\n  @Input() item = \'\';\r\n}\r\n//breadcrumb.component.html\r\n<li class=\"breadcrumb-item  fw-bold active\" aria-current=\"page\">{{item}}</li>\r\n//client-page.component.html\r\n<app-breadcrumb [item]=\"currentItem\"></app-breadcrumb>\r\n//client-page.component.ts\r\nexport class ClientPageComponent {\r\n  currentItem:string=\'CLIENT\';\r\n}\r\n//media-page.component.html\r\n<app-breadcrumb [item]=\"currentItem | translate\"></app-breadcrumb>\r\n//media-page.component.ts\r\ncurrentItem:string=\'media\';\r\n\r\n','2024-02-09 02:11:33','2024-02-09 02:11:33'),(278,'Angular .htaccess\r\n<IfModule mod_rewrite.c>\r\n\r\n  RewriteEngine On\r\n  RewriteBase /\r\n  RewriteRule ^index\\.html$ - [L]\r\n  RewriteCond %{REQUEST_FILENAME} !-f\r\n  RewriteCond %{REQUEST_FILENAME} !-d\r\n  RewriteCond %{REQUEST_FILENAME} !-l\r\n  RewriteRule . /index.html [L]\r\n\r\n</IfModule>','2024-02-09 02:11:33','2024-02-09 02:11:33'),(279,'Bootstrap & CSS Reference\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(280,'How to control content from ck editor\r\n.description .p{color:white} \r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(281,'Using positions in bootstrap5\r\nposition-relative\r\nposition-absolute top-0 start-0\r\nposition-fixed\r\nposition-static\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(282,'El Zero Course\r\n\r\nDifference between inline, block and inline-block\r\n\r\nBlock\r\n-Take  full width when no width determined\r\n-Add line breaks before and after each element\r\n-Respect padding, margin, width and height\r\n\r\n\r\nInline\r\n-Do not respect width and height\r\n-Respect padding and margin just for [left & right]\r\n-Do not add line breaks\r\n-Allow elements before and after it\r\n\r\n\r\nInline-block\r\n-Allow elements before and after it\r\n-Respect padding and margin\r\n\r\nbackground-attachment:fixed;\r\nbackground-position:left top or center right\r\nbackground-size:auto cover contain(extinsable)\r\n\r\n\r\ndiff between display:none and visibility:hidden is that visibility:hidden keeps element  position  while display:none does not\r\n\r\nwidth:fit-content;\r\noverflow:hidden or scroll or auto\r\ntext-shadow:h-shadow v-shadow color blur;\r\nvertical-align:middle,top,bottom; // used when combining text and image\r\n\r\n//to use float:left,right; and add like clear (break) to stop affecting next element after floated elements use clear\r\nclear:left,right,both;\r\nem => time of parent font size\r\nrem=> Root time (root refer to html) and default size is 16px\r\npercentage=> percentage of parent font size\r\nvw=> viewport width (if viewport is 900 px then 1 vw is 9px) and it is very important in responsive\r\nvh same as vw but with height\r\nfont-style:italic;\r\ncss topics\r\ninheritance\r\nnesting\r\noverride\r\ncursor:pointer;\r\ncursor:grab;\r\nvertical-align:middle;\r\ntext-decoration:line through, underline, overline, none;\r\ntext-transform:uppercase, lowercase, capitalize;\r\nletter-spacing:2px;\r\ntext-indent:100px;\r\nline-height:1.2;\r\nword-spacing:5px;\r\nwhite-spacing:nowrap;\r\nword-break:5px;\r\ntext-overflow:ellipsis;\r\ntitle attribute in html\r\nborder-color:inherit: using inheritance in general\r\ndiv{color:red;}\r\ndiv p{color:inherit; //red};\r\n@font-face{font-family:”myFont”,\r\nsr:url(‘’)};\r\n\r\nposition:static is the default and it is not affected by top right etc properties\r\nposition:relative; move according to its current position\r\nposition:absolute; move according to webpage or according to the first parent with position:relative;\r\nposition:fixed; move according to web page and move with scroll and does not affected with parent position\r\nposition:sticky; top:0; ex: sticky navbar.\r\n\r\n\r\nz-index => layers\r\nz-index works only with elements that have position property\r\nwhen z-index:-1; this means to put the element in last layer\r\n.ch + label {} means the label element after class .ch\r\nforcestate developer tool option\r\npseudo classes and elements\r\npseudo mean unreal\r\n:hover :checked :visited :link :empty :focus\r\n::first-letter ::first-line ::selection\r\n\r\n::after and ::before must have content:\"\";\r\n\r\noutline:2px solid red; and border:2px solid red; border is better\r\ntransition-delay:1s;\r\ntransition-property:width;\r\ntransition-duration:2s;\r\ntransition-timing-function:ease, ease-in, ease-in-out, linear;\r\ntransition:width 1s .5s linear;\r\n\r\n\r\nflexible Box for parent\r\ndisplay:flex; to start flexible box;\r\nflex-direction:row => default, column, row-reverse, column-reverse;\r\nflex-wrap:no-wrap => default,\r\nflex-flow:[flex-direction flex-wrap];\r\nflex-flow:row wrap;\r\njustify-content:flex-start => default, flex-end, space-between, space-around, space-evenly;\r\nNote: It is recommended to use width: calc(100%/3); with flex box\r\nalign-items:stretch => default, flex-start, flex-end, space-between, space-around\r\n\r\n\r\njustify-items:flex-start => default, flex-end, space-between, space-around, space-evenly;\r\nNote: It is recommended to use width: calc(100%/3); with flex box\r\nalign-content:stretch => default, flex-start, flex-end, space-between, space-around\r\n\r\n\r\nflex box for child\r\nflex-grow:0 => default\r\nflex-shrink:1 => default\r\norder:0 =>default //order must be given to element wanted to move and the one in destination position at the same time\r\nflex-basis:auto => default //flex basis depends on direction\r\nflex:[flex grow] [flex shrink] [flex basis]\r\ndisplay:inline flex; //to put element inline with flex row\r\nalign-self: start, end;\r\ntext-nowrap //to remove wrap in text\r\n\r\nfilter:blur(50%);\r\nfilter:grayscale(100%);\r\nfilter:invert(100%);\r\nbackground-image:linear-gradient(to right, red, blue,green);\r\nbackground-image:linear-gradient(90deg, red, blue,green);\r\nbackground-image:linear-gradient(to right,\r\ncolor1: 20%,\r\ncolor2: 20%,\r\ncolor2:40%,\r\ncolor3:40%,\r\ncolor3:60%,\r\ncolor4:60%,\r\ncolor4:80%,\r\ncolor5:80%,);\r\ncontenteditable=”true”;\r\ncaret-color:red;\r\npointer-events:none;\r\n\r\nGrid\r\nParent\r\ndisplay:grid | inline-grid;\r\n\r\ngrid-template-columns:[number of columns in] => [PX, %, Auto, Fraction, Repeat(num,value),Mix]\r\ngrid-template-columns:auto,50%,30px,1fr,2fr,repeat(2,auto);\r\n\r\ngrid-template-rows:[number of columns in] => [PX, %, Auto, Fraction, Repeat(num,value),Mix]\r\ngrid-template-rows:auto,50%,30px,1fr,2fr,repeat(2,auto);\r\n\r\ngap-row:20px;\r\ngap-column:20px;\r\n\r\ngap:20px 20px;\r\n\r\nauto is shy and fr is greedy\r\n\r\njustify-content:flex-start => default, flex-end, space-between, space-around, space-evenly;\r\nNote: It is recommended to use width: calc(100%/3); with flex box\r\nalign-items:stretch => default, flex-start, flex-end, space-between, space-around\r\n\r\njustify-items:flex-start => default, flex-end, space-between, space-around, space-evenly;\r\nNote: It is recommended to use width: calc(100%/3); with flex box\r\nalign-content:stretch => default, flex-start, flex-end, space-between, space-around\r\n\r\ngrid-template-areas: “logo nav nav nav”, “content content content aside”,”. footer footer footer”;\r\n\r\ngrid-area:logo;\r\n\r\nGrid for child\r\ngrid-column:1/5;\r\ngrid-column:span 4;\r\ngrid-column:2/span 3;\r\n\r\ngrid-row:1/5;\r\ngrid-row:span 4;\r\ngrid-row:2/span 3;\r\n\r\ngrid-row-start:2;\r\ngrid-column-start:2;\r\ngrid-row-end:5;\r\ngrid-column-end:6;\r\ngrid-area:2/2/5/6;\r\n\r\ngrid-template-columns: minmax(200px - 400px);\r\ngrid-template-columns: repeat(auto-fill - 200px);\r\ngrid-template-columns: repeat(auto-fill - minmax(200px));\r\nread about auto-fit\r\n\r\ntransform:scaleX(1.5);\r\ntransform:scaleY(1.5);\r\ntransform:scale(1.5,1.5); // x and y\r\ntransform:scaleX(-1); //flip the element at x axis\r\ntransform:scaleY(-1); //flip the element at y axis\r\n\r\ntransform:rotateX(180 deg);\r\ntransform:rotateY(180 deg);\r\ntransform:rotateY(0.5 turn); //half of turn\r\ntransform:rotate(180 deg); // x and y 180deg\r\ntransform:scale(1.5 )rotateY(180 deg); //to use scale and rotate together\r\nopacity:0.6;\r\ntransform:translate(x,y); //to mov element\r\n–webkit-transform\r\n\r\ntransform:skewX(-90 deg);\r\ntransform:skewY(90 deg);\r\ntransform:skew(10 deg, 10deg);\r\n//to skew the element background without affecting it use sudo element ::before\r\ntransform:matrix(scaleX,scaleY,skewX,skewY,translateX,translateY); // to use all transform options together\r\n\r\n2d transform-origin(x,y);\r\n3d transform-origin(x,y,z);\r\ntransform-origin(top,left);\r\ntransform-origin(center,center); =>default //to determine the origin point of the shape give this to parent\r\ntransform:rotate3d();\r\ntransform:translate3d();\r\nprospective:300px; //must be given to shape parent to use z axis\r\nprospective-origin:top right;\r\n\r\n\r\nback-visibility:hidden;\r\ntransform-style:flat;\r\ntransform-style:perspective-3d;\r\n\r\n\r\nCss selectors\r\n*\r\nElement => [p, div, h2]\r\nElement => other Element [div p]\r\n.class-name\r\n#id-name\r\n.parent .child\r\n.class one.class two //element that has both classes\r\nclass-name div, class-name p\r\nElement.class-name\r\n.parent > .child => Direct Child\r\n\r\nElement + Other Element => [div + p]\r\nElement ~ Other Element => [div ~ p]\r\n[Attribute]\r\nElement [Attribute]\r\n[Attribute=value]\r\nElement [Attribute=value] => input [type=”submit”]\r\n[Attribute~=value] => contain a word\r\n[Attribute*=value] => contain a string\r\n[Attribute^=value] => start with a string\r\n:first-child\r\n:last-child\r\n:first-of-type\r\n:last-of-type\r\n:only-child\r\n:not(Selectors)\r\n:nth-child(n)\r\n:nth-last-child(n)\r\n:nth-of-type(n)\r\n:nth-last-of-type(n)\r\n:root\r\n:checked\r\n:empty\r\n:disabled\r\n:required\r\n:focus\r\n::selection\r\n::placeholder\r\n\r\nGlobal variables\r\ninherit\r\ninitial\r\nunset if inherit inherit else initial\r\nrevert css level 4 \r\nall\r\nctrl+0 reset zoom\r\nm mute video\r\n\r\n\r\n\r\n//image-container\r\n\r\n//font family site\r\nhttps://fonts.google.com/specimen/Roboto?query=Roboto\r\n\r\n//to remove dots from list\r\n\r\nul {\r\n    list-style-type: none;\r\n    margin: 0;\r\n    padding: 0;\r\n  }\r\n\r\n//if bootstrap responsive doesn\'t work apply it as follow (want to margin 5 in small screens)\r\n<div class=\"col-md-4 box-shadow mt-5 m-lg-0 \">\r\n\r\n\r\nTransition scale\r\n.card-image :hover {\r\n    transform: scale(1.3);\r\n    transition: all .5s;\r\n    cursor: pointer;\r\n}\r\n\r\n//css directions\r\ntop right left bottom\r\n//css\r\n.image-container{\r\n    overflow: hidden;\r\n}\r\n//html\r\n<div class=\"image-container\">\r\n    <img class=\"card-img-top card-image\" width=\"100%\" src=\"{{ $blog->image }}\"\r\n        alt=\"Title\">\r\n</div>\r\n\r\n\r\n//limit line text very important for fixing cards size\r\n\r\n.text-limit {\r\n    overflow: hidden !important;\r\n    text-overflow: ellipsis !important;\r\n    display: -webkit-box !important;\r\n    -webkit-line-clamp: var(--lines) !important;\r\n    line-clamp: var(--lines) !important;\r\n    -webkit-box-orient: vertical !important;\r\n}\r\n\r\n<h4 class=\"card-title fs-5 text-limit\" style=\'--lines: 1;\'>{{Str::limit($blog->title, 50)}}</h4>\r\n\r\n\r\n\r\n//box shadow very important with cards and can used to create a card of anything\r\nhttps://getcssscan.com/css-box-shadow-examples\r\n\r\nWhen building a website design always refer to Bootstrap5 official site https://getbootstrap.com/docs/5.3/getting-started/introduction/ \r\n-use this link to make all the website content rtl <\r\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/npm/bootstrap@5.0.2/dist/css/bootstrap.rtl.min.css\" integrity=\"sha384-gXt9imSW0VcJVHezoNQsP+TNrjYXoGcrqBZJpry9zJt8PCQjobwmhMGaDHTASo9N\" crossorigin=\"anonymous\">\r\nhttps://developer.mozilla.org/en-US/docs/Web/CSS/position //css guide\r\nhttps://bootstrapfriendly.com//bootstrap guide\r\nhttps://bootstrap-cheatsheet.themeselection.com/ //Very organized and easy to use bootstrap5 guide and contains free dashboards \r\n//bootstrap links\r\nhttps://cdnjs.com\r\n\r\n//Download bootstrap 5\r\nhttps://getbootstrap.com/docs/5.0/getting-started/download/\r\n//download fontawesome 6\r\nhttps://fontawesome.com/download\r\n\r\n//to make h1 with a side colored line\r\nh1 {\r\n  border-style: solid;\r\n  border-color: #f57c00;\r\n  border-width: 0 0 0 3px;\r\n  padding: 0 0 0 30px;\r\n}\r\n\r\n// to make background image darker and centered\r\n.bg {\r\n  height: 370px;\r\n  object-fit: cover;\r\n  background-repeat: no-repeat;\r\n  background-size: cover;\r\n  /* background-position: center; */\r\n  background-image: linear-gradient(rgba(0, 0, 0, 0.2), rgba(0, 0, 0, 0.2)),    url(\'https://ate.demoyoursite.net/assets/images/field-3186902_1920.webp\');\r\n}\r\n//how to blur\r\n.blur{\r\n  backdrop-filter: blur(15px);\r\n  -webkit-backdrop-filter: blur(15px);\r\n  padding: 35px 40px;\r\n  border-radius: 25px 25px 0 0;\r\n  text-transform: capitalize;\r\n}\r\n//how to change active nav item color\r\n.navbar-nav > .active > a {\r\n    color: #2681db !important;\r\n   \r\n \r\n  }\r\n\r\n//overlay for carousel image\r\n.carousel-item::before{\r\n    position: absolute;\r\n    content: \'\';\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: linear-gradient(rgba(0, 0, 0, 0.4), rgba(0, 0, 0, 0.4));\r\n}\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(283,'If there is something that depend on lang handle it as following\r\n:lang(ar)::placeholder{\r\n    text-align: right !important;\r\n}\r\n:lang(en)::placeholder{\r\n    text-align: left !important;\r\n}\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(284,'Inspect margin and padding chrome tool methodology(important magic)\r\n1-click f12 for inspect\r\n2-choose element you want \r\n3- control its margin or padding by clicking - sign in green(for padding) or red (for margin)\r\n4-copy result from element \r\n5- check margin or padding for any element at the same way\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(285,'Notes\r\nWe can use bootstrap screen sizes lg md sm in many bootstrap classes to serve responsive tasks ex- p-lg-5\r\nIn case there is two elements that cannot be responsive put each one of them in separate div\r\nThe colors represent the areas of elements corresponding to the CSS box-model.\r\nBlue is the content\r\nGreen is the padding\r\nOrange is the border\r\nRed is the margin\r\n\r\nThink about css and bootstrap as a logic\r\n\r\nh1,h2,h3{} means apply to h1 and h2 and h3\r\n.class-name h1{} means h1 inside this class\r\n:lang(ar) p{} means all p tags when lang is ar\r\nwe cannot add more than one tag at the same line for a class or lang ex: :lang p,h1{} or .class-name p,h1 it is wrong\r\nDON NOT work on front tasks without including latest bootstrap version\r\nin rtl use bootstrap5 rtl file\r\nWe can add css to html element using element name for example p{} and when we want to use different css for a specific p we use its parent class for example .parent-class p{} and this is really important\r\nTo have full app height Give parent div: min-height:100vh;\r\nTo remove bottom scroll Give html{}: overflow-x:hidden;\r\ngive container to section div to remove full screen  content centered mode  \r\nTo position items easily use d-flex options,row & col and p & m and gab\r\nd-flex justify-content-center align-items-center\r\nd-flex justify-content-center align-items-end\r\nd-flex flex-column gap-5 justify-content-center align-items-center\r\nd-flex flex-row gap-5 justify-content-center align-items-center\r\n//horizontal\r\njustify-content-start justify-content-center justify-content-end\r\n//vertical\r\nalign-items-start\r\nalign-items-center\r\nalign-items-end\r\n//to toggle between horizontal and vertical use flex-column and flex-row\r\nh-90 mean height:90%; w-90 mean width:90%; p-5,pt-5,px-5,pb-5 maximum is 5 m-5,mt-5,mx-5,mb-5 maximum is 5 \r\nwe give fixed height to parent and give child height in % \r\n//Padding and margin in bootstrap\r\ns->start\r\ne->end\r\nx->s and e\r\nt->top\r\nb->bottom\r\ny->t and b\r\n//vertical\r\npt mt\r\npy my\r\npx mx\r\n//horizontal\r\nps px pe ms mx me\r\n//Text cap and low\r\ntext-capitalize text-uppercase text-lowercase\r\n//how to blod fw-bold\r\n//how to increase font size fs-2\r\n//to move an element we give it position relative,absolute or static and then control it by top bottom left right ex top:50px\r\nIt is important to use text-limit and box-shadow with cards\r\nwhen editing css fold section you are working on using ctrl+shift+[ to see elements clearly\r\nIn general if a bootstrap item is not rtl search for me,ms,mx,mr,ml or pe,ps,pr,pl elements and change or remove them to make website responsive\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(286,'Bootstrap5 classes\r\nsr-only\r\ncontainer-sm md lg \r\nCol-md-auto\r\npx-lg-3\r\nbg-submit\r\nrow row-cols-ms-2\r\nIf we did not write lg md sm it is by default all screens\r\nStart end right left top bottom\r\np\r\nm\r\nalign-items\r\nalign-self\r\njustify-content\r\nCol order-first second last \r\nCol-md-4 offset-md-4\r\ntext-muted\r\nhtml\r\nsmall tag\r\ndl tag\r\nmark tag\r\nCite tag\r\ndd tag\r\ndt tag \r\ndl tag\r\ncode tag\r\ndisplay-1 from 1-4\r\ndel\r\nblockquote\r\nlist-unstyled\r\nlist-inline\r\nlist-inline-item\r\ntext-truncate\r\nbtn-outline-success\r\ntext-transform:uppercase;\r\nbox-shadow:2px -2px 0px 5px color;\r\ntransition:all .4s;\r\nbtn-lg\r\nbtn-sm\r\nbtn-md\r\nbtn-sm\r\ninput-sm\r\ninput-md\r\ninput-lg\r\nform-select-sm\r\nd-flex flex-wrap\r\nbtn-ghost\r\nbackground-attachment:fixed;\r\nposition:fixed;\r\nlh-lg\r\nborder border-success rounded\r\n<div class=”line”></div>\r\ng-0\r\ntext-success\r\nz-index:300px;\r\nimg-thumbnail\r\ncarousel-fade\r\nimg-fluid\r\nletter-spacing:9px;\r\nmax-height:500px;\r\nimg-fluid float-right rounded mx-auto d-block\r\ntable table-dark\r\nthead-dark\r\ntable-striped\r\ncolspan=”2”\r\ntable table-borderless\r\ntable table-hover\r\ntable table-sm\r\ntable-active\r\n<caption>\r\ntable-responsive-md\r\nfigure \r\nfigure-img img-fluid rounded\r\nfigure-caption\r\nform-label\r\nform-control\r\nform-text\r\ncol-form-label\r\nform-control-lg\r\ncol-auto\r\n<datalist> tag\r\nform-select \r\nform-check\r\n<select> size=”3”\r\nform-switch\r\nform-check-input\r\nbtn-check\r\nbtn-check-outline\r\ninput-group\r\ninput-group-lg\r\ndisplay-2 //to increase font-size as much as we want\r\nclearfix\r\nfloat-md-left\r\nml-md-3\r\ntable-hover\r\nborder-primary\r\nfixed-top\r\n\r\nHome - CodeWithHarry\r\n11/16\r\nCSS Flexbox\r\nFlexbox is a layout of CSS that lets you format HTML easily. Flexbox makes it simple to align\r\nitems vertically and horizontally using rows and columns. Items will \"flex\" to different sizes to fill\r\nthe space. And overall, it makes the responsive design more manageable.\r\nParent Properties (flex container)\r\ndisplay\r\ndisplay: flex;\r\nflex-direction\r\nflex-direction: row | row-reverse | column | column-reverse;\r\nflex-wrap\r\nflex-wrap: nowrap | wrap | wrap-reverse;\r\nflex-flow\r\nflex-flow: column wrap;\r\njustify-content\r\nalign-items\r\nalign-content\r\njustify-content: flex-start | flex-end | center | space-between | space-arou\r\nalign-items: stretch | flex-start | flex-end | center | baseline | first bas\r\nHome - CodeWithHarry\r\n12/16\r\nChild Properties (flex items)\r\norder\r\norder: 5; /* default is 0 */\r\nflex-grow\r\nflex-grow: 4; /* default 0 */\r\nflex-shrink\r\nflex-shrink: 3; /* default 1 */\r\nflex-basis\r\nflex-basis: | auto; /* default auto */\r\nflex shorthand\r\nflex: none | [ <\'flex-grow\'> <\'flex-shrink\'>? || <\'flex-basis\'> ]\r\nalign-self\r\nalign-self: auto | flex-start | flex-end | center | baseline | stretch;\r\nCSS Grid\r\nGrid layout is a 2-Dimensional grid system to CSS that creates complex responsive web design\r\nlayouts more easily and consistently across browsers.\r\nParent Properties (Grid container)\r\ndisplay\r\nalign-content: flex-start | flex-end | center | space-between | space-around\r\nHome - CodeWithHarry\r\n13/16\r\ndisplay: grid | inline-grid;\r\ngrid-template-columns\r\ngrid-template-columns: 12px 12px 12px;\r\ngrid-template-rows\r\ngrid-template-rows: 8px auto 12px;\r\ngrid-template\r\ngrid-template: none | <grid-template-rows> / <grid-template-columns>;\r\ncolumn-gap\r\ncolumn-gap: <line-size>;\r\nrow-gap\r\nrow-gap: <line-size>;\r\ngrid-column-gap\r\ngrid-column-gap: <line-size>;\r\ngrid-row-gap\r\ngrid-row-gap: <line-size>;\r\ngap shorthand\r\ngap: <grid-row-gap> <grid-column-gap>;\r\nHome - CodeWithHarry\r\n14/16\r\ngrid-gap shorthand\r\ngrid-gap: <grid-row-gap> <grid-column-gap>;\r\njustify-items\r\njustify-items: start | end | center | stretch;\r\nalign-items\r\nalign-items: start | end | center | stretch;\r\nplace-items\r\nplace-items: center;\r\njustify-content\r\nalign-content\r\nplace-content\r\nplace-content: <align-content> / <justify-content> ;\r\ngrid-auto-columns\r\ngrid-auto-columns: <track-size> ...;\r\ngrid-auto-rows\r\njustify-content: start | end | center | stretch | space-around | space-betwe\r\nalign-content: start | end | center | stretch | space-around | space-between\r\nHome - CodeWithHarry\r\n15/16\r\ngrid-auto-rows: <track-size> ...;\r\ngrid-auto-flow\r\ngrid-auto-flow: row | column | row dense | column dense;\r\nChild Properties (Grid items)\r\ngrid-column-start\r\ngrid-column-start: <number> | <name> | span <number> | span <name> | auto;\r\ngrid-column-end\r\ngrid-column-end: <number> | <name> | span <number> | span <name> | auto;\r\ngrid-row-start\r\ngrid-row-start: <number> | <name> | span <number> | span <name> | auto;\r\ngrid-row-end\r\ngrid-row-end: <number> | <name> | span <number> | span <name> | auto;\r\ngrid-column shorthand\r\ngrid-column: <start-line> / <end-line> | <start-line> / span <value>;\r\ngrid-row shorthand\r\ngrid-row: <start-line> / <end-line> | <start-line> / span <value>;\r\ngrid-area\r\nHome - CodeWithHarry\r\n16/16\r\njustify-self\r\njustify-self: start | end | center | stretch;\r\nalign-self\r\nalign-self: start | end | center | stretch;\r\nplace-self\r\nplace-self: center;\r\ngrid-area: <name> | <row-start> / <column-start> / <row-end> / <column-end>;\r\n\r\n\r\n\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(287,'Style according to lang\r\n.slash:lang(en){\r\n  transform: rotateY(180deg);\r\n}\r\n\r\n.slash:lang(ar){\r\n  transform: rotateY(0);\r\n}\r\nnote: lang here refer to lang attribute in html tag\r\n//using not in css\r\nh1:lang(en):not(.slider-title) {\r\n    border-style: solid;\r\n    border-color: #f57c00;\r\n    border-width: 0 0 0 3px;\r\n    padding: 0 0 0 30px;\r\n    width: fit-content;\r\n  }\r\n \r\n  h1:lang(ar):not(.slider-title) {\r\n    border-style: solid;\r\n    border-color: #f57c00;\r\n    border-width: 0 3px 0 0;\r\n    padding: 0 30px 0 0;\r\n    width: fit-content;\r\n  }\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(288,'Rotate element\r\n:lang(en) .phone {\r\n    rotate: 120deg;\r\n}\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(289,'Responsive Screens\r\n/* when nav collapse start */\r\n@media (max-width: 576px) {}\r\n/* after nav collapse*/\r\n@media (min-width: 576) and (max-width: 768px) {}\r\n\r\n@media (min-width: 768) and (max-width: 992px) {}\r\n\r\n@media (min-width: 992px) and (max-width: 1200px) {}\r\n\r\n@media (min-width: 1200px) and (max-width: 1400px) {}\r\n\r\nNotes:\r\nWe can add margin and padding using p-5 and m-5 as much as we want by giving p-5 and m-5 to parent tags and child tags\r\n\r\nex:\r\n<div class=\"col-md-4 p-5\">\r\n    <div class=\"p-5\">\r\n        <h2 class=\"contact-title pt-5\">{{ trans(\'site.contact_info\') }}</h2>\r\n        <div class=\"info\">\r\n            <p>{{ Settings()->address }}</p>\r\n        </div>\r\n        <div class=\"info\">{{ trans(\'site.phone\') }}:<a\r\n                href=\"tel:{{ contact(\'mobile\')->contact }}\">{{ contact(\'mobile\')->contact }} </a></div>\r\n        <div class=\"info\">{{ trans(\'site.email\') }}:<a\r\n                href=\"mailto:{{ contact(\'email\')->contact }}\">{{ contact(\'email\')->contact }}</a>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(290,'Try\r\n1-::before and ::after\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(291,'CSS cheat sheet\r\nHome - CodeWithHarry\r\n1/16\r\nFont\r\nThere are many properties related to the font, such as the face, weight, style, etc. These\r\nproperties allow you to change the style or complete look of your text.\r\nFont-Family\r\nfont-family: \'Segoe UI\', Tahoma, Geneva, Verdana, sans-serif;\r\nFont-Style\r\nfont-style: italic;\r\nFont-Variant\r\nfont-variant: small-caps;\r\nFont-Weight\r\nfont-weight: bold;\r\nFont-Size\r\nfont-size: larger;\r\nFont\r\nfont: style variant weight size family;\r\nText\r\nText properties allow one to manipulate alignment, spacing, decoration, indentation, etc., in the\r\ndocument.\r\nText-Align\r\nHome - CodeWithHarry\r\n2/16\r\ntext-align: justify;\r\nLetter-Spacing\r\nletter-spacing: .15em;\r\nText-Decoration\r\ntext-decoration: underline;\r\nWord-Spacing\r\nword-spacing: 0.25em;\r\nText-Transform\r\ntext-transform: uppercase;\r\nText-Indent\r\ntext-indent: 0.5cm;\r\nLine-Height\r\nline-height: normal;\r\nBackground\r\nAs the name suggests, these properties are related to background, i.e., you can change the color,\r\nimage, position, size, etc., of the document.\r\nBackground-Image\r\nbackground-image: url(\"Path\");\r\nHome - CodeWithHarry\r\n3/16\r\nBackground-Position\r\nbackground-position: right top;\r\nBackground-Size\r\nbackground-size: cover;\r\nBackground-Repeat\r\nbackground-repeat: no-repeat;\r\nBackground-Attachment\r\nbackground-attachment: scroll;\r\nBackground-Color\r\nbackground-color: fuchsia;\r\nBackground\r\nbackground: color image repeat attachment position;\r\nBorder\r\nBorder properties are used to change the style, radius, color, etc., of buttons or other items of\r\nthe document.\r\nBorder-Width\r\nborder-width: 5px;\r\nBorder-Style\r\nHome - CodeWithHarry\r\n4/16\r\nborder-style: solid;\r\nBorder-Color\r\nborder-color: aqua;\r\nBorder-Radius\r\nborder-radius: 15px;\r\nBorder\r\nborder: width style color;\r\nBox Model\r\nIn laymen\'s terms, the CSS box model is a container that wraps around every HTML element. It\r\nconsists of margins, borders, padding, and the actual content. It is used to create the design and\r\nlayout of web pages.\r\nFloat\r\nfloat: none;\r\nClear\r\nclear: both;\r\nDisplay\r\ndisplay: block;\r\nHeight\r\nheight: fit-content;\r\nHome - CodeWithHarry\r\n5/16\r\nWidth\r\nwidth: auto;\r\nMargin\r\nmargin: top right bottom left;\r\nPadding\r\npadding: top right bottom left;\r\nOverflow\r\noverflow: hidden;\r\nVisibility\r\nvisibility: visible;\r\nColors\r\nWith the help of the color property, one can give color to text, shape, or any other object.\r\nColor\r\ncolor: cornsilk;\r\nOpacity\r\nopacity: 4;\r\nTemplate Layout\r\nSpecifies the visual look of the content inside a template\r\nHome - CodeWithHarry\r\n6/16\r\nBox-Align\r\nbox-align : start;\r\nBox-Direction\r\nbox-direction : normal;\r\nBox-Flex\r\nbox-flex : normal;\r\nBox-Flex-Group\r\nbox-flex-group : 2;\r\nBox-Orient\r\nbox-orient : inline;\r\nBox-Pack\r\nbox-pack : justify;\r\nBox-Sizing\r\nbox-sizing : margin-box;\r\nmax-width\r\nmax-width: 800px;\r\nmin-width\r\nmin-width: 500px;\r\nHome - CodeWithHarry\r\n7/16\r\nmax-height\r\nmax-height: 100px;\r\nmin-height\r\nmin-height: 80px;\r\nTable\r\nTable properties are used to give style to the tables in the document. You can change many\r\nthings like border spacing, table layout, caption, etc.\r\nBorder-Collapse\r\nborder-collapse: separate;\r\nEmpty-Cells\r\nempty-cells: show;\r\nBorder-Spacing\r\nborder-spacing: 2px;\r\nTable-Layout\r\ntable-layout: auto;\r\nCaption-Side\r\ncaption-side: bottom;\r\nColumns\r\nHome - CodeWithHarry\r\n8/16\r\nThese properties are used explicitly with columns of the tables, and they are used to give the\r\ntable an incredible look.\r\nColumn-Count\r\ncolumn-count : 10;\r\nColumn-Gap\r\ncolumn-gap : 5px;\r\nColumn-rule-width\r\ncolumn-rule-width : medium;\r\nColumn-rule-style\r\ncolumn-rule-style : dotted ;\r\nColumn-rule-color\r\ncolumn-rule-color : black;\r\nColumn-width\r\ncolumn-width : 10px;\r\nColumn-span\r\ncolumn-span : all;\r\nList & Markers\r\nList and marker properties are used to customize lists in the document.\r\nHome - CodeWithHarry\r\n9/16\r\nList-style-type\r\nlist-style-type: square;\r\nList-style-position\r\nlist-style-position : 20px;\r\nList-style-image\r\nlist-style-image : url(�image.gif�);\r\nMarker-offset\r\nmarker-offset : auto;\r\nAnimations\r\nCSS animations allow one to animate transitions or other media files on the web page.\r\nAnimation-name\r\nanimation-name : myanimation;\r\nAnimation-duration\r\nanimation-duration : 10s;\r\nAnimation-timing-function\r\nanimation-timing-function : ease;\r\nAnimation-delay\r\nanimation-delay : 5ms;\r\nHome - CodeWithHarry\r\n10/16\r\nAnimation-iteration-count\r\nanimation-iteration-count : 3;\r\nAnimation-direction\r\nanimation-direction : normal;\r\nAnimation-play-state\r\nanimation-play-state : running;\r\nAnimation-fill-mode\r\nanimation-fill-mode : both;\r\nTransitions\r\nTransitions let you define the transition between two states of an element.\r\nTransition-property\r\ntransition-property: none;\r\nTransition-duration\r\ntransition-duration : 2s;\r\nTransition-timing-function\r\ntransition-timing-function: ease-in-out;\r\nTransition-delay\r\ntransition-delay : 20ms;\r\n\r\n\r\n\r\n\r\n','2024-02-09 02:13:29','2024-02-09 02:13:29'),(292,'Change ltr template to rtl methodology\r\n1-change template style.css to style_ar.css as follow\r\n right to boulasflag and left to right then change boulasflag to left\r\n2- crate a condition to separate between two files (style and style_ar) and also add bootstrap and bootstrap.rel according to lang \r\nex:\r\n @if (app()->getLocale()==\'en\')\r\n    <link rel=\"stylesheet\" href=\"{{asset(\'bootstrap-5.3.1-dist\\css\\bootstrap.min.css\')}}\"\r\n    <link rel=\"stylesheet\" href=\"{{ asset(\'dist/css/adminlte.min.css\') }}\">\r\n    @else\r\n    <link rel=\"stylesheet\" href=\"{{asset(\'bootstrap-5.3.1-dist\\css\\bootstrap.rtl.min.css\')}}\">\r\n    <link rel=\"stylesheet\" href=\"{{ asset(\'dist/css/adminlte.min_ar.css\') }}\">\r\n    @endif','2024-02-09 02:13:29','2024-02-09 02:13:29'),(293,'React Reference\r\n\r\nnode –v\r\nnpm –version\r\nnpm install –g create-react-app\r\nnpx create-react-app hello-world-example\r\nnpm –version\r\nnpx create-react-app hello-world-example\r\nnpm init react-app hello-world\r\nyarn create react-app hello-world-example\r\ncd hello-world-example\r\nnpm start\r\nhttp://localhost:3000/\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(294,'Packages and resources\r\nhttps://www.learmoreseekmore.com/2022/09/reactjs-v18-crud-example.html \r\nBasic Concepts of Flexbox \r\nImporting a Component \r\nBabeljs.io \r\nNPM docs: package.json \r\ngit docs: gitignore \r\nNPM docs: node modules folder \r\nwebpack docs: DevServer \r\nwebpack/webpack-dev-server on GitHub \r\nVisual Studio Code keyboard shortcuts (Windows)\r\nVisual Studio Code keyboard shortcuts (macOS) Components and props \r\nIntoducing JSX \r\nStyling and CSS in React \r\nIntroducing expressions in JSX \r\nHandling Events \r\nSupported Events \r\nSyntheticEvent \r\nHow do I pass an event handler (like onClick) to a component? \r\nJavaScript Expressions as Props \r\nJavaScript Expressions as Children \r\nReact docs website URL which discusses the issue in depth \r\nData flows down \r\nThe Power Of Not Mutating Data \r\nAdd Inverse Data Flow \r\nComponent state \r\nState: A Component\'s Memory \r\nSharing State Between Components \r\nState as a Snapshot \r\nBasic useState examples \r\nSynchronizing with effects - putting it all together \r\nFetch API \r\nThe event loop in JavaScript \r\nReact Router v6 \r\nnav: The Navigation Section element \r\nConditional (ternary) operator in JavaScript \r\nif...else \r\nReact Router v6 \r\nnav: The Navigation Section element \r\nConditional (ternary) operator in JavaScript \r\nif...else \r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(295,'Notes\r\nLearn react from github app and this refrence\r\n\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(296,'Week1 Solution1 your first component\r\nfunction Heading() { \r\n  return ( \r\n    <h1>This is an h1 heading.</h1> \r\n  ) \r\n} \r\n \r\nfunction App() { \r\n  return ( \r\n    <div className=\"App\"> \r\n     This is the starting \r\n     code for \"Your first\r\n     component\" ungraded lab \r\n      <Heading /> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App;\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(297,'Week1 Solution 2 creating and importing components\r\nfunction Heading() {\r\n      return (\r\n        <h1>This is an h1 heading</h1>\r\n      )\r\n  }\r\n  \r\n  export default Heading;\r\n\r\n  import Heading from \"./Heading\";\r\n\r\n    function App() {\r\n      return (\r\n        <div className=\"App\">\r\n          <Heading />\r\n        </div>\r\n      );\r\n    }\r\n\r\n    export default App;\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(298,'Week1 Solution3 passing props\r\n\r\nimport Heading from \"./Heading\";\r\n\r\nfunction App() {\r\n  return (\r\n    <div className=\"App\">\r\n      <Heading firstName=\"Bob\" />\r\n      <Heading firstName=\r\n      \"Any name other than Bob\" />\r\n    </div>\r\n  );\r\n}\r\n\r\nexport default App;\r\n\r\n  function Heading(props) {\r\n    return (\r\n      <h1>Hello,{props.firstName}</h1>\r\n    )\r\n  }\r\n\r\n  export default Heading;\r\n\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(299,'Week1 Soution4 Multible components\r\n\r\nimport \"./App.css\";\r\nimport Card from \"./Card\";\r\n\r\nfunction App() {\r\nreturn (\r\n    <div className=\"App\">\r\n        <h1>Task: Add three Card elements</h1>\r\n        <Card h2=\"First card\'s h2\" h3=\"First card\'s h3\" />\r\n        <Card h2=\"Second card\'s h2\" h3=\"Second card\'s h3\" />\r\n        <Card h2=\"Third card\'s h2\" h3=\"Third card\'s h3\" />\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default App;\r\n\r\nfunction Card(props) {\r\n  return (\r\n      <div className=\"card\">\r\n          <h2>{props.h2}</h2>\r\n          <h3>{props.h3}</h3>\r\n      </div>\r\n    );\r\n};\r\n\r\nexport default Card;\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(300,'Week2 Solution1 Dynamic Events\r\nfunction App() {\r\n\r\n    function handleClick() {\r\n      let randomNum = Math.floor(Math.random() * 3) + 1;\r\n      console.log(randomNum);\r\n      let userInput = prompt(\'type a number\');\r\n      alert(`Computer number: ${randomNum}, Your guess: ${userInput}`);\r\n    }\r\n  \r\n    return (\r\n      <div>\r\n        <h1>Task: Add a button and handle a click event</h1>\r\n        <button onClick={handleClick}>Guess the number between 1 and 3</button>\r\n      </div>\r\n    );\r\n  }\r\n  \r\n  export default App;\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(301,'Week2 Solution2 Manging state in react\r\nimport React from \"react\";\r\nimport Fruits from \"./Fruits\";\r\nimport FruitsCounter from \"./FruitsCounter\";\r\n\r\nfunction App() {\r\n  const [fruits] = React.useState([\r\n      {fruitName: \'apple\', id: 1},\r\n      {fruitName: \'apple\', id: 2},\r\n      {fruitName: \'plum\', id: 3},\r\n  ]);\r\n\r\n  return (\r\n    <div className=\"App\">\r\n      <h1>Where should the state go?</h1>\r\n      <Fruits fruits={fruits} />\r\n      <FruitsCounter fruits={fruits} />\r\n    </div>\r\n  );\r\n}\r\n\r\nexport default App;\r\n\r\n\r\nfunction Fruits(props) {\r\n  return (\r\n      <div>\r\n          {props.fruits.map(f => <p key={f.id}>{f.fruitName}</p>)}\r\n      </div>\r\n  )\r\n}\r\n\r\nexport default Fruits;\r\n\r\nfunction FruitsCounter(props) {\r\n  return (\r\n      <h2>Total fruits: {props.fruits.length}</h2>\r\n  )\r\n}\r\n\r\nexport default FruitsCounter;\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(302,'Week3 Solution1 Creatin a route\r\nfunction Contact() {\r\n  return  <h1>Contact Little Lemon on this page.</h1>\r\n}\r\nexport default Contact;\r\n\r\nimport \"./App.css\";\r\nimport Homepage from \"./Homepage\";\r\nimport AboutLittleLemon from \"./AboutLittleLemon\";\r\nimport Contact from \"./Contact\";\r\nimport { Routes, Route, Link } from \"react-router-dom\";\r\n\r\nfunction App() {\r\n  return (\r\n    <div> \r\n    <nav>\r\n      <Link to=\"/\" className=\"nav-item\">Homepage</Link>\r\n      <Link to=\"/about\" className=\"nav-item\">About Little Lemon</Link>\r\n      <Link to=\"/contact\" className=\"nav-item\">Contact</Link>\r\n    </nav>\r\n      <Routes> \r\n        <Route path=\"/\" element={<Homepage />}></Route>\r\n        <Route path=\"/about\" element={<AboutLittleLemon />}></Route>\r\n        <Route path=\"/contact\" element={<Contact />}></Route>\r\n      </Routes>\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default App;\r\n\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(303,'Week3 Solution2 Displaying images\r\nimport logo from\"./assets/logo.png\"\r\n\r\nfunction App() {\r\n  return (\r\n    <div className=\"App\">\r\n      <h1>Task: Add an image below</h1>\r\n      <img src={logo} alt=\"Logo\" />\r\n    </div>\r\n  );\r\n};\r\n\r\nexport default App;\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(304,'Week3 Solution3 Song selection\r\nimport React from \"react\"; \r\n \r\nfunction App() { \r\n \r\n  const bird1 = new Audio( \r\n    \"https://upload.wikimedia.org/wikipedia/commons/9/9b/Hydroprogne_caspia_-_Caspian_Tern_XC432679.mp3\" \r\n  ); \r\n \r\n  const bird2 = new Audio( \r\n    \"https://upload.wikimedia.org/wikipedia/commons/b/b5/Hydroprogne_caspia_-_Caspian_Tern_XC432881.mp3\" \r\n  ); \r\n \r\n  function toggle1() { \r\n    if (bird1.paused) { \r\n      bird1.play(); \r\n    } else { \r\n      bird1.pause(); \r\n    } \r\n  }; \r\n \r\n  function toggle2() { \r\n    if (bird2.paused) { \r\n      bird2.play(); \r\n    } else { \r\n      bird2.pause(); \r\n    } \r\n  }; \r\n \r\n  return ( \r\n    <div> \r\n      <button onClick={toggle1}>Caspian Tern 1</button> \r\n      <button onClick={toggle2}>Caspian Tern 2</button> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App;\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(305,'Week4 Solution1 Bulid a calculator app\r\nimport React, { useState, useRef } from \"react\"; \r\nimport \"./App.css\"; \r\n \r\nfunction App() { \r\n  const inputRef = useRef(null); \r\n  const resultRef = useRef(null); \r\n  const [result, setResult] = useState(0); \r\n \r\n  function plus(e) { \r\n    e.preventDefault(); \r\n    // const inputVal = inputRef.current.value; \r\n    // const newResult = result + Number(inputVal); \r\n    // setResult(newResult); \r\n    setResult((result) => result + Number(inputRef.current.value)); \r\n  } \r\n \r\n  function minus(e) { \r\n    e.preventDefault(); \r\n    const inputVal = inputRef.current.value; \r\n    const newResult = result - Number(inputVal); \r\n    setResult(newResult); \r\n  } \r\n \r\n  function times(e) { \r\n    e.preventDefault(); \r\n    const inputVal = inputRef.current.value; \r\n    const newResult = result * Number(inputVal); \r\n    setResult(newResult); \r\n  } \r\n \r\n  function divide(e) { \r\n    e.preventDefault(); \r\n    const inputVal = inputRef.current.value; \r\n    const newResult = result / Number(inputVal); \r\n    setResult(newResult); \r\n  } \r\n \r\n  function resetInput(e) { \r\n    e.preventDefault(); \r\n    inputRef.current.value = 0; \r\n  } \r\n \r\n  function resetResult(e) { \r\n    e.preventDefault(); \r\n    setResult(0); \r\n  } \r\n \r\n  return ( \r\n    <div className=\"App\"> \r\n      <div> \r\n        <h1>Simplest Working Calculator</h1> \r\n      </div> \r\n      <form> \r\n        <p ref={resultRef}>{result}</p> \r\n        <input \r\n          pattern=\"[0-9]\" \r\n          ref={inputRef} \r\n          type=\"number\" \r\n          placeholder=\"Type a number\" \r\n        /> \r\n        <button onClick={plus}>add</button> \r\n        <button onClick={minus}>subtract</button> \r\n        <button onClick={times}>multiply</button> \r\n        <button onClick={divide}>divide</button> \r\n        <button onClick={resetInput}>reset input</button> \r\n        <button onClick={resetResult}>reset result</button> \r\n      </form> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App;\r\n\r\n\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(306,'Calculator App\r\nApp.css\r\n* {\r\n  font-family: sans-serif;\r\n}\r\ninput,\r\nbutton {\r\n  font-size: 20px;\r\n  padding: 10px;\r\n  border-radius: 5px;\r\n}\r\ninput {\r\n  display: block;\r\n  margin-bottom: 20px;\r\n}\r\nbutton {\r\n  border: 1px solid gray;\r\n  background: whitesmoke;\r\n  margin-right: 5px;\r\n}\r\nbutton:nth-last-child(2),\r\nbutton:nth-last-child(1) {\r\n  background: tomato;\r\n  color: white;\r\n}\r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(307,'App.js\r\nimport {\r\n  useState,\r\n  useRef\r\n} from \"react\"; \r\nimport \"./App.css\";\r\n\r\nfunction App() { \r\n  const inputRef = useRef(null); \r\n  const resultRef = useRef(null); \r\n  const [result, setResult] = useState(0); \r\n \r\n  function plus(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result + Number(inputRef.current.value)); \r\n  }; \r\n\r\n  function minus(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result - Number(inputRef.current.value)); \r\n  }; \r\n\r\n  function times(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result * Number(inputRef.current.value)); \r\n  }; \r\n \r\n  function divide(e) { \r\n    e.preventDefault(); \r\n    setResult((result) => result / Number(inputRef.current.value)); \r\n  }; \r\n \r\n  function resetInput(e) { \r\n    e.preventDefault(); \r\n    inputRef.current.value=\"\";\r\n  }; \r\n \r\n  function resetResult(e) { \r\n    e.preventDefault(); \r\n    setResult(0);\r\n  }; \r\n \r\n  return ( \r\n    <div className=\"App\"> \r\n      <div> \r\n        <h1>Simplest Working Calculator</h1> \r\n      </div> \r\n      <form> \r\n        <p ref={resultRef}> \r\n          {result} \r\n        </p> \r\n        <input\r\n          pattern=\"[0-9]\" \r\n          ref={inputRef} \r\n          type=\"number\" \r\n          placeholder=\"Type a number\" \r\n        /> \r\n        <button onClick={plus}>add</button> \r\n        <button onClick={minus}>subtract</button> \r\n        <button onClick={times}>multiply</button> \r\n        <button onClick={divide}>divide</button> \r\n        <button onClick={resetInput}>reset input</button> \r\n        <button onClick={resetResult}>reset result</button> \r\n      </form> \r\n    </div> \r\n  ); \r\n} \r\n \r\nexport default App; \r\n\r\n','2024-02-09 02:15:34','2024-02-09 02:15:34'),(308,'Index.js\r\nimport React from \'react\';\r\nimport ReactDOM from \'react-dom/client\';\r\nimport \'./index.css\';\r\nimport App from \'./App\';\r\nimport reportWebVitals from \'./reportWebVitals\';\r\n\r\nconst root = ReactDOM.createRoot(document.getElementById(\'root\'));\r\nroot.render(\r\n  <React.StrictMode>\r\n    <App />\r\n  </React.StrictMode>\r\n);\r\n\r\n// If you want to start measuring performance in your app, pass a function\r\n// to log results (for example: reportWebVitals(console.log))\r\n// or send to an analytics endpoint. Learn more: https://bit.ly/CRA-vitals\r\nreportWebVitals();','2024-02-09 02:15:34','2024-02-09 02:15:34'),(310,'Packages and resources\r\nReact Native Dev Environment Setup\r\nDownload Node.js\r\nThe Missing Package Manager for macOS (or Linux) — Homebrew\r\nWatchman A file watching service | Watchman (facebook.github.io)\r\nDownload Visual Studio Code - Mac, Linux, Windows\r\nDownload Android Studio & App Tools - Android Developers\r\nXcode on the Mac App Store (apple.com)\r\nCocoaPods Guides - Getting Started\r\nSetting up the development environment\r\nSetting up the development environment · React Native\r\nFirst 