pen only once - while scrolling down\r\n         mirror: false, // whether elements should animate out while scrolling past them\r\n         anchorPlacement: \'top-bottom\', // defines which position of the element regarding to window should trigger the animation\r\n\r\n     });\r\n </script>','2024-02-09 13:32:54','2024-02-09 13:32:54'),(345,'<!-- Vision Start -->\r\n <div class=\"container-fluid py-5 wow fadeInUp\" data-wow-delay=\"0.1s\" id=\"vision\" data-aos=\"zoom-in\">\r\n    <div class=\"container\">\r\n        <div class=\"row g-5 visionmission-boxshadow\">\r\n            <div class=\"col-lg-7\">\r\n                <div class=\"section-title mb-4\">\r\n                    <h5 class=\"position-relative d-inline-block text-primary text-uppercase\">{{ __(\'general.vision\') }}</h5>\r\n                    <h3 class=\" mb-0\">{{ page(\'vision\')->title }}</h3>\r\n                </div>\r\n                <h5 class=\"text-body fst-italic mb-4\">{{ page(\'vision\')->subtitle }}</h5>\r\n                <div class=\"mb-4 description\">{!!  page(\'vision\')->description  !!}</div>\r\n                {{-- <div class=\"row g-3\">\r\n                    <div class=\"col-sm-6 wow zoomIn\" data-wow-delay=\"0.3s\">\r\n                        <h5 class=\"mb-3\"><i class=\"fa fa-check-circle text-primary me-3\"></i>Award Winning</h5>\r\n                        <h5 class=\"mb-3\"><i class=\"fa fa-check-circle text-primary me-3\"></i>Professional Staff</h5>\r\n                    </div>\r\n                    <div class=\"col-sm-6 wow zoomIn\" data-wow-delay=\"0.6s\">\r\n                        <h5 class=\"mb-3\"><i class=\"fa fa-check-circle text-primary me-3\"></i>24/7 Opened</h5>\r\n                        <h5 class=\"mb-3\"><i class=\"fa fa-check-circle text-primary me-3\"></i>Fair Prices</h5>\r\n                    </div>\r\n                </div> --}}\r\n                {{-- <a href=\"{{route(\'user.login-view\')}}\" class=\"btn btn-primary py-3 px-5 mt-4 wow zoomIn\" da